INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 3, E'Giving no offence in any thing, that the ministry be not blamed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 4, E'But in all things approving ourselves as the ministers of God, in much patience, in afflictions, in necessities, in distresses,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 5, E'In stripes, in imprisonments, in tumults, in labours, in watchings, in fastings;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 6, E'By pureness, by knowledge, by longsuffering, by kindness, by the Holy Ghost, by love unfeigned,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 7, E'By the word of truth, by the power of God, by the armour of righteousness on the right hand and on the left,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 8, E'By honour and dishonour, by evil report and good report: as deceivers, and yet true;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 9, E'As unknown, and yet well known; as dying, and, behold, we live; as chastened, and not killed;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 10, E'As sorrowful, yet alway rejoicing; as poor, yet making many rich; as having nothing, and yet possessing all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 11, E'O ye Corinthians, our mouth is open unto you, our heart is enlarged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 12, E'Ye are not straitened in us, but ye are straitened in your own bowels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 13, E'Now for a recompence in the same, (I speak as unto my children,) be ye also enlarged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 14, E'Be ye not unequally yoked together with unbelievers: for what fellowship hath righteousness with unrighteousness? and what communion hath light with darkness?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 15, E'And what concord hath Christ with Belial? or what part hath he that believeth with an infidel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 16, E'And what agreement hath the temple of God with idols? for ye are the temple of the living God; as God hath said, I will dwell in them, and walk in them; and I will be their God, and they shall be my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 17, E'Wherefore come out from among them, and be ye separate, saith the Lord, and touch not the unclean thing; and I will receive you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 6, 18, E'And will be a Father unto you, and ye shall be my sons and daughters, saith the Lord Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 1, E'Having therefore these promises, dearly beloved, let us cleanse ourselves from all filthiness of the flesh and spirit, perfecting holiness in the fear of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 2, E'Receive us; we have wronged no man, we have corrupted no man, we have defrauded no man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 3, E'I speak not this to condemn you: for I have said before, that ye are in our hearts to die and live with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 4, E'Great is my boldness of speech toward you, great is my glorying of you: I am filled with comfort, I am exceeding joyful in all our tribulation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 5, E'For, when we were come into Macedonia, our flesh had no rest, but we were troubled on every side; without were fightings, within were fears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 6, E'Nevertheless God, that comforteth those that are cast down, comforted us by the coming of Titus;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 7, E'And not by his coming only, but by the consolation wherewith he was comforted in you, when he told us your earnest desire, your mourning, your fervent mind toward me; so that I rejoiced the more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 8, E'For though I made you sorry with a letter, I do not repent, though I did repent: for I perceive that the same epistle hath made you sorry, though it were but for a season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 9, E'Now I rejoice, not that ye were made sorry, but that ye sorrowed to repentance: for ye were made sorry after a godly manner, that ye might receive damage by us in nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 10, E'For godly sorrow worketh repentance to salvation not to be repented of: but the sorrow of the world worketh death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 11, E'For behold this selfsame thing, that ye sorrowed after a godly sort, what carefulness it wrought in you, yea, what clearing of yourselves, yea, what indignation, yea, what fear, yea, what vehement desire, yea, what zeal, yea, what revenge! In all things ye have approved yourselves to be clear in this matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 12, E'Wherefore, though I wrote unto you, I did it not for his cause that had done the wrong, nor for his cause that suffered wrong, but that our care for you in the sight of God might appear unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 13, E'Therefore we were comforted in your comfort: yea, and exceedingly the more joyed we for the joy of Titus, because his spirit was refreshed by you all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 14, E'For if I have boasted any thing to him of you, I am not ashamed; but as we spake all things to you in truth, even so our boasting, which I made before Titus, is found a truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 15, E'And his inward affection is more abundant toward you, whilst he remembereth the obedience of you all, how with fear and trembling ye received him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 7, 16, E'I rejoice therefore that I have confidence in you in all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 1, E'Moreover, brethren, we do you to wit of the grace of God bestowed on the churches of Macedonia;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 2, E'How that in a great trial of affliction the abundance of their joy and their deep poverty abounded unto the riches of their liberality.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 3, E'For to their power, I bear record, yea, and beyond their power they were willing of themselves;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 4, E'Praying us with much intreaty that we would receive the gift, and take upon us the fellowship of the ministering to the saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 5, E'And this they did, not as we hoped, but first gave their own selves to the Lord, and unto us by the will of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 6, E'Insomuch that we desired Titus, that as he had begun, so he would also finish in you the same grace also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 7, E'Therefore, as ye abound in every thing, in faith, and utterance, and knowledge, and in all diligence, and in your love to us, see that ye abound in this grace also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 8, E'I speak not by commandment, but by occasion of the forwardness of others, and to prove the sincerity of your love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 9, E'For ye know the grace of our Lord Jesus Christ, that, though he was rich, yet for your sakes he became poor, that ye through his poverty might be rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 10, E'And herein I give my advice: for this is expedient for you, who have begun before, not only to do, but also to be forward a year ago.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 11, E'Now therefore perform the doing of it; that as there was a readiness to will, so there may be a performance also out of that which ye have.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 12, E'For if there be first a willing mind, it is accepted according to that a man hath, and not according to that he hath not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 13, E'For I mean not that other men be eased, and ye burdened:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 14, E'But by an equality, that now at this time your abundance may be a supply for their want, that their abundance also may be a supply for your want: that there may be equality:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 15, E'As it is written, He that had gathered much had nothing over; and he that had gathered little had no lack.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 16, E'But thanks be to God, which put the same earnest care into the heart of Titus for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 17, E'For indeed he accepted the exhortation; but being more forward, of his own accord he went unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 18, E'And we have sent with him the brother, whose praise is in the gospel throughout all the churches;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 19, E'And not that only, but who was also chosen of the churches to travel with us with this grace, which is administered by us to the glory of the same Lord, and declaration of your ready mind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 20, E'Avoiding this, that no man should blame us in this abundance which is administered by us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 21, E'Providing for honest things, not only in the sight of the Lord, but also in the sight of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 22, E'And we have sent with them our brother, whom we have oftentimes proved diligent in many things, but now much more diligent, upon the great confidence which I have in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 23, E'Whether any do enquire of Titus, he is my partner and fellowhelper concerning you: or our brethren be enquired of, they are the messengers of the churches, and the glory of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 8, 24, E'Wherefore shew ye to them, and before the churches, the proof of your love, and of our boasting on your behalf.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 1, E'For as touching the ministering to the saints, it is superfluous for me to write to you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 2, E'For I know the forwardness of your mind, for which I boast of you to them of Macedonia, that Achaia was ready a year ago; and your zeal hath provoked very many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 3, E'Yet have I sent the brethren, lest our boasting of you should be in vain in this behalf; that, as I said, ye may be ready:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 4, E'Lest haply if they of Macedonia come with me, and find you unprepared, we (that we say not, ye) should be ashamed in this same confident boasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 5, E'Therefore I thought it necessary to exhort the brethren, that they would go before unto you, and make up beforehand your bounty, whereof ye had notice before, that the same might be ready, as a matter of bounty, and not as of covetousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 6, E'But this I say, He which soweth sparingly shall reap also sparingly; and he which soweth bountifully shall reap also bountifully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 7, E'Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 8, E'And God is able to make all grace abound toward you; that ye, always having all sufficiency in all things, may abound to every good work:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 9, E'(As it is written, He hath dispersed abroad; he hath given to the poor: his righteousness remaineth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 10, E'Now he that ministereth seed to the sower both minister bread for your food, and multiply your seed sown, and increase the fruits of your righteousness;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 11, E'Being enriched in every thing to all bountifulness, which causeth through us thanksgiving to God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 12, E'For the administration of this service not only supplieth the want of the saints, but is abundant also by many thanksgivings unto God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 13, E'Whiles by the experiment of this ministration they glorify God for your professed subjection unto the gospel of Christ, and for your liberal distribution unto them, and unto all men;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 14, E'And by their prayer for you, which long after you for the exceeding grace of God in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 9, 15, E'Thanks be unto God for his unspeakable gift.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 1, E'Now I Paul myself beseech you by the meekness and gentleness of Christ, who in presence am base among you, but being absent am bold toward you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 2, E'But I beseech you, that I may not be bold when I am present with that confidence, wherewith I think to be bold against some, which think of us as if we walked according to the flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 3, E'For though we walk in the flesh, we do not war after the flesh:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 4, E'(For the weapons of our warfare are not carnal, but mighty through God to the pulling down of strong holds;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 5, E'Casting down imaginations, and every high thing that exalteth itself against the knowledge of God, and bringing into captivity every thought to the obedience of Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 6, E'And having in a readiness to revenge all disobedience, when your obedience is fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 7, E'Do ye look on things after the outward appearance? If any man trust to himself that he is Christâ€™s, let him of himself think this again, that, as he is Christâ€™s, even so are we Christâ€™s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 8, E'For though I should boast somewhat more of our authority, which the Lord hath given us for edification, and not for your destruction, I should not be ashamed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 9, E'That I may not seem as if I would terrify you by letters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 10, E'For his letters, say they, are weighty and powerful; but his bodily presence is weak, and his speech contemptible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 11, E'Let such an one think this, that, such as we are in word by letters when we are absent, such will we be also in deed when we are present.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 12, E'For we dare not make ourselves of the number, or compare ourselves with some that commend themselves: but they measuring themselves by themselves, and comparing themselves among themselves, are not wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 13, E'But we will not boast of things without our measure, but according to the measure of the rule which God hath distributed to us, a measure to reach even unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 14, E'For we stretch not ourselves beyond our measure, as though we reached not unto you: for we are come as far as to you also in preaching the gospel of Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 15, E'Not boasting of things without our measure, that is, of other menâ€™s labours; but having hope, when your faith is increased, that we shall be enlarged by you according to our rule abundantly,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 16, E'To preach the gospel in the regions beyond you, and not to boast in another manâ€™s line of things made ready to our hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 17, E'But he that glorieth, let him glory in the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 10, 18, E'For not he that commendeth himself is approved, but whom the Lord commendeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 1, E'Would to God ye could bear with me a little in my folly: and indeed bear with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 2, E'For I am jealous over you with godly jealousy: for I have espoused you to one husband, that I may present you as a chaste virgin to Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 3, E'But I fear, lest by any means, as the serpent beguiled Eve through his subtilty, so your minds should be corrupted from the simplicity that is in Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 4, E'For if he that cometh preacheth another Jesus, whom we have not preached, or if ye receive another spirit, which ye have not received, or another gospel, which ye have not accepted, ye might well bear with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 5, E'For I suppose I was not a whit behind the very chiefest apostles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 6, E'But though I be rude in speech, yet not in knowledge; but we have been throughly made manifest among you in all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 7, E'Have I committed an offence in abasing myself that ye might be exalted, because I have preached to you the gospel of God freely?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 8, E'I robbed other churches, taking wages of them, to do you service.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 9, E'And when I was present with you, and wanted, I was chargeable to no man: for that which was lacking to me the brethren which came from Macedonia supplied: and in all things I have kept myself from being burdensome unto you, and so will I keep myself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 10, E'As the truth of Christ is in me, no man shall stop me of this boasting in the regions of Achaia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 11, E'Wherefore? because I love you not? God knoweth.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Corinthians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 12, E'But what I do, that I will do, that I may cut off occasion from them which desire occasion; that wherein they glory, they may be found even as we.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 13, E'For such are false apostles, deceitful workers, transforming themselves into the apostles of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 14, E'And no marvel; for Satan himself is transformed into an angel of light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 15, E'Therefore it is no great thing if his ministers also be transformed as the ministers of righteousness; whose end shall be according to their works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 16, E'I say again, Let no man think me a fool; if otherwise, yet as a fool receive me, that I may boast myself a little.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 17, E'That which I speak, I speak it not after the Lord, but as it were foolishly, in this confidence of boasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 18, E'Seeing that many glory after the flesh, I will glory also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 19, E'For ye suffer fools gladly, seeing ye yourselves are wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 20, E'For ye suffer, if a man bring you into bondage, if a man devour you, if a man take of you, if a man exalt himself, if a man smite you on the face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 21, E'I speak as concerning reproach, as though we had been weak. Howbeit whereinsoever any is bold, (I speak foolishly,) I am bold also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 22, E'Are they Hebrews? so am I. Are they Israelites? so am I. Are they the seed of Abraham? so am I.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 23, E'Are they ministers of Christ? (I speak as a fool) I am more; in labours more abundant, in stripes above measure, in prisons more frequent, in deaths oft.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 24, E'Of the Jews five times received I forty stripes save one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 25, E'Thrice was I beaten with rods, once was I stoned, thrice I suffered shipwreck, a night and a day I have been in the deep;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 26, E'In journeyings often, in perils of waters, in perils of robbers, in perils by mine own countrymen, in perils by the heathen, in perils in the city, in perils in the wilderness, in perils in the sea, in perils among false brethren;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 27, E'In weariness and painfulness, in watchings often, in hunger and thirst, in fastings often, in cold and nakedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 28, E'Beside those things that are without, that which cometh upon me daily, the care of all the churches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 29, E'Who is weak, and I am not weak? who is offended, and I burn not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 30, E'If I must needs glory, I will glory of the things which concern mine infirmities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 31, E'The God and Father of our Lord Jesus Christ, which is blessed for evermore, knoweth that I lie not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 32, E'In Damascus the governor under Aretas the king kept the city of the Damascenes with a garrison, desirous to apprehend me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 11, 33, E'And through a window in a basket was I let down by the wall, and escaped his hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 1, E'It is not expedient for me doubtless to glory. I will come to visions and revelations of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 2, E'I knew a man in Christ above fourteen years ago, (whether in the body, I cannot tell; or whether out of the body, I cannot tell: God knoweth;) such an one caught up to the third heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 3, E'And I knew such a man, (whether in the body, or out of the body, I cannot tell: God knoweth;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 4, E'How that he was caught up into paradise, and heard unspeakable words, which it is not lawful for a man to utter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 5, E'Of such an one will I glory: yet of myself I will not glory, but in mine infirmities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 6, E'For though I would desire to glory, I shall not be a fool; for I will say the truth: but now I forbear, lest any man should think of me above that which he seeth me to be, or that he heareth of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 7, E'And lest I should be exalted above measure through the abundance of the revelations, there was given to me a thorn in the flesh, the messenger of Satan to buffet me, lest I should be exalted above measure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 8, E'For this thing I besought the Lord thrice, that it might depart from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 9, E'And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 10, E'Therefore I take pleasure in infirmities, in reproaches, in necessities, in persecutions, in distresses for Christâ€™s sake: for when I am weak, then am I strong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 11, E'I am become a fool in glorying; ye have compelled me: for I ought to have been commended of you: for in nothing am I behind the very chiefest apostles, though I be nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 12, E'Truly the signs of an apostle were wrought among you in all patience, in signs, and wonders, and mighty deeds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 13, E'For what is it wherein ye were inferior to other churches, except it be that I myself was not burdensome to you? forgive me this wrong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 14, E'Behold, the third time I am ready to come to you; and I will not be burdensome to you: for I seek not yours, but you: for the children ought not to lay up for the parents, but the parents for the children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 15, E'And I will very gladly spend and be spent for you; though the more abundantly I love you, the less I be loved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 16, E'But be it so, I did not burden you: nevertheless, being crafty, I caught you with guile.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 17, E'Did I make a gain of you by any of them whom I sent unto you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 18, E'I desired Titus, and with him I sent a brother. Did Titus make a gain of you? walked we not in the same spirit? walked we not in the same steps?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 19, E'Again, think ye that we excuse ourselves unto you? we speak before God in Christ: but we do all things, dearly beloved, for your edifying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 20, E'For I fear, lest, when I come, I shall not find you such as I would, and that I shall be found unto you such as ye would not: lest there be debates, envyings, wraths, strifes, backbitings, whisperings, swellings, tumults:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 12, 21, E'And lest, when I come again, my God will humble me among you, and that I shall bewail many which have sinned already, and have not repented of the uncleanness and fornication and lasciviousness which they have committed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 1, E'This is the third time I am coming to you. In the mouth of two or three witnesses shall every word be established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 2, E'I told you before, and foretell you, as if I were present, the second time; and being absent now I write to them which heretofore have sinned, and to all other, that, if I come again, I will not spare:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 3, E'Since ye seek a proof of Christ speaking in me, which to you-ward is not weak, but is mighty in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 4, E'For though he was crucified through weakness, yet he liveth by the power of God. For we also are weak in him, but we shall live with him by the power of God toward you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 5, E'Examine yourselves, whether ye be in the faith; prove your own selves. Know ye not your own selves, how that Jesus Christ is in you, except ye be reprobates?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 6, E'But I trust that ye shall know that we are not reprobates.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 7, E'Now I pray to God that ye do no evil; not that we should appear approved, but that ye should do that which is honest, though we be as reprobates.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 8, E'For we can do nothing against the truth, but for the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 9, E'For we are glad, when we are weak, and ye are strong: and this also we wish, even your perfection.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 10, E'Therefore I write these things being absent, lest being present I should use sharpness, according to the power which the Lord hath given me to edification, and not to destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 11, E'Finally, brethren, farewell. Be perfect, be of good comfort, be of one mind, live in peace; and the God of love and peace shall be with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 12, E'Greet one another with an holy kiss.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 13, E'All the saints salute you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9cff383a-f2c8-449d-ade6-60f31010f1e0', 13, 14, E'The grace of the Lord Jesus Christ, and the love of God, and the communion of the Holy Ghost, be with you all. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Corinthians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 1, E'Paul, an apostle, (not of men, neither by man, but by Jesus Christ, and God the Father, who raised him from the dead;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 2, E'And all the brethren which are with me, unto the churches of Galatia:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 3, E'Grace be to you and peace from God the Father, and from our Lord Jesus Christ,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 4, E'Who gave himself for our sins, that he might deliver us from this present evil world, according to the will of God and our Father:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 5, E'To whom be glory for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 6, E'I marvel that ye are so soon removed from him that called you into the grace of Christ unto another gospel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 7, E'Which is not another; but there be some that trouble you, and would pervert the gospel of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 8, E'But though we, or an angel from heaven, preach any other gospel unto you than that which we have preached unto you, let him be accursed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 9, E'As we said before, so say I now again, If any man preach any other gospel unto you than that ye have received, let him be accursed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 10, E'For do I now persuade men, or God? or do I seek to please men? for if I yet pleased men, I should not be the servant of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 11, E'But I certify you, brethren, that the gospel which was preached of me is not after man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 12, E'For I neither received it of man, neither was I taught it, but by the revelation of Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 13, E'For ye have heard of my conversation in time past in the Jewsâ€™ religion, how that beyond measure I persecuted the church of God, and wasted it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 14, E'And profited in the Jewsâ€™ religion above many my equals in mine own nation, being more exceedingly zealous of the traditions of my fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 15, E'But when it pleased God, who separated me from my motherâ€™s womb, and called me by his grace,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 16, E'To reveal his Son in me, that I might preach him among the heathen; immediately I conferred not with flesh and blood:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 17, E'Neither went I up to Jerusalem to them which were apostles before me; but I went into Arabia, and returned again unto Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 18, E'Then after three years I went up to Jerusalem to see Peter, and abode with him fifteen days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 19, E'But other of the apostles saw I none, save James the Lordâ€™s brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 20, E'Now the things which I write unto you, behold, before God, I lie not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 21, E'Afterwards I came into the regions of Syria and Cilicia;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 22, E'And was unknown by face unto the churches of Judaea which were in Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 23, E'But they had heard only, That he which persecuted us in times past now preacheth the faith which once he destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 1, 24, E'And they glorified God in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 1, E'Then fourteen years after I went up again to Jerusalem with Barnabas, and took Titus with me also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 2, E'And I went up by revelation, and communicated unto them that gospel which I preach among the Gentiles, but privately to them which were of reputation, lest by any means I should run, or had run, in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 3, E'But neither Titus, who was with me, being a Greek, was compelled to be circumcised:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 4, E'And that because of false brethren unawares brought in, who came in privily to spy out our liberty which we have in Christ Jesus, that they might bring us into bondage:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 5, E'To whom we gave place by subjection, no, not for an hour; that the truth of the gospel might continue with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 6, E'But of these who seemed to be somewhat, (whatsoever they were, it maketh no matter to me: God accepteth no manâ€™s person:) for they who seemed to be somewhat in conference added nothing to me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 7, E'But contrariwise, when they saw that the gospel of the uncircumcision was committed unto me, as the gospel of the circumcision was unto Peter;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 8, E'(For he that wrought effectually in Peter to the apostleship of the circumcision, the same was mighty in me toward the Gentiles:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 9, E'And when James, Cephas, and John, who seemed to be pillars, perceived the grace that was given unto me, they gave to me and Barnabas the right hands of fellowship; that we should go unto the heathen, and they unto the circumcision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 10, E'Only they would that we should remember the poor; the same which I also was forward to do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 11, E'But when Peter was come to Antioch, I withstood him to the face, because he was to be blamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 12, E'For before that certain came from James, he did eat with the Gentiles: but when they were come, he withdrew and separated himself, fearing them which were of the circumcision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 13, E'And the other Jews dissembled likewise with him; insomuch that Barnabas also was carried away with their dissimulation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 14, E'But when I saw that they walked not uprightly according to the truth of the gospel, I said unto Peter before them all, If thou, being a Jew, livest after the manner of Gentiles, and not as do the Jews, why compellest thou the Gentiles to live as do the Jews?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 15, E'We who are Jews by nature, and not sinners of the Gentiles,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 16, E'Knowing that a man is not justified by the works of the law, but by the faith of Jesus Christ, even we have believed in Jesus Christ, that we might be justified by the faith of Christ, and not by the works of the law: for by the works of the law shall no flesh be justified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 17, E'But if, while we seek to be justified by Christ, we ourselves also are found sinners, is therefore Christ the minister of sin? God forbid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 18, E'For if I build again the things which I destroyed, I make myself a transgressor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 19, E'For I through the law am dead to the law, that I might live unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 20, E'I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 2, 21, E'I do not frustrate the grace of God: for if righteousness come by the law, then Christ is dead in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 1, E'O foolish Galatians, who hath bewitched you, that ye should not obey the truth, before whose eyes Jesus Christ hath been evidently set forth, crucified among you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 2, E'This only would I learn of you, Received ye the Spirit by the works of the law, or by the hearing of faith?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 3, E'Are ye so foolish? having begun in the Spirit, are ye now made perfect by the flesh?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 4, E'Have ye suffered so many things in vain? if it be yet in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 5, E'He therefore that ministereth to you the Spirit, and worketh miracles among you, doeth he it by the works of the law, or by the hearing of faith?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 6, E'Even as Abraham believed God, and it was accounted to him for righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 7, E'Know ye therefore that they which are of faith, the same are the children of Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 8, E'And the scripture, foreseeing that God would justify the heathen through faith, preached before the gospel unto Abraham, saying, In thee shall all nations be blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 9, E'So then they which be of faith are blessed with faithful Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 10, E'For as many as are of the works of the law are under the curse: for it is written, Cursed is every one that continueth not in all things which are written in the book of the law to do them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 11, E'But that no man is justified by the law in the sight of God, it is evident: for, The just shall live by faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 12, E'And the law is not of faith: but, The man that doeth them shall live in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 13, E'Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 14, E'That the blessing of Abraham might come on the Gentiles through Jesus Christ; that we might receive the promise of the Spirit through faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 15, E'Brethren, I speak after the manner of men; Though it be but a manâ€™s covenant, yet if it be confirmed, no man disannulleth, or addeth thereto.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 16, E'Now to Abraham and his seed were the promises made. He saith not, And to seeds, as of many; but as of one, And to thy seed, which is Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 17, E'And this I say, that the covenant, that was confirmed before of God in Christ, the law, which was four hundred and thirty years after, cannot disannul, that it should make the promise of none effect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 18, E'For if the inheritance be of the law, it is no more of promise: but God gave it to Abraham by promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 19, E'Wherefore then serveth the law? It was added because of transgressions, till the seed should come to whom the promise was made; and it was ordained by angels in the hand of a mediator.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 20, E'Now a mediator is not a mediator of one, but God is one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 21, E'Is the law then against the promises of God? God forbid: for if there had been a law given which could have given life, verily righteousness should have been by the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 22, E'But the scripture hath concluded all under sin, that the promise by faith of Jesus Christ might be given to them that believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 23, E'But before faith came, we were kept under the law, shut up unto the faith which should afterwards be revealed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 24, E'Wherefore the law was our schoolmaster to bring us unto Christ, that we might be justified by faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 25, E'But after that faith is come, we are no longer under a schoolmaster.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 26, E'For ye are all the children of God by faith in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 27, E'For as many of you as have been baptized into Christ have put on Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 28, E'There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 3, 29, E'And if ye be Christâ€™s, then are ye Abrahamâ€™s seed, and heirs according to the promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 1, E'Now I say, That the heir, as long as he is a child, differeth nothing from a servant, though he be lord of all;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 2, E'But is under tutors and governors until the time appointed of the father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 3, E'Even so we, when we were children, were in bondage under the elements of the world:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 4, E'But when the fulness of the time was come, God sent forth his Son, made of a woman, made under the law,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 5, E'To redeem them that were under the law, that we might receive the adoption of sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 6, E'And because ye are sons, God hath sent forth the Spirit of his Son into your hearts, crying, Abba, Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 7, E'Wherefore thou art no more a servant, but a son; and if a son, then an heir of God through Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 8, E'Howbeit then, when ye knew not God, ye did service unto them which by nature are no gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 9, E'But now, after that ye have known God, or rather are known of God, how turn ye again to the weak and beggarly elements, whereunto ye desire again to be in bondage?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 10, E'Ye observe days, and months, and times, and years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 11, E'I am afraid of you, lest I have bestowed upon you labour in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 12, E'Brethren, I beseech you, be as I am; for I am as ye are: ye have not injured me at all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 13, E'Ye know how through infirmity of the flesh I preached the gospel unto you at the first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 14, E'And my temptation which was in my flesh ye despised not, nor rejected; but received me as an angel of God, even as Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 15, E'Where is then the blessedness ye spake of? for I bear you record, that, if it had been possible, ye would have plucked out your own eyes, and have given them to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 16, E'Am I therefore become your enemy, because I tell you the truth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 17, E'They zealously affect you, but not well; yea, they would exclude you, that ye might affect them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 18, E'But it is good to be zealously affected always in a good thing, and not only when I am present with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 19, E'My little children, of whom I travail in birth again until Christ be formed in you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 20, E'I desire to be present with you now, and to change my voice; for I stand in doubt of you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 21, E'Tell me, ye that desire to be under the law, do ye not hear the law?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 22, E'For it is written, that Abraham had two sons, the one by a bondmaid, the other by a freewoman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 23, E'But he who was of the bondwoman was born after the flesh; but he of the freewoman was by promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 24, E'Which things are an allegory: for these are the two covenants; the one from the mount Sinai, which gendereth to bondage, which is Agar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 25, E'For this Agar is mount Sinai in Arabia, and answereth to Jerusalem which now is, and is in bondage with her children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 26, E'But Jerusalem which is above is free, which is the mother of us all.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Galatians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 27, E'For it is written, Rejoice, thou barren that bearest not; break forth and cry, thou that travailest not: for the desolate hath many more children than she which hath an husband.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 28, E'Now we, brethren, as Isaac was, are the children of promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 29, E'But as then he that was born after the flesh persecuted him that was born after the Spirit, even so it is now.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 30, E'Nevertheless what saith the scripture? Cast out the bondwoman and her son: for the son of the bondwoman shall not be heir with the son of the freewoman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 4, 31, E'So then, brethren, we are not children of the bondwoman, but of the free.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 1, E'Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 2, E'Behold, I Paul say unto you, that if ye be circumcised, Christ shall profit you nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 3, E'For I testify again to every man that is circumcised, that he is a debtor to do the whole law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 4, E'Christ is become of no effect unto you, whosoever of you are justified by the law; ye are fallen from grace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 5, E'For we through the Spirit wait for the hope of righteousness by faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 6, E'For in Jesus Christ neither circumcision availeth any thing, nor uncircumcision; but faith which worketh by love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 7, E'Ye did run well; who did hinder you that ye should not obey the truth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 8, E'This persuasion cometh not of him that calleth you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 9, E'A little leaven leaveneth the whole lump.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 10, E'I have confidence in you through the Lord, that ye will be none otherwise minded: but he that troubleth you shall bear his judgment, whosoever he be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 11, E'And I, brethren, if I yet preach circumcision, why do I yet suffer persecution? then is the offence of the cross ceased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 12, E'I would they were even cut off which trouble you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 13, E'For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 14, E'For all the law is fulfilled in one word, even in this; Thou shalt love thy neighbour as thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 15, E'But if ye bite and devour one another, take heed that ye be not consumed one of another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 16, E'This I say then, Walk in the Spirit, and ye shall not fulfil the lust of the flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 17, E'For the flesh lusteth against the Spirit, and the Spirit against the flesh: and these are contrary the one to the other: so that ye cannot do the things that ye would.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 18, E'But if ye be led of the Spirit, ye are not under the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 19, E'Now the works of the flesh are manifest, which are these; Adultery, fornication, uncleanness, lasciviousness,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 20, E'Idolatry, witchcraft, hatred, variance, emulations, wrath, strife, seditions, heresies,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 21, E'Envyings, murders, drunkenness, revellings, and such like: of the which I tell you before, as I have also told you in time past, that they which do such things shall not inherit the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 22, E'But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 23, E'Meekness, temperance: against such there is no law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 24, E'And they that are Christâ€™s have crucified the flesh with the affections and lusts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 25, E'If we live in the Spirit, let us also walk in the Spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 5, 26, E'Let us not be desirous of vain glory, provoking one another, envying one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 1, E'Brethren, if a man be overtaken in a fault, ye which are spiritual, restore such an one in the spirit of meekness; considering thyself, lest thou also be tempted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 2, E'Bear ye one anotherâ€™s burdens, and so fulfil the law of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 3, E'For if a man think himself to be something, when he is nothing, he deceiveth himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 4, E'But let every man prove his own work, and then shall he have rejoicing in himself alone, and not in another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 5, E'For every man shall bear his own burden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 6, E'Let him that is taught in the word communicate unto him that teacheth in all good things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 7, E'Be not deceived; God is not mocked: for whatsoever a man soweth, that shall he also reap.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 8, E'For he that soweth to his flesh shall of the flesh reap corruption; but he that soweth to the Spirit shall of the Spirit reap life everlasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 9, E'And let us not be weary in well doing: for in due season we shall reap, if we faint not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 10, E'As we have therefore opportunity, let us do good unto all men, especially unto them who are of the household of faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 11, E'Ye see how large a letter I have written unto you with mine own hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 12, E'As many as desire to make a fair shew in the flesh, they constrain you to be circumcised; only lest they should suffer persecution for the cross of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 13, E'For neither they themselves who are circumcised keep the law; but desire to have you circumcised, that they may glory in your flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 14, E'But God forbid that I should glory, save in the cross of our Lord Jesus Christ, by whom the world is crucified unto me, and I unto the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 15, E'For in Christ Jesus neither circumcision availeth any thing, nor uncircumcision, but a new creature.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 16, E'And as many as walk according to this rule, peace be on them, and mercy, and upon the Israel of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 17, E'From henceforth let no man trouble me: for I bear in my body the marks of the Lord Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5b5f8404-2230-4792-8c37-148a927a52fa', 6, 18, E'Brethren, the grace of our Lord Jesus Christ be with your spirit. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Galatians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 1, E'Paul, an apostle of Jesus Christ by the will of God, to the saints which are at Ephesus, and to the faithful in Christ Jesus:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 2, E'Grace be to you, and peace, from God our Father, and from the Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 3, E'Blessed be the God and Father of our Lord Jesus Christ, who hath blessed us with all spiritual blessings in heavenly places in Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 4, E'According as he hath chosen us in him before the foundation of the world, that we should be holy and without blame before him in love:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 5, E'Having predestinated us unto the adoption of children by Jesus Christ to himself, according to the good pleasure of his will,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 6, E'To the praise of the glory of his grace, wherein he hath made us accepted in the beloved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 7, E'In whom we have redemption through his blood, the forgiveness of sins, according to the riches of his grace;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 8, E'Wherein he hath abounded toward us in all wisdom and prudence;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 9, E'Having made known unto us the mystery of his will, according to his good pleasure which he hath purposed in himself:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 10, E'That in the dispensation of the fulness of times he might gather together in one all things in Christ, both which are in heaven, and which are on earth; even in him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 11, E'In whom also we have obtained an inheritance, being predestinated according to the purpose of him who worketh all things after the counsel of his own will:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 12, E'That we should be to the praise of his glory, who first trusted in Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 13, E'In whom ye also trusted, after that ye heard the word of truth, the gospel of your salvation: in whom also after that ye believed, ye were sealed with that holy Spirit of promise,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 14, E'Which is the earnest of our inheritance until the redemption of the purchased possession, unto the praise of his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 15, E'Wherefore I also, after I heard of your faith in the Lord Jesus, and love unto all the saints,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 16, E'Cease not to give thanks for you, making mention of you in my prayers;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 17, E'That the God of our Lord Jesus Christ, the Father of glory, may give unto you the spirit of wisdom and revelation in the knowledge of him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 18, E'The eyes of your understanding being enlightened; that ye may know what is the hope of his calling, and what the riches of the glory of his inheritance in the saints,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 19, E'And what is the exceeding greatness of his power to us-ward who believe, according to the working of his mighty power,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 20, E'Which he wrought in Christ, when he raised him from the dead, and set him at his own right hand in the heavenly places,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 21, E'Far above all principality, and power, and might, and dominion, and every name that is named, not only in this world, but also in that which is to come:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 22, E'And hath put all things under his feet, and gave him to be the head over all things to the church,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 1, 23, E'Which is his body, the fulness of him that filleth all in all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 1, E'And you hath he quickened, who were dead in trespasses and sins;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 2, E'Wherein in time past ye walked according to the course of this world, according to the prince of the power of the air, the spirit that now worketh in the children of disobedience:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 3, E'Among whom also we all had our conversation in times past in the lusts of our flesh, fulfilling the desires of the flesh and of the mind; and were by nature the children of wrath, even as others.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 4, E'But God, who is rich in mercy, for his great love wherewith he loved us,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 5, E'Even when we were dead in sins, hath quickened us together with Christ, (by grace ye are saved;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 6, E'And hath raised us up together, and made us sit together in heavenly places in Christ Jesus:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 7, E'That in the ages to come he might shew the exceeding riches of his grace in his kindness toward us through Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 8, E'For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 9, E'Not of works, lest any man should boast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 10, E'For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 11, E'Wherefore remember, that ye being in time past Gentiles in the flesh, who are called Uncircumcision by that which is called the Circumcision in the flesh made by hands;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 12, E'That at that time ye were without Christ, being aliens from the commonwealth of Israel, and strangers from the covenants of promise, having no hope, and without God in the world:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 13, E'But now in Christ Jesus ye who sometimes were far off are made nigh by the blood of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 14, E'For he is our peace, who hath made both one, and hath broken down the middle wall of partition between us;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 15, E'Having abolished in his flesh the enmity, even the law of commandments contained in ordinances; for to make in himself of twain one new man, so making peace;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 16, E'And that he might reconcile both unto God in one body by the cross, having slain the enmity thereby:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 17, E'And came and preached peace to you which were afar off, and to them that were nigh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 18, E'For through him we both have access by one Spirit unto the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 19, E'Now therefore ye are no more strangers and foreigners, but fellowcitizens with the saints, and of the household of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 20, E'And are built upon the foundation of the apostles and prophets, Jesus Christ himself being the chief corner stone;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 21, E'In whom all the building fitly framed together groweth unto an holy temple in the Lord:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 2, 22, E'In whom ye also are builded together for an habitation of God through the Spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 1, E'For this cause I Paul, the prisoner of Jesus Christ for you Gentiles,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 2, E'If ye have heard of the dispensation of the grace of God which is given me to you-ward:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 3, E'How that by revelation he made known unto me the mystery; (as I wrote afore in few words,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 4, E'Whereby, when ye read, ye may understand my knowledge in the mystery of Christ)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 5, E'Which in other ages was not made known unto the sons of men, as it is now revealed unto his holy apostles and prophets by the Spirit;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 6, E'That the Gentiles should be fellowheirs, and of the same body, and partakers of his promise in Christ by the gospel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 7, E'Whereof I was made a minister, according to the gift of the grace of God given unto me by the effectual working of his power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 8, E'Unto me, who am less than the least of all saints, is this grace given, that I should preach among the Gentiles the unsearchable riches of Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 9, E'And to make all men see what is the fellowship of the mystery, which from the beginning of the world hath been hid in God, who created all things by Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 10, E'To the intent that now unto the principalities and powers in heavenly places might be known by the church the manifold wisdom of God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 11, E'According to the eternal purpose which he purposed in Christ Jesus our Lord:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 12, E'In whom we have boldness and access with confidence by the faith of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 13, E'Wherefore I desire that ye faint not at my tribulations for you, which is your glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 14, E'For this cause I bow my knees unto the Father of our Lord Jesus Christ,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 15, E'Of whom the whole family in heaven and earth is named,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 16, E'That he would grant you, according to the riches of his glory, to be strengthened with might by his Spirit in the inner man;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 17, E'That Christ may dwell in your hearts by faith; that ye, being rooted and grounded in love,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 18, E'May be able to comprehend with all saints what is the breadth, and length, and depth, and height;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 19, E'And to know the love of Christ, which passeth knowledge, that ye might be filled with all the fulness of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 20, E'Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 3, 21, E'Unto him be glory in the church by Christ Jesus throughout all ages, world without end. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 1, E'I therefore, the prisoner of the Lord, beseech you that ye walk worthy of the vocation wherewith ye are called,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 2, E'With all lowliness and meekness, with longsuffering, forbearing one another in love;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 3, E'Endeavouring to keep the unity of the Spirit in the bond of peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 4, E'There is one body, and one Spirit, even as ye are called in one hope of your calling;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 5, E'One Lord, one faith, one baptism,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 6, E'One God and Father of all, who is above all, and through all, and in you all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 7, E'But unto every one of us is given grace according to the measure of the gift of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 8, E'Wherefore he saith, When he ascended up on high, he led captivity captive, and gave gifts unto men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 9, E'(Now that he ascended, what is it but that he also descended first into the lower parts of the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 10, E'He that descended is the same also that ascended up far above all heavens, that he might fill all things.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 11, E'And he gave some, apostles; and some, prophets; and some, evangelists; and some, pastors and teachers;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 12, E'For the perfecting of the saints, for the work of the ministry, for the edifying of the body of Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 13, E'Till we all come in the unity of the faith, and of the knowledge of the Son of God, unto a perfect man, unto the measure of the stature of the fulness of Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 14, E'That we henceforth be no more children, tossed to and fro, and carried about with every wind of doctrine, by the sleight of men, and cunning craftiness, whereby they lie in wait to deceive;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 15, E'But speaking the truth in love, may grow up into him in all things, which is the head, even Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 16, E'From whom the whole body fitly joined together and compacted by that which every joint supplieth, according to the effectual working in the measure of every part, maketh increase of the body unto the edifying of itself in love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 17, E'This I say therefore, and testify in the Lord, that ye henceforth walk not as other Gentiles walk, in the vanity of their mind,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 18, E'Having the understanding darkened, being alienated from the life of God through the ignorance that is in them, because of the blindness of their heart:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 19, E'Who being past feeling have given themselves over unto lasciviousness, to work all uncleanness with greediness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 20, E'But ye have not so learned Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 21, E'If so be that ye have heard him, and have been taught by him, as the truth is in Jesus:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 22, E'That ye put off concerning the former conversation the old man, which is corrupt according to the deceitful lusts;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 23, E'And be renewed in the spirit of your mind;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 24, E'And that ye put on the new man, which after God is created in righteousness and true holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 25, E'Wherefore putting away lying, speak every man truth with his neighbour: for we are members one of another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 26, E'Be ye angry, and sin not: let not the sun go down upon your wrath:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 27, E'Neither give place to the devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 28, E'Let him that stole steal no more: but rather let him labour, working with his hands the thing which is good, that he may have to give to him that needeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 29, E'Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 30, E'And grieve not the holy Spirit of God, whereby ye are sealed unto the day of redemption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 31, E'Let all bitterness, and wrath, and anger, and clamour, and evil speaking, be put away from you, with all malice:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 4, 32, E'And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christâ€™s sake hath forgiven you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 1, E'Be ye therefore followers of God, as dear children;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 2, E'And walk in love, as Christ also hath loved us, and hath given himself for us an offering and a sacrifice to God for a sweetsmelling savour.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ephesians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 3, E'But fornication, and all uncleanness, or covetousness, let it not be once named among you, as becometh saints;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 4, E'Neither filthiness, nor foolish talking, nor jesting, which are not convenient: but rather giving of thanks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 5, E'For this ye know, that no whoremonger, nor unclean person, nor covetous man, who is an idolater, hath any inheritance in the kingdom of Christ and of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 6, E'Let no man deceive you with vain words: for because of these things cometh the wrath of God upon the children of disobedience.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 7, E'Be not ye therefore partakers with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 8, E'For ye were sometimes darkness, but now are ye light in the Lord: walk as children of light:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 9, E'(For the fruit of the Spirit is in all goodness and righteousness and truth;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 10, E'Proving what is acceptable unto the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 11, E'And have no fellowship with the unfruitful works of darkness, but rather reprove them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 12, E'For it is a shame even to speak of those things which are done of them in secret.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 13, E'But all things that are reproved are made manifest by the light: for whatsoever doth make manifest is light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 14, E'Wherefore he saith, Awake thou that sleepest, and arise from the dead, and Christ shall give thee light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 15, E'See then that ye walk circumspectly, not as fools, but as wise,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 16, E'Redeeming the time, because the days are evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 17, E'Wherefore be ye not unwise, but understanding what the will of the Lord is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 18, E'And be not drunk with wine, wherein is excess; but be filled with the Spirit;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 19, E'Speaking to yourselves in psalms and hymns and spiritual songs, singing and making melody in your heart to the Lord;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 20, E'Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 21, E'Submitting yourselves one to another in the fear of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 22, E'Wives, submit yourselves unto your own husbands, as unto the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 23, E'For the husband is the head of the wife, even as Christ is the head of the church: and he is the saviour of the body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 24, E'Therefore as the church is subject unto Christ, so let the wives be to their own husbands in every thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 25, E'Husbands, love your wives, even as Christ also loved the church, and gave himself for it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 26, E'That he might sanctify and cleanse it with the washing of water by the word,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 27, E'That he might present it to himself a glorious church, not having spot, or wrinkle, or any such thing; but that it should be holy and without blemish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 28, E'So ought men to love their wives as their own bodies. He that loveth his wife loveth himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 29, E'For no man ever yet hated his own flesh; but nourisheth and cherisheth it, even as the Lord the church:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 30, E'For we are members of his body, of his flesh, and of his bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 31, E'For this cause shall a man leave his father and mother, and shall be joined unto his wife, and they two shall be one flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 32, E'This is a great mystery: but I speak concerning Christ and the church.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 5, 33, E'Nevertheless let every one of you in particular so love his wife even as himself; and the wife see that she reverence her husband.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 1, E'Children, obey your parents in the Lord: for this is right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 2, E'Honour thy father and mother; which is the first commandment with promise;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 3, E'That it may be well with thee, and thou mayest live long on the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 4, E'And, ye fathers, provoke not your children to wrath: but bring them up in the nurture and admonition of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 5, E'Servants, be obedient to them that are your masters according to the flesh, with fear and trembling, in singleness of your heart, as unto Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 6, E'Not with eyeservice, as menpleasers; but as the servants of Christ, doing the will of God from the heart;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 7, E'With good will doing service, as to the Lord, and not to men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 8, E'Knowing that whatsoever good thing any man doeth, the same shall he receive of the Lord, whether he be bond or free.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 9, E'And, ye masters, do the same things unto them, forbearing threatening: knowing that your Master also is in heaven; neither is there respect of persons with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 10, E'Finally, my brethren, be strong in the Lord, and in the power of his might.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 11, E'Put on the whole armour of God, that ye may be able to stand against the wiles of the devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 12, E'For we wrestle not against flesh and blood, but against principalities, against powers, against the rulers of the darkness of this world, against spiritual wickedness in high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 13, E'Wherefore take unto you the whole armour of God, that ye may be able to withstand in the evil day, and having done all, to stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 14, E'Stand therefore, having your loins girt about with truth, and having on the breastplate of righteousness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 15, E'And your feet shod with the preparation of the gospel of peace;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 16, E'Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 17, E'And take the helmet of salvation, and the sword of the Spirit, which is the word of God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 18, E'Praying always with all prayer and supplication in the Spirit, and watching thereunto with all perseverance and supplication for all saints;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 19, E'And for me, that utterance may be given unto me, that I may open my mouth boldly, to make known the mystery of the gospel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 20, E'For which I am an ambassador in bonds: that therein I may speak boldly, as I ought to speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 21, E'But that ye also may know my affairs, and how I do, Tychicus, a beloved brother and faithful minister in the Lord, shall make known to you all things:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 22, E'Whom I have sent unto you for the same purpose, that ye might know our affairs, and that he might comfort your hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 23, E'Peace be to the brethren, and love with faith, from God the Father and the Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b1ebe5d3-41c8-4fcb-9e7b-107c051f7017', 6, 24, E'Grace be with all them that love our Lord Jesus Christ in sincerity. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ephesians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 1, E'Paul and Timotheus, the servants of Jesus Christ, to all the saints in Christ Jesus which are at Philippi, with the bishops and deacons:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 2, E'Grace be unto you, and peace, from God our Father, and from the Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 3, E'I thank my God upon every remembrance of you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 4, E'Always in every prayer of mine for you all making request with joy,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 5, E'For your fellowship in the gospel from the first day until now;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 6, E'Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 7, E'Even as it is meet for me to think this of you all, because I have you in my heart; inasmuch as both in my bonds, and in the defence and confirmation of the gospel, ye all are partakers of my grace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 8, E'For God is my record, how greatly I long after you all in the bowels of Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 9, E'And this I pray, that your love may abound yet more and more in knowledge and in all judgment;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 10, E'That ye may approve things that are excellent; that ye may be sincere and without offence till the day of Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 11, E'Being filled with the fruits of righteousness, which are by Jesus Christ, unto the glory and praise of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 12, E'But I would ye should understand, brethren, that the things which happened unto me have fallen out rather unto the furtherance of the gospel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 13, E'So that my bonds in Christ are manifest in all the palace, and in all other places;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 14, E'And many of the brethren in the Lord, waxing confident by my bonds, are much more bold to speak the word without fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 15, E'Some indeed preach Christ even of envy and strife; and some also of good will:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 16, E'The one preach Christ of contention, not sincerely, supposing to add affliction to my bonds:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 17, E'But the other of love, knowing that I am set for the defence of the gospel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 18, E'What then? notwithstanding, every way, whether in pretence, or in truth, Christ is preached; and I therein do rejoice, yea, and will rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 19, E'For I know that this shall turn to my salvation through your prayer, and the supply of the Spirit of Jesus Christ,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 20, E'According to my earnest expectation and my hope, that in nothing I shall be ashamed, but that with all boldness, as always, so now also Christ shall be magnified in my body, whether it be by life, or by death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 21, E'For to me to live is Christ, and to die is gain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 22, E'But if I live in the flesh, this is the fruit of my labour: yet what I shall choose I wot not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 23, E'For I am in a strait betwixt two, having a desire to depart, and to be with Christ; which is far better:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 24, E'Nevertheless to abide in the flesh is more needful for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 25, E'And having this confidence, I know that I shall abide and continue with you all for your furtherance and joy of faith;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 26, E'That your rejoicing may be more abundant in Jesus Christ for me by my coming to you again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 27, E'Only let your conversation be as it becometh the gospel of Christ: that whether I come and see you, or else be absent, I may hear of your affairs, that ye stand fast in one spirit, with one mind striving together for the faith of the gospel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 28, E'And in nothing terrified by your adversaries: which is to them an evident token of perdition, but to you of salvation, and that of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 29, E'For unto you it is given in the behalf of Christ, not only to believe on him, but also to suffer for his sake;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 1, 30, E'Having the same conflict which ye saw in me, and now hear to be in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 1, E'If there be therefore any consolation in Christ, if any comfort of love, if any fellowship of the Spirit, if any bowels and mercies,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 2, E'Fulfil ye my joy, that ye be likeminded, having the same love, being of one accord, of one mind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 3, E'Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 4, E'Look not every man on his own things, but every man also on the things of others.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 5, E'Let this mind be in you, which was also in Christ Jesus:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 6, E'Who, being in the form of God, thought it not robbery to be equal with God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 7, E'But made himself of no reputation, and took upon him the form of a servant, and was made in the likeness of men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 8, E'And being found in fashion as a man, he humbled himself, and became obedient unto death, even the death of the cross.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 9, E'Wherefore God also hath highly exalted him, and given him a name which is above every name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 10, E'That at the name of Jesus every knee should bow, of things in heaven, and things in earth, and things under the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 11, E'And that every tongue should confess that Jesus Christ is Lord, to the glory of God the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 12, E'Wherefore, my beloved, as ye have always obeyed, not as in my presence only, but now much more in my absence, work out your own salvation with fear and trembling.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 13, E'For it is God which worketh in you both to will and to do of his good pleasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 14, E'Do all things without murmurings and disputings:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 15, E'That ye may be blameless and harmless, the sons of God, without rebuke, in the midst of a crooked and perverse nation, among whom ye shine as lights in the world;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 16, E'Holding forth the word of life; that I may rejoice in the day of Christ, that I have not run in vain, neither laboured in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 17, E'Yea, and if I be offered upon the sacrifice and service of your faith, I joy, and rejoice with you all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 18, E'For the same cause also do ye joy, and rejoice with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 19, E'But I trust in the Lord Jesus to send Timotheus shortly unto you, that I also may be of good comfort, when I know your state.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 20, E'For I have no man likeminded, who will naturally care for your state.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 21, E'For all seek their own, not the things which are Jesus Christâ€™s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 22, E'But ye know the proof of him, that, as a son with the father, he hath served with me in the gospel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 23, E'Him therefore I hope to send presently, so soon as I shall see how it will go with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 24, E'But I trust in the Lord that I also myself shall come shortly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 25, E'Yet I supposed it necessary to send to you Epaphroditus, my brother, and companion in labour, and fellowsoldier, but your messenger, and he that ministered to my wants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 26, E'For he longed after you all, and was full of heaviness, because that ye had heard that he had been sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 27, E'For indeed he was sick nigh unto death: but God had mercy on him; and not on him only, but on me also, lest I should have sorrow upon sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 28, E'I sent him therefore the more carefully, that, when ye see him again, ye may rejoice, and that I may be the less sorrowful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 29, E'Receive him therefore in the Lord with all gladness; and hold such in reputation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 2, 30, E'Because for the work of Christ he was nigh unto death, not regarding his life, to supply your lack of service toward me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 1, E'Finally, my brethren, rejoice in the Lord. To write the same things to you, to me indeed is not grievous, but for you it is safe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 2, E'Beware of dogs, beware of evil workers, beware of the concision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 3, E'For we are the circumcision, which worship God in the spirit, and rejoice in Christ Jesus, and have no confidence in the flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 4, E'Though I might also have confidence in the flesh. If any other man thinketh that he hath whereof he might trust in the flesh, I more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 5, E'Circumcised the eighth day, of the stock of Israel, of the tribe of Benjamin, an Hebrew of the Hebrews; as touching the law, a Pharisee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 6, E'Concerning zeal, persecuting the church; touching the righteousness which is in the law, blameless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 7, E'But what things were gain to me, those I counted loss for Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 8, E'Yea doubtless, and I count all things but loss for the excellency of the knowledge of Christ Jesus my Lord: for whom I have suffered the loss of all things, and do count them but dung, that I may win Christ,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 9, E'And be found in him, not having mine own righteousness, which is of the law, but that which is through the faith of Christ, the righteousness which is of God by faith:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 10, E'That I may know him, and the power of his resurrection, and the fellowship of his sufferings, being made conformable unto his death;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 11, E'If by any means I might attain unto the resurrection of the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 12, E'Not as though I had already attained, either were already perfect: but I follow after, if that I may apprehend that for which also I am apprehended of Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 13, E'Brethren, I count not myself to have apprehended: but this one thing I do, forgetting those things which are behind, and reaching forth unto those things which are before,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 14, E'I press toward the mark for the prize of the high calling of God in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 15, E'Let us therefore, as many as be perfect, be thus minded: and if in any thing ye be otherwise minded, God shall reveal even this unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 16, E'Nevertheless, whereto we have already attained, let us walk by the same rule, let us mind the same thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 17, E'Brethren, be followers together of me, and mark them which walk so as ye have us for an ensample.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 18, E'(For many walk, of whom I have told you often, and now tell you even weeping, that they are the enemies of the cross of Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 19, E'Whose end is destruction, whose God is their belly, and whose glory is in their shame, who mind earthly things.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 20, E'For our conversation is in heaven; from whence also we look for the Saviour, the Lord Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 3, 21, E'Who shall change our vile body, that it may be fashioned like unto his glorious body, according to the working whereby he is able even to subdue all things unto himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 1, E'Therefore, my brethren dearly beloved and longed for, my joy and crown, so stand fast in the Lord, my dearly beloved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 2, E'I beseech Euodias, and beseech Syntyche, that they be of the same mind in the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 3, E'And I intreat thee also, true yokefellow, help those women which laboured with me in the gospel, with Clement also, and with other my fellowlabourers, whose names are in the book of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 4, E'Rejoice in the Lord alway: and again I say, Rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 5, E'Let your moderation be known unto all men. The Lord is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 6, E'Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 7, E'And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 8, E'Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 9, E'Those things, which ye have both learned, and received, and heard, and seen in me, do: and the God of peace shall be with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 10, E'But I rejoiced in the Lord greatly, that now at the last your care of me hath flourished again; wherein ye were also careful, but ye lacked opportunity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 11, E'Not that I speak in respect of want: for I have learned, in whatsoever state I am, therewith to be content.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 12, E'I know both how to be abased, and I know how to abound: every where and in all things I am instructed both to be full and to be hungry, both to abound and to suffer need.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 13, E'I can do all things through Christ which strengtheneth me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 14, E'Notwithstanding ye have well done, that ye did communicate with my affliction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 15, E'Now ye Philippians know also, that in the beginning of the gospel, when I departed from Macedonia, no church communicated with me as concerning giving and receiving, but ye only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 16, E'For even in Thessalonica ye sent once and again unto my necessity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 17, E'Not because I desire a gift: but I desire fruit that may abound to your account.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 18, E'But I have all, and abound: I am full, having received of Epaphroditus the things which were sent from you, an odour of a sweet smell, a sacrifice acceptable, wellpleasing to God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 19, E'But my God shall supply all your need according to his riches in glory by Christ Jesus.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Philippians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 20, E'Now unto God and our Father be glory for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 21, E'Salute every saint in Christ Jesus. The brethren which are with me greet you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 22, E'All the saints salute you, chiefly they that are of Caesarâ€™s household.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1c980596-041b-4524-bda1-47215892271c', 4, 23, E'The grace of our Lord Jesus Christ be with you all. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Philippians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 1, E'Paul, an apostle of Jesus Christ by the will of God, and Timotheus our brother,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 2, E'To the saints and faithful brethren in Christ which are at Colosse: Grace be unto you, and peace, from God our Father and the Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 3, E'We give thanks to God and the Father of our Lord Jesus Christ, praying always for you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 4, E'Since we heard of your faith in Christ Jesus, and of the love which ye have to all the saints,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 5, E'For the hope which is laid up for you in heaven, whereof ye heard before in the word of the truth of the gospel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 6, E'Which is come unto you, as it is in all the world; and bringeth forth fruit, as it doth also in you, since the day ye heard of it, and knew the grace of God in truth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 7, E'As ye also learned of Epaphras our dear fellowservant, who is for you a faithful minister of Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 8, E'Who also declared unto us your love in the Spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 9, E'For this cause we also, since the day we heard it, do not cease to pray for you, and to desire that ye might be filled with the knowledge of his will in all wisdom and spiritual understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 10, E'That ye might walk worthy of the Lord unto all pleasing, being fruitful in every good work, and increasing in the knowledge of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 11, E'Strengthened with all might, according to his glorious power, unto all patience and longsuffering with joyfulness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 12, E'Giving thanks unto the Father, which hath made us meet to be partakers of the inheritance of the saints in light:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 13, E'Who hath delivered us from the power of darkness, and hath translated us into the kingdom of his dear Son:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 14, E'In whom we have redemption through his blood, even the forgiveness of sins:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 15, E'Who is the image of the invisible God, the firstborn of every creature:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 16, E'For by him were all things created, that are in heaven, and that are in earth, visible and invisible, whether they be thrones, or dominions, or principalities, or powers: all things were created by him, and for him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 17, E'And he is before all things, and by him all things consist.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 18, E'And he is the head of the body, the church: who is the beginning, the firstborn from the dead; that in all things he might have the preeminence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 19, E'For it pleased the Father that in him should all fulness dwell;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 20, E'And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 21, E'And you, that were sometime alienated and enemies in your mind by wicked works, yet now hath he reconciled'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 22, E'In the body of his flesh through death, to present you holy and unblameable and unreproveable in his sight:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 23, E'If ye continue in the faith grounded and settled, and be not moved away from the hope of the gospel, which ye have heard, and which was preached to every creature which is under heaven; whereof I Paul am made a minister;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 24, E'Who now rejoice in my sufferings for you, and fill up that which is behind of the afflictions of Christ in my flesh for his bodyâ€™s sake, which is the church:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 25, E'Whereof I am made a minister, according to the dispensation of God which is given to me for you, to fulfil the word of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 26, E'Even the mystery which hath been hid from ages and from generations, but now is made manifest to his saints:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 27, E'To whom God would make known what is the riches of the glory of this mystery among the Gentiles; which is Christ in you, the hope of glory:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 28, E'Whom we preach, warning every man, and teaching every man in all wisdom; that we may present every man perfect in Christ Jesus:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 1, 29, E'Whereunto I also labour, striving according to his working, which worketh in me mightily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 1, E'For I would that ye knew what great conflict I have for you, and for them at Laodicea, and for as many as have not seen my face in the flesh;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 2, E'That their hearts might be comforted, being knit together in love, and unto all riches of the full assurance of understanding, to the acknowledgement of the mystery of God, and of the Father, and of Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 3, E'In whom are hid all the treasures of wisdom and knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 4, E'And this I say, lest any man should beguile you with enticing words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 5, E'For though I be absent in the flesh, yet am I with you in the spirit, joying and beholding your order, and the stedfastness of your faith in Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 6, E'As ye have therefore received Christ Jesus the Lord, so walk ye in him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 7, E'Rooted and built up in him, and stablished in the faith, as ye have been taught, abounding therein with thanksgiving.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 8, E'Beware lest any man spoil you through philosophy and vain deceit, after the tradition of men, after the rudiments of the world, and not after Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 9, E'For in him dwelleth all the fulness of the Godhead bodily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 10, E'And ye are complete in him, which is the head of all principality and power:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 11, E'In whom also ye are circumcised with the circumcision made without hands, in putting off the body of the sins of the flesh by the circumcision of Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 12, E'Buried with him in baptism, wherein also ye are risen with him through the faith of the operation of God, who hath raised him from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 13, E'And you, being dead in your sins and the uncircumcision of your flesh, hath he quickened together with him, having forgiven you all trespasses;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 14, E'Blotting out the handwriting of ordinances that was against us, which was contrary to us, and took it out of the way, nailing it to his cross;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 15, E'And having spoiled principalities and powers, he made a shew of them openly, triumphing over them in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 16, E'Let no man therefore judge you in meat, or in drink, or in respect of an holyday, or of the new moon, or of the sabbath days:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 17, E'Which are a shadow of things to come; but the body is of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 18, E'Let no man beguile you of your reward in a voluntary humility and worshipping of angels, intruding into those things which he hath not seen, vainly puffed up by his fleshly mind,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 19, E'And not holding the Head, from which all the body by joints and bands having nourishment ministered, and knit together, increaseth with the increase of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 20, E'Wherefore if ye be dead with Christ from the rudiments of the world, why, as though living in the world, are ye subject to ordinances,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 21, E'(Touch not; taste not; handle not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 22, E'Which all are to perish with the using;) after the commandments and doctrines of men?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 2, 23, E'Which things have indeed a shew of wisdom in will worship, and humility, and neglecting of the body; not in any honour to the satisfying of the flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 1, E'If ye then be risen with Christ, seek those things which are above, where Christ sitteth on the right hand of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 2, E'Set your affection on things above, not on things on the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 3, E'For ye are dead, and your life is hid with Christ in God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 4, E'When Christ, who is our life, shall appear, then shall ye also appear with him in glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 5, E'Mortify therefore your members which are upon the earth; fornication, uncleanness, inordinate affection, evil concupiscence, and covetousness, which is idolatry:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 6, E'For which thingsâ€™ sake the wrath of God cometh on the children of disobedience:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 7, E'In the which ye also walked some time, when ye lived in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 8, E'But now ye also put off all these; anger, wrath, malice, blasphemy, filthy communication out of your mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 9, E'Lie not one to another, seeing that ye have put off the old man with his deeds;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 10, E'And have put on the new man, which is renewed in knowledge after the image of him that created him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 11, E'Where there is neither Greek nor Jew, circumcision nor uncircumcision, Barbarian, Scythian, bond nor free: but Christ is all, and in all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 12, E'Put on therefore, as the elect of God, holy and beloved, bowels of mercies, kindness, humbleness of mind, meekness, longsuffering;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 13, E'Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 14, E'And above all these things put on charity, which is the bond of perfectness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 15, E'And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 16, E'Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 17, E'And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 18, E'Wives, submit yourselves unto your own husbands, as it is fit in the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 19, E'Husbands, love your wives, and be not bitter against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 20, E'Children, obey your parents in all things: for this is well pleasing unto the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 21, E'Fathers, provoke not your children to anger, lest they be discouraged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 22, E'Servants, obey in all things your masters according to the flesh; not with eyeservice, as menpleasers; but in singleness of heart, fearing God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 23, E'And whatsoever ye do, do it heartily, as to the Lord, and not unto men;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 24, E'Knowing that of the Lord ye shall receive the reward of the inheritance: for ye serve the Lord Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 3, 25, E'But he that doeth wrong shall receive for the wrong which he hath done: and there is no respect of persons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 1, E'Masters, give unto your servants that which is just and equal; knowing that ye also have a Master in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 2, E'Continue in prayer, and watch in the same with thanksgiving;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 3, E'Withal praying also for us, that God would open unto us a door of utterance, to speak the mystery of Christ, for which I am also in bonds:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 4, E'That I may make it manifest, as I ought to speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 5, E'Walk in wisdom toward them that are without, redeeming the time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 6, E'Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 7, E'All my state shall Tychicus declare unto you, who is a beloved brother, and a faithful minister and fellowservant in the Lord:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 8, E'Whom I have sent unto you for the same purpose, that he might know your estate, and comfort your hearts;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 9, E'With Onesimus, a faithful and beloved brother, who is one of you. They shall make known unto you all things which are done here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 10, E'Aristarchus my fellowprisoner saluteth you, and Marcus, sisterâ€™s son to Barnabas, (touching whom ye received commandments: if he come unto you, receive him;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 11, E'And Jesus, which is called Justus, who are of the circumcision. These only are my fellowworkers unto the kingdom of God, which have been a comfort unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 12, E'Epaphras, who is one of you, a servant of Christ, saluteth you, always labouring fervently for you in prayers, that ye may stand perfect and complete in all the will of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 13, E'For I bear him record, that he hath a great zeal for you, and them that are in Laodicea, and them in Hierapolis.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 14, E'Luke, the beloved physician, and Demas, greet you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 15, E'Salute the brethren which are in Laodicea, and Nymphas, and the church which is in his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 16, E'And when this epistle is read among you, cause that it be read also in the church of the Laodiceans; and that ye likewise read the epistle from Laodicea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 17, E'And say to Archippus, Take heed to the ministry which thou hast received in the Lord, that thou fulfil it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '502875d7-ed3c-4db3-8ca5-88a9bcf8c980', 4, 18, E'The salutation by the hand of me Paul. Remember my bonds. Grace be with you. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Colossians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 1, E'Paul, and Silvanus, and Timotheus, unto the church of the Thessalonians which is in God the Father and in the Lord Jesus Christ: Grace be unto you, and peace, from God our Father, and the Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 2, E'We give thanks to God always for you all, making mention of you in our prayers;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 3, E'Remembering without ceasing your work of faith, and labour of love, and patience of hope in our Lord Jesus Christ, in the sight of God and our Father;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 4, E'Knowing, brethren beloved, your election of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 5, E'For our gospel came not unto you in word only, but also in power, and in the Holy Ghost, and in much assurance; as ye know what manner of men we were among you for your sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 6, E'And ye became followers of us, and of the Lord, having received the word in much affliction, with joy of the Holy Ghost:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 7, E'So that ye were ensamples to all that believe in Macedonia and Achaia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 8, E'For from you sounded out the word of the Lord not only in Macedonia and Achaia, but also in every place your faith to God-ward is spread abroad; so that we need not to speak any thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 9, E'For they themselves shew of us what manner of entering in we had unto you, and how ye turned to God from idols to serve the living and true God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 1, 10, E'And to wait for his Son from heaven, whom he raised from the dead, even Jesus, which delivered us from the wrath to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 1, E'For yourselves, brethren, know our entrance in unto you, that it was not in vain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 2, E'But even after that we had suffered before, and were shamefully entreated, as ye know, at Philippi, we were bold in our God to speak unto you the gospel of God with much contention.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 3, E'For our exhortation was not of deceit, nor of uncleanness, nor in guile:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 4, E'But as we were allowed of God to be put in trust with the gospel, even so we speak; not as pleasing men, but God, which trieth our hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 5, E'For neither at any time used we flattering words, as ye know, nor a cloke of covetousness; God is witness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 6, E'Nor of men sought we glory, neither of you, nor yet of others, when we might have been burdensome, as the apostles of Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 7, E'But we were gentle among you, even as a nurse cherisheth her children:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 8, E'So being affectionately desirous of you, we were willing to have imparted unto you, not the gospel of God only, but also our own souls, because ye were dear unto us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 9, E'For ye remember, brethren, our labour and travail: for labouring night and day, because we would not be chargeable unto any of you, we preached unto you the gospel of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 10, E'Ye are witnesses, and God also, how holily and justly and unblameably we behaved ourselves among you that believe:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 11, E'As ye know how we exhorted and comforted and charged every one of you, as a father doth his children,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 12, E'That ye would walk worthy of God, who hath called you unto his kingdom and glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 13, E'For this cause also thank we God without ceasing, because, when ye received the word of God which ye heard of us, ye received it not as the word of men, but as it is in truth, the word of God, which effectually worketh also in you that believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 14, E'For ye, brethren, became followers of the churches of God which in Judaea are in Christ Jesus: for ye also have suffered like things of your own countrymen, even as they have of the Jews:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 15, E'Who both killed the Lord Jesus, and their own prophets, and have persecuted us; and they please not God, and are contrary to all men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 16, E'Forbidding us to speak to the Gentiles that they might be saved, to fill up their sins alway: for the wrath is come upon them to the uttermost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 17, E'But we, brethren, being taken from you for a short time in presence, not in heart, endeavoured the more abundantly to see your face with great desire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 18, E'Wherefore we would have come unto you, even I Paul, once and again; but Satan hindered us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 19, E'For what is our hope, or joy, or crown of rejoicing? Are not even ye in the presence of our Lord Jesus Christ at his coming?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 2, 20, E'For ye are our glory and joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 1, E'Wherefore when we could no longer forbear, we thought it good to be left at Athens alone;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 2, E'And sent Timotheus, our brother, and minister of God, and our fellowlabourer in the gospel of Christ, to establish you, and to comfort you concerning your faith:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 3, E'That no man should be moved by these afflictions: for yourselves know that we are appointed thereunto.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 4, E'For verily, when we were with you, we told you before that we should suffer tribulation; even as it came to pass, and ye know.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 5, E'For this cause, when I could no longer forbear, I sent to know your faith, lest by some means the tempter have tempted you, and our labour be in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 6, E'But now when Timotheus came from you unto us, and brought us good tidings of your faith and charity, and that ye have good remembrance of us always, desiring greatly to see us, as we also to see you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 7, E'Therefore, brethren, we were comforted over you in all our affliction and distress by your faith:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 8, E'For now we live, if ye stand fast in the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 9, E'For what thanks can we render to God again for you, for all the joy wherewith we joy for your sakes before our God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 10, E'Night and day praying exceedingly that we might see your face, and might perfect that which is lacking in your faith?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 11, E'Now God himself and our Father, and our Lord Jesus Christ, direct our way unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 12, E'And the Lord make you to increase and abound in love one toward another, and toward all men, even as we do toward you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 3, 13, E'To the end he may stablish your hearts unblameable in holiness before God, even our Father, at the coming of our Lord Jesus Christ with all his saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 1, E'Furthermore then we beseech you, brethren, and exhort you by the Lord Jesus, that as ye have received of us how ye ought to walk and to please God, so ye would abound more and more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 2, E'For ye know what commandments we gave you by the Lord Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 3, E'For this is the will of God, even your sanctification, that ye should abstain from fornication:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 4, E'That every one of you should know how to possess his vessel in sanctification and honour;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 5, E'Not in the lust of concupiscence, even as the Gentiles which know not God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 6, E'That no man go beyond and defraud his brother in any matter: because that the Lord is the avenger of all such, as we also have forewarned you and testified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 7, E'For God hath not called us unto uncleanness, but unto holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 8, E'He therefore that despiseth, despiseth not man, but God, who hath also given unto us his holy Spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 9, E'But as touching brotherly love ye need not that I write unto you: for ye yourselves are taught of God to love one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 10, E'And indeed ye do it toward all the brethren which are in all Macedonia: but we beseech you, brethren, that ye increase more and more;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 11, E'And that ye study to be quiet, and to do your own business, and to work with your own hands, as we commanded you;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 12, E'That ye may walk honestly toward them that are without, and that ye may have lack of nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 13, E'But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 14, E'For if we believe that Jesus died and rose again, even so them also which sleep in Jesus will God bring with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 15, E'For this we say unto you by the word of the Lord, that we which are alive and remain unto the coming of the Lord shall not prevent them which are asleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 16, E'For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 17, E'Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 4, 18, E'Wherefore comfort one another with these words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 1, E'But of the times and the seasons, brethren, ye have no need that I write unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 2, E'For yourselves know perfectly that the day of the Lord so cometh as a thief in the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 3, E'For when they shall say, Peace and safety; then sudden destruction cometh upon them, as travail upon a woman with child; and they shall not escape.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 4, E'But ye, brethren, are not in darkness, that that day should overtake you as a thief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 5, E'Ye are all the children of light, and the children of the day: we are not of the night, nor of darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 6, E'Therefore let us not sleep, as do others; but let us watch and be sober.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 7, E'For they that sleep sleep in the night; and they that be drunken are drunken in the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 8, E'But let us, who are of the day, be sober, putting on the breastplate of faith and love; and for an helmet, the hope of salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 9, E'For God hath not appointed us to wrath, but to obtain salvation by our Lord Jesus Christ,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 10, E'Who died for us, that, whether we wake or sleep, we should live together with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 11, E'Wherefore comfort yourselves together, and edify one another, even as also ye do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 12, E'And we beseech you, brethren, to know them which labour among you, and are over you in the Lord, and admonish you;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 13, E'And to esteem them very highly in love for their workâ€™s sake. And be at peace among yourselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 14, E'Now we exhort you, brethren, warn them that are unruly, comfort the feebleminded, support the weak, be patient toward all men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 15, E'See that none render evil for evil unto any man; but ever follow that which is good, both among yourselves, and to all men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 16, E'Rejoice evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 17, E'Pray without ceasing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 18, E'In every thing give thanks: for this is the will of God in Christ Jesus concerning you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 19, E'Quench not the Spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 20, E'Despise not prophesyings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 21, E'Prove all things; hold fast that which is good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 22, E'Abstain from all appearance of evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 23, E'And the very God of peace sanctify you wholly; and I pray God your whole spirit and soul and body be preserved blameless unto the coming of our Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 24, E'Faithful is he that calleth you, who also will do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 25, E'Brethren, pray for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 26, E'Greet all the brethren with an holy kiss.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 27, E'I charge you by the Lord that this epistle be read unto all the holy brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'bee39295-12cb-420e-ad33-1aac2d8af329', 5, 28, E'The grace of our Lord Jesus Christ be with you. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Thessalonians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 1, E'Paul, and Silvanus, and Timotheus, unto the church of the Thessalonians in God our Father and the Lord Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 2, E'Grace unto you, and peace, from God our Father and the Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 3, E'We are bound to thank God always for you, brethren, as it is meet, because that your faith groweth exceedingly, and the charity of every one of you all toward each other aboundeth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 4, E'So that we ourselves glory in you in the churches of God for your patience and faith in all your persecutions and tribulations that ye endure:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 5, E'Which is a manifest token of the righteous judgment of God, that ye may be counted worthy of the kingdom of God, for which ye also suffer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 6, E'Seeing it is a righteous thing with God to recompense tribulation to them that trouble you;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 7, E'And to you who are troubled rest with us, when the Lord Jesus shall be revealed from heaven with his mighty angels,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 8, E'In flaming fire taking vengeance on them that know not God, and that obey not the gospel of our Lord Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 9, E'Who shall be punished with everlasting destruction from the presence of the Lord, and from the glory of his power;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 10, E'When he shall come to be glorified in his saints, and to be admired in all them that believe (because our testimony among you was believed) in that day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 11, E'Wherefore also we pray always for you, that our God would count you worthy of this calling, and fulfil all the good pleasure of his goodness, and the work of faith with power:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 1, 12, E'That the name of our Lord Jesus Christ may be glorified in you, and ye in him, according to the grace of our God and the Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 1, E'Now we beseech you, brethren, by the coming of our Lord Jesus Christ, and by our gathering together unto him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 2, E'That ye be not soon shaken in mind, or be troubled, neither by spirit, nor by word, nor by letter as from us, as that the day of Christ is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 3, E'Let no man deceive you by any means: for that day shall not come, except there come a falling away first, and that man of sin be revealed, the son of perdition;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 4, E'Who opposeth and exalteth himself above all that is called God, or that is worshipped; so that he as God sitteth in the temple of God, shewing himself that he is God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 5, E'Remember ye not, that, when I was yet with you, I told you these things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 6, E'And now ye know what withholdeth that he might be revealed in his time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 7, E'For the mystery of iniquity doth already work: only he who now letteth will let, until he be taken out of the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 8, E'And then shall that Wicked be revealed, whom the Lord shall consume with the spirit of his mouth, and shall destroy with the brightness of his coming:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 9, E'Even him, whose coming is after the working of Satan with all power and signs and lying wonders,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 10, E'And with all deceivableness of unrighteousness in them that perish; because they received not the love of the truth, that they might be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 11, E'And for this cause God shall send them strong delusion, that they should believe a lie:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 12, E'That they all might be damned who believed not the truth, but had pleasure in unrighteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 13, E'But we are bound to give thanks alway to God for you, brethren beloved of the Lord, because God hath from the beginning chosen you to salvation through sanctification of the Spirit and belief of the truth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 14, E'Whereunto he called you by our gospel, to the obtaining of the glory of our Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 15, E'Therefore, brethren, stand fast, and hold the traditions which ye have been taught, whether by word, or our epistle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 16, E'Now our Lord Jesus Christ himself, and God, even our Father, which hath loved us, and hath given us everlasting consolation and good hope through grace,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 2, 17, E'Comfort your hearts, and stablish you in every good word and work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 1, E'Finally, brethren, pray for us, that the word of the Lord may have free course, and be glorified, even as it is with you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 2, E'And that we may be delivered from unreasonable and wicked men: for all men have not faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 3, E'But the Lord is faithful, who shall stablish you, and keep you from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 4, E'And we have confidence in the Lord touching you, that ye both do and will do the things which we command you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 5, E'And the Lord direct your hearts into the love of God, and into the patient waiting for Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 6, E'Now we command you, brethren, in the name of our Lord Jesus Christ, that ye withdraw yourselves from every brother that walketh disorderly, and not after the tradition which he received of us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 7, E'For yourselves know how ye ought to follow us: for we behaved not ourselves disorderly among you;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 8, E'Neither did we eat any manâ€™s bread for nought; but wrought with labour and travail night and day, that we might not be chargeable to any of you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 9, E'Not because we have not power, but to make ourselves an ensample unto you to follow us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 10, E'For even when we were with you, this we commanded you, that if any would not work, neither should he eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 11, E'For we hear that there are some which walk among you disorderly, working not at all, but are busybodies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 12, E'Now them that are such we command and exhort by our Lord Jesus Christ, that with quietness they work, and eat their own bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 13, E'But ye, brethren, be not weary in well doing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 14, E'And if any man obey not our word by this epistle, note that man, and have no company with him, that he may be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 15, E'Yet count him not as an enemy, but admonish him as a brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 16, E'Now the Lord of peace himself give you peace always by all means. The Lord be with you all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 17, E'The salutation of Paul with mine own hand, which is the token in every epistle: so I write.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '729c21ba-7695-4e33-be0e-ef0f2bdeb8ff', 3, 18, E'The grace of our Lord Jesus Christ be with you all. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Thessalonians') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 1, E'Paul, an apostle of Jesus Christ by the commandment of God our Saviour, and Lord Jesus Christ, which is our hope;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 2, E'Unto Timothy, my own son in the faith: Grace, mercy, and peace, from God our Father and Jesus Christ our Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 3, E'As I besought thee to abide still at Ephesus, when I went into Macedonia, that thou mightest charge some that they teach no other doctrine,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 4, E'Neither give heed to fables and endless genealogies, which minister questions, rather than godly edifying which is in faith: so do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 5, E'Now the end of the commandment is charity out of a pure heart, and of a good conscience, and of faith unfeigned:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 6, E'From which some having swerved have turned aside unto vain jangling;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 7, E'Desiring to be teachers of the law; understanding neither what they say, nor whereof they affirm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 8, E'But we know that the law is good, if a man use it lawfully;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 9, E'Knowing this, that the law is not made for a righteous man, but for the lawless and disobedient, for the ungodly and for sinners, for unholy and profane, for murderers of fathers and murderers of mothers, for manslayers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 10, E'For whoremongers, for them that defile themselves with mankind, for menstealers, for liars, for perjured persons, and if there be any other thing that is contrary to sound doctrine;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 11, E'According to the glorious gospel of the blessed God, which was committed to my trust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 12, E'And I thank Christ Jesus our Lord, who hath enabled me, for that he counted me faithful, putting me into the ministry;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 13, E'Who was before a blasphemer, and a persecutor, and injurious: but I obtained mercy, because I did it ignorantly in unbelief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 14, E'And the grace of our Lord was exceeding abundant with faith and love which is in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 15, E'This is a faithful saying, and worthy of all acceptation, that Christ Jesus came into the world to save sinners; of whom I am chief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 16, E'Howbeit for this cause I obtained mercy, that in me first Jesus Christ might shew forth all longsuffering, for a pattern to them which should hereafter believe on him to life everlasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 17, E'Now unto the King eternal, immortal, invisible, the only wise God, be honour and glory for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 18, E'This charge I commit unto thee, son Timothy, according to the prophecies which went before on thee, that thou by them mightest war a good warfare;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 19, E'Holding faith, and a good conscience; which some having put away concerning faith have made shipwreck:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 1, 20, E'Of whom is Hymenaeus and Alexander; whom I have delivered unto Satan, that they may learn not to blaspheme.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 1, E'I exhort therefore, that, first of all, supplications, prayers, intercessions, and giving of thanks, be made for all men;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 2, E'For kings, and for all that are in authority; that we may lead a quiet and peaceable life in all godliness and honesty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 3, E'For this is good and acceptable in the sight of God our Saviour;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 4, E'Who will have all men to be saved, and to come unto the knowledge of the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 5, E'For there is one God, and one mediator between God and men, the man Christ Jesus;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 6, E'Who gave himself a ransom for all, to be testified in due time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 7, E'Whereunto I am ordained a preacher, and an apostle, (I speak the truth in Christ, and lie not;) a teacher of the Gentiles in faith and verity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 8, E'I will therefore that men pray every where, lifting up holy hands, without wrath and doubting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 9, E'In like manner also, that women adorn themselves in modest apparel, with shamefacedness and sobriety; not with broided hair, or gold, or pearls, or costly array;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 10, E'But (which becometh women professing godliness) with good works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 11, E'Let the woman learn in silence with all subjection.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 12, E'But I suffer not a woman to teach, nor to usurp authority over the man, but to be in silence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 13, E'For Adam was first formed, then Eve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 14, E'And Adam was not deceived, but the woman being deceived was in the transgression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 2, 15, E'Notwithstanding she shall be saved in childbearing, if they continue in faith and charity and holiness with sobriety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 1, E'This is a true saying, If a man desire the office of a bishop, he desireth a good work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 2, E'A bishop then must be blameless, the husband of one wife, vigilant, sober, of good behaviour, given to hospitality, apt to teach;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 3, E'Not given to wine, no striker, not greedy of filthy lucre; but patient, not a brawler, not covetous;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 4, E'One that ruleth well his own house, having his children in subjection with all gravity;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 5, E'(For if a man know not how to rule his own house, how shall he take care of the church of God?)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 6, E'Not a novice, lest being lifted up with pride he fall into the condemnation of the devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 7, E'Moreover he must have a good report of them which are without; lest he fall into reproach and the snare of the devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 8, E'Likewise must the deacons be grave, not doubletongued, not given to much wine, not greedy of filthy lucre;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 9, E'Holding the mystery of the faith in a pure conscience.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 10, E'And let these also first be proved; then let them use the office of a deacon, being found blameless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 11, E'Even so must their wives be grave, not slanderers, sober, faithful in all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 12, E'Let the deacons be the husbands of one wife, ruling their children and their own houses well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 13, E'For they that have used the office of a deacon well purchase to themselves a good degree, and great boldness in the faith which is in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 14, E'These things write I unto thee, hoping to come unto thee shortly:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 15, E'But if I tarry long, that thou mayest know how thou oughtest to behave thyself in the house of God, which is the church of the living God, the pillar and ground of the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 3, 16, E'And without controversy great is the mystery of godliness: God was manifest in the flesh, justified in the Spirit, seen of angels, preached unto the Gentiles, believed on in the world, received up into glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 1, E'Now the Spirit speaketh expressly, that in the latter times some shall depart from the faith, giving heed to seducing spirits, and doctrines of devils;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 2, E'Speaking lies in hypocrisy; having their conscience seared with a hot iron;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 3, E'Forbidding to marry, and commanding to abstain from meats, which God hath created to be received with thanksgiving of them which believe and know the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 4, E'For every creature of God is good, and nothing to be refused, if it be received with thanksgiving:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 5, E'For it is sanctified by the word of God and prayer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 6, E'If thou put the brethren in remembrance of these things, thou shalt be a good minister of Jesus Christ, nourished up in the words of faith and of good doctrine, whereunto thou hast attained.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 7, E'But refuse profane and old wivesâ€™ fables, and exercise thyself rather unto godliness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 8, E'For bodily exercise profiteth little: but godliness is profitable unto all things, having promise of the life that now is, and of that which is to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 9, E'This is a faithful saying and worthy of all acceptation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 10, E'For therefore we both labour and suffer reproach, because we trust in the living God, who is the Saviour of all men, specially of those that believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 11, E'These things command and teach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 12, E'Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 13, E'Till I come, give attendance to reading, to exhortation, to doctrine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 14, E'Neglect not the gift that is in thee, which was given thee by prophecy, with the laying on of the hands of the presbytery.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 15, E'Meditate upon these things; give thyself wholly to them; that thy profiting may appear to all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 4, 16, E'Take heed unto thyself, and unto the doctrine; continue in them: for in doing this thou shalt both save thyself, and them that hear thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 1, E'Rebuke not an elder, but intreat him as a father; and the younger men as brethren;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 2, E'The elder women as mothers; the younger as sisters, with all purity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 3, E'Honour widows that are widows indeed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 4, E'But if any widow have children or nephews, let them learn first to shew piety at home, and to requite their parents: for that is good and acceptable before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 5, E'Now she that is a widow indeed, and desolate, trusteth in God, and continueth in supplications and prayers night and day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 6, E'But she that liveth in pleasure is dead while she liveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 7, E'And these things give in charge, that they may be blameless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 8, E'But if any provide not for his own, and specially for those of his own house, he hath denied the faith, and is worse than an infidel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 9, E'Let not a widow be taken into the number under threescore years old, having been the wife of one man,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 10, E'Well reported of for good works; if she have brought up children, if she have lodged strangers, if she have washed the saintsâ€™ feet, if she have relieved the afflicted, if she have diligently followed every good work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 11, E'But the younger widows refuse: for when they have begun to wax wanton against Christ, they will marry;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 12, E'Having damnation, because they have cast off their first faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 13, E'And withal they learn to be idle, wandering about from house to house; and not only idle, but tattlers also and busybodies, speaking things which they ought not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 14, E'I will therefore that the younger women marry, bear children, guide the house, give none occasion to the adversary to speak reproachfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 15, E'For some are already turned aside after Satan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 16, E'If any man or woman that believeth have widows, let them relieve them, and let not the church be charged; that it may relieve them that are widows indeed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 17, E'Let the elders that rule well be counted worthy of double honour, especially they who labour in the word and doctrine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 18, E'For the scripture saith, Thou shalt not muzzle the ox that treadeth out the corn. And, The labourer is worthy of his reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 19, E'Against an elder receive not an accusation, but before two or three witnesses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 20, E'Them that sin rebuke before all, that others also may fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 21, E'I charge thee before God, and the Lord Jesus Christ, and the elect angels, that thou observe these things without preferring one before another, doing nothing by partiality.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 22, E'Lay hands suddenly on no man, neither be partaker of other menâ€™s sins: keep thyself pure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 23, E'Drink no longer water, but use a little wine for thy stomachâ€™s sake and thine often infirmities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 24, E'Some menâ€™s sins are open beforehand, going before to judgment; and some men they follow after.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 5, 25, E'Likewise also the good works of some are manifest beforehand; and they that are otherwise cannot be hid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 1, E'Let as many servants as are under the yoke count their own masters worthy of all honour, that the name of God and his doctrine be not blasphemed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 2, E'And they that have believing masters, let them not despise them, because they are brethren; but rather do them service, because they are faithful and beloved, partakers of the benefit. These things teach and exhort.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 3, E'If any man teach otherwise, and consent not to wholesome words, even the words of our Lord Jesus Christ, and to the doctrine which is according to godliness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 4, E'He is proud, knowing nothing, but doting about questions and strifes of words, whereof cometh envy, strife, railings, evil surmisings,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 5, E'Perverse disputings of men of corrupt minds, and destitute of the truth, supposing that gain is godliness: from such withdraw thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 6, E'But godliness with contentment is great gain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 7, E'For we brought nothing into this world, and it is certain we can carry nothing out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 8, E'And having food and raiment let us be therewith content.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Timothy') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 9, E'But they that will be rich fall into temptation and a snare, and into many foolish and hurtful lusts, which drown men in destruction and perdition.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 10, E'For the love of money is the root of all evil: which while some coveted after, they have erred from the faith, and pierced themselves through with many sorrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 11, E'But thou, O man of God, flee these things; and follow after righteousness, godliness, faith, love, patience, meekness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 12, E'Fight the good fight of faith, lay hold on eternal life, whereunto thou art also called, and hast professed a good profession before many witnesses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 13, E'I give thee charge in the sight of God, who quickeneth all things, and before Christ Jesus, who before Pontius Pilate witnessed a good confession;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 14, E'That thou keep this commandment without spot, unrebukeable, until the appearing of our Lord Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 15, E'Which in his times he shall shew, who is the blessed and only Potentate, the King of kings, and Lord of lords;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 16, E'Who only hath immortality, dwelling in the light which no man can approach unto; whom no man hath seen, nor can see: to whom be honour and power everlasting. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 17, E'Charge them that are rich in this world, that they be not highminded, nor trust in uncertain riches, but in the living God, who giveth us richly all things to enjoy;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 18, E'That they do good, that they be rich in good works, ready to distribute, willing to communicate;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 19, E'Laying up in store for themselves a good foundation against the time to come, that they may lay hold on eternal life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 20, E'O Timothy, keep that which is committed to thy trust, avoiding profane and vain babblings, and oppositions of science falsely so called:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4a228f84-3a17-4e93-9322-78663a6dcaca', 6, 21, E'Which some professing have erred concerning the faith. Grace be with thee. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Timothy') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 1, E'Paul, an apostle of Jesus Christ by the will of God, according to the promise of life which is in Christ Jesus,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 2, E'To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 3, E'I thank God, whom I serve from my forefathers with pure conscience, that without ceasing I have remembrance of thee in my prayers night and day;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 4, E'Greatly desiring to see thee, being mindful of thy tears, that I may be filled with joy;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 5, E'When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 6, E'Wherefore I put thee in remembrance that thou stir up the gift of God, which is in thee by the putting on of my hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 7, E'For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 8, E'Be not thou therefore ashamed of the testimony of our Lord, nor of me his prisoner: but be thou partaker of the afflictions of the gospel according to the power of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 9, E'Who hath saved us, and called us with an holy calling, not according to our works, but according to his own purpose and grace, which was given us in Christ Jesus before the world began,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 10, E'But is now made manifest by the appearing of our Saviour Jesus Christ, who hath abolished death, and hath brought life and immortality to light through the gospel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 11, E'Whereunto I am appointed a preacher, and an apostle, and a teacher of the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 12, E'For the which cause I also suffer these things: nevertheless I am not ashamed: for I know whom I have believed, and am persuaded that he is able to keep that which I have committed unto him against that day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 13, E'Hold fast the form of sound words, which thou hast heard of me, in faith and love which is in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 14, E'That good thing which was committed unto thee keep by the Holy Ghost which dwelleth in us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 15, E'This thou knowest, that all they which are in Asia be turned away from me; of whom are Phygellus and Hermogenes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 16, E'The Lord give mercy unto the house of Onesiphorus; for he oft refreshed me, and was not ashamed of my chain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 17, E'But, when he was in Rome, he sought me out very diligently, and found me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 1, 18, E'The Lord grant unto him that he may find mercy of the Lord in that day: and in how many things he ministered unto me at Ephesus, thou knowest very well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 1, E'Thou therefore, my son, be strong in the grace that is in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 2, E'And the things that thou hast heard of me among many witnesses, the same commit thou to faithful men, who shall be able to teach others also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 3, E'Thou therefore endure hardness, as a good soldier of Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 4, E'No man that warreth entangleth himself with the affairs of this life; that he may please him who hath chosen him to be a soldier.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 5, E'And if a man also strive for masteries, yet is he not crowned, except he strive lawfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 6, E'The husbandman that laboureth must be first partaker of the fruits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 7, E'Consider what I say; and the Lord give thee understanding in all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 8, E'Remember that Jesus Christ of the seed of David was raised from the dead according to my gospel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 9, E'Wherein I suffer trouble, as an evil doer, even unto bonds; but the word of God is not bound.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 10, E'Therefore I endure all things for the electâ€™s sakes, that they may also obtain the salvation which is in Christ Jesus with eternal glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 11, E'It is a faithful saying: For if we be dead with him, we shall also live with him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 12, E'If we suffer, we shall also reign with him: if we deny him, he also will deny us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 13, E'If we believe not, yet he abideth faithful: he cannot deny himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 14, E'Of these things put them in remembrance, charging them before the Lord that they strive not about words to no profit, but to the subverting of the hearers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 15, E'Study to shew thyself approved unto God, a workman that needeth not to be ashamed, rightly dividing the word of truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 16, E'But shun profane and vain babblings: for they will increase unto more ungodliness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 17, E'And their word will eat as doth a canker: of whom is Hymenaeus and Philetus;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 18, E'Who concerning the truth have erred, saying that the resurrection is past already; and overthrow the faith of some.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 19, E'Nevertheless the foundation of God standeth sure, having this seal, The Lord knoweth them that are his. And, Let every one that nameth the name of Christ depart from iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 20, E'But in a great house there are not only vessels of gold and of silver, but also of wood and of earth; and some to honour, and some to dishonour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 21, E'If a man therefore purge himself from these, he shall be a vessel unto honour, sanctified, and meet for the masterâ€™s use, and prepared unto every good work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 22, E'Flee also youthful lusts: but follow righteousness, faith, charity, peace, with them that call on the Lord out of a pure heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 23, E'But foolish and unlearned questions avoid, knowing that they do gender strifes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 24, E'And the servant of the Lord must not strive; but be gentle unto all men, apt to teach, patient,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 25, E'In meekness instructing those that oppose themselves; if God peradventure will give them repentance to the acknowledging of the truth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 2, 26, E'And that they may recover themselves out of the snare of the devil, who are taken captive by him at his will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 1, E'This know also, that in the last days perilous times shall come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 2, E'For men shall be lovers of their own selves, covetous, boasters, proud, blasphemers, disobedient to parents, unthankful, unholy,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 3, E'Without natural affection, trucebreakers, false accusers, incontinent, fierce, despisers of those that are good,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 4, E'Traitors, heady, highminded, lovers of pleasures more than lovers of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 5, E'Having a form of godliness, but denying the power thereof: from such turn away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 6, E'For of this sort are they which creep into houses, and lead captive silly women laden with sins, led away with divers lusts,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 7, E'Ever learning, and never able to come to the knowledge of the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 8, E'Now as Jannes and Jambres withstood Moses, so do these also resist the truth: men of corrupt minds, reprobate concerning the faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 9, E'But they shall proceed no further: for their folly shall be manifest unto all men, as theirs also was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 10, E'But thou hast fully known my doctrine, manner of life, purpose, faith, longsuffering, charity, patience,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 11, E'Persecutions, afflictions, which came unto me at Antioch, at Iconium, at Lystra; what persecutions I endured: but out of them all the Lord delivered me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 12, E'Yea, and all that will live godly in Christ Jesus shall suffer persecution.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 13, E'But evil men and seducers shall wax worse and worse, deceiving, and being deceived.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 14, E'But continue thou in the things which thou hast learned and hast been assured of, knowing of whom thou hast learned them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 15, E'And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 16, E'All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 3, 17, E'That the man of God may be perfect, throughly furnished unto all good works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 1, E'I charge thee therefore before God, and the Lord Jesus Christ, who shall judge the quick and the dead at his appearing and his kingdom;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 2, E'Preach the word; be instant in season, out of season; reprove, rebuke, exhort with all longsuffering and doctrine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 3, E'For the time will come when they will not endure sound doctrine; but after their own lusts shall they heap to themselves teachers, having itching ears;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 4, E'And they shall turn away their ears from the truth, and shall be turned unto fables.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 5, E'But watch thou in all things, endure afflictions, do the work of an evangelist, make full proof of thy ministry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 6, E'For I am now ready to be offered, and the time of my departure is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 7, E'I have fought a good fight, I have finished my course, I have kept the faith:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 8, E'Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day: and not to me only, but unto all them also that love his appearing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 9, E'Do thy diligence to come shortly unto me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 10, E'For Demas hath forsaken me, having loved this present world, and is departed unto Thessalonica; Crescens to Galatia, Titus unto Dalmatia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 11, E'Only Luke is with me. Take Mark, and bring him with thee: for he is profitable to me for the ministry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 12, E'And Tychicus have I sent to Ephesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 13, E'The cloke that I left at Troas with Carpus, when thou comest, bring with thee, and the books, but especially the parchments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 14, E'Alexander the coppersmith did me much evil: the Lord reward him according to his works:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 15, E'Of whom be thou ware also; for he hath greatly withstood our words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 16, E'At my first answer no man stood with me, but all men forsook me: I pray God that it may not be laid to their charge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 17, E'Notwithstanding the Lord stood with me, and strengthened me; that by me the preaching might be fully known, and that all the Gentiles might hear: and I was delivered out of the mouth of the lion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 18, E'And the Lord shall deliver me from every evil work, and will preserve me unto his heavenly kingdom: to whom be glory for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 19, E'Salute Prisca and Aquila, and the household of Onesiphorus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 20, E'Erastus abode at Corinth: but Trophimus have I left at Miletum sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 21, E'Do thy diligence to come before winter. Eubulus greeteth thee, and Pudens, and Linus, and Claudia, and all the brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ae866527-5fa5-4eb8-8c0b-feb8780ed1bf', 4, 22, E'The Lord Jesus Christ be with thy spirit. Grace be with you. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Timothy') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 1, E'Paul, a servant of God, and an apostle of Jesus Christ, according to the faith of Godâ€™s elect, and the acknowledging of the truth which is after godliness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 2, E'In hope of eternal life, which God, that cannot lie, promised before the world began;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 3, E'But hath in due times manifested his word through preaching, which is committed unto me according to the commandment of God our Saviour;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 4, E'To Titus, mine own son after the common faith: Grace, mercy, and peace, from God the Father and the Lord Jesus Christ our Saviour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 5, E'For this cause left I thee in Crete, that thou shouldest set in order the things that are wanting, and ordain elders in every city, as I had appointed thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 6, E'If any be blameless, the husband of one wife, having faithful children not accused of riot or unruly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 7, E'For a bishop must be blameless, as the steward of God; not selfwilled, not soon angry, not given to wine, no striker, not given to filthy lucre;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 8, E'But a lover of hospitality, a lover of good men, sober, just, holy, temperate;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 9, E'Holding fast the faithful word as he hath been taught, that he may be able by sound doctrine both to exhort and to convince the gainsayers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 10, E'For there are many unruly and vain talkers and deceivers, specially they of the circumcision:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 11, E'Whose mouths must be stopped, who subvert whole houses, teaching things which they ought not, for filthy lucreâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 12, E'One of themselves, even a prophet of their own, said, The Cretians are alway liars, evil beasts, slow bellies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 13, E'This witness is true. Wherefore rebuke them sharply, that they may be sound in the faith;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 14, E'Not giving heed to Jewish fables, and commandments of men, that turn from the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 15, E'Unto the pure all things are pure: but unto them that are defiled and unbelieving is nothing pure; but even their mind and conscience is defiled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 1, 16, E'They profess that they know God; but in works they deny him, being abominable, and disobedient, and unto every good work reprobate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 1, E'But speak thou the things which become sound doctrine:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 2, E'That the aged men be sober, grave, temperate, sound in faith, in charity, in patience.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 3, E'The aged women likewise, that they be in behaviour as becometh holiness, not false accusers, not given to much wine, teachers of good things;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 4, E'That they may teach the young women to be sober, to love their husbands, to love their children,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 5, E'To be discreet, chaste, keepers at home, good, obedient to their own husbands, that the word of God be not blasphemed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 6, E'Young men likewise exhort to be sober minded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 7, E'In all things shewing thyself a pattern of good works: in doctrine shewing uncorruptness, gravity, sincerity,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 8, E'Sound speech, that cannot be condemned; that he that is of the contrary part may be ashamed, having no evil thing to say of you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 9, E'Exhort servants to be obedient unto their own masters, and to please them well in all things; not answering again;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 10, E'Not purloining, but shewing all good fidelity; that they may adorn the doctrine of God our Saviour in all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 11, E'For the grace of God that bringeth salvation hath appeared to all men,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 12, E'Teaching us that, denying ungodliness and worldly lusts, we should live soberly, righteously, and godly, in this present world;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 13, E'Looking for that blessed hope, and the glorious appearing of the great God and our Saviour Jesus Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 14, E'Who gave himself for us, that he might redeem us from all iniquity, and purify unto himself a peculiar people, zealous of good works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 2, 15, E'These things speak, and exhort, and rebuke with all authority. Let no man despise thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 1, E'Put them in mind to be subject to principalities and powers, to obey magistrates, to be ready to every good work,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 2, E'To speak evil of no man, to be no brawlers, but gentle, shewing all meekness unto all men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 3, E'For we ourselves also were sometimes foolish, disobedient, deceived, serving divers lusts and pleasures, living in malice and envy, hateful, and hating one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 4, E'But after that the kindness and love of God our Saviour toward man appeared,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 5, E'Not by works of righteousness which we have done, but according to his mercy he saved us, by the washing of regeneration, and renewing of the Holy Ghost;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 6, E'Which he shed on us abundantly through Jesus Christ our Saviour;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 7, E'That being justified by his grace, we should be made heirs according to the hope of eternal life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 8, E'This is a faithful saying, and these things I will that thou affirm constantly, that they which have believed in God might be careful to maintain good works. These things are good and profitable unto men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 9, E'But avoid foolish questions, and genealogies, and contentions, and strivings about the law; for they are unprofitable and vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 10, E'A man that is an heretick after the first and second admonition reject;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 11, E'Knowing that he that is such is subverted, and sinneth, being condemned of himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 12, E'When I shall send Artemas unto thee, or Tychicus, be diligent to come unto me to Nicopolis: for I have determined there to winter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 13, E'Bring Zenas the lawyer and Apollos on their journey diligently, that nothing be wanting unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 14, E'And let ours also learn to maintain good works for necessary uses, that they be not unfruitful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '2e79b72c-1577-4692-9f95-1d7f40566ef8', 3, 15, E'All that are with me salute thee. Greet them that love us in the faith. Grace be with you all. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Titus') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 1, E'Paul, a prisoner of Jesus Christ, and Timothy our brother, unto Philemon our dearly beloved, and fellowlabourer,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 2, E'And to our beloved Apphia, and Archippus our fellowsoldier, and to the church in thy house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 3, E'Grace to you, and peace, from God our Father and the Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 4, E'I thank my God, making mention of thee always in my prayers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 5, E'Hearing of thy love and faith, which thou hast toward the Lord Jesus, and toward all saints;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 6, E'That the communication of thy faith may become effectual by the acknowledging of every good thing which is in you in Christ Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 7, E'For we have great joy and consolation in thy love, because the bowels of the saints are refreshed by thee, brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 8, E'Wherefore, though I might be much bold in Christ to enjoin thee that which is convenient,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 9, E'Yet for loveâ€™s sake I rather beseech thee, being such an one as Paul the aged, and now also a prisoner of Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 10, E'I beseech thee for my son Onesimus, whom I have begotten in my bonds:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 11, E'Which in time past was to thee unprofitable, but now profitable to thee and to me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 12, E'Whom I have sent again: thou therefore receive him, that is, mine own bowels:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 13, E'Whom I would have retained with me, that in thy stead he might have ministered unto me in the bonds of the gospel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 14, E'But without thy mind would I do nothing; that thy benefit should not be as it were of necessity, but willingly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 15, E'For perhaps he therefore departed for a season, that thou shouldest receive him for ever;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 16, E'Not now as a servant, but above a servant, a brother beloved, specially to me, but how much more unto thee, both in the flesh, and in the Lord?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 17, E'If thou count me therefore a partner, receive him as myself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 18, E'If he hath wronged thee, or oweth thee ought, put that on mine account;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 19, E'I Paul have written it with mine own hand, I will repay it: albeit I do not say to thee how thou owest unto me even thine own self besides.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 20, E'Yea, brother, let me have joy of thee in the Lord: refresh my bowels in the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 21, E'Having confidence in thy obedience I wrote unto thee, knowing that thou wilt also do more than I say.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 22, E'But withal prepare me also a lodging: for I trust that through your prayers I shall be given unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 23, E'There salute thee Epaphras, my fellowprisoner in Christ Jesus;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 24, E'Marcus, Aristarchus, Demas, Lucas, my fellowlabourers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '37b0cddb-50bb-4554-a0ca-902dcc727ccb', 1, 25, E'The grace of our Lord Jesus Christ be with your spirit. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Philemon') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 1, E'God, who at sundry times and in divers manners spake in time past unto the fathers by the prophets,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 2, E'Hath in these last days spoken unto us by his Son, whom he hath appointed heir of all things, by whom also he made the worlds;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 3, E'Who being the brightness of his glory, and the express image of his person, and upholding all things by the word of his power, when he had by himself purged our sins, sat down on the right hand of the Majesty on high;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 4, E'Being made so much better than the angels, as he hath by inheritance obtained a more excellent name than they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 5, E'For unto which of the angels said he at any time, Thou art my Son, this day have I begotten thee? And again, I will be to him a Father, and he shall be to me a Son?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 6, E'And again, when he bringeth in the firstbegotten into the world, he saith, And let all the angels of God worship him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 7, E'And of the angels he saith, Who maketh his angels spirits, and his ministers a flame of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 8, E'But unto the Son he saith, Thy throne, O God, is for ever and ever: a sceptre of righteousness is the sceptre of thy kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 9, E'Thou hast loved righteousness, and hated iniquity; therefore God, even thy God, hath anointed thee with the oil of gladness above thy fellows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 10, E'And, Thou, Lord, in the beginning hast laid the foundation of the earth; and the heavens are the works of thine hands:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 11, E'They shall perish; but thou remainest; and they all shall wax old as doth a garment;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 12, E'And as a vesture shalt thou fold them up, and they shall be changed: but thou art the same, and thy years shall not fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 13, E'But to which of the angels said he at any time, Sit on my right hand, until I make thine enemies thy footstool?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 1, 14, E'Are they not all ministering spirits, sent forth to minister for them who shall be heirs of salvation?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 1, E'Therefore we ought to give the more earnest heed to the things which we have heard, lest at any time we should let them slip.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 2, E'For if the word spoken by angels was stedfast, and every transgression and disobedience received a just recompence of reward;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 3, E'How shall we escape, if we neglect so great salvation; which at the first began to be spoken by the Lord, and was confirmed unto us by them that heard him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 4, E'God also bearing them witness, both with signs and wonders, and with divers miracles, and gifts of the Holy Ghost, according to his own will?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 5, E'For unto the angels hath he not put in subjection the world to come, whereof we speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 6, E'But one in a certain place testified, saying, What is man, that thou art mindful of him? or the son of man, that thou visitest him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 7, E'Thou madest him a little lower than the angels; thou crownedst him with glory and honour, and didst set him over the works of thy hands:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 8, E'Thou hast put all things in subjection under his feet. For in that he put all in subjection under him, he left nothing that is not put under him. But now we see not yet all things put under him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 9, E'But we see Jesus, who was made a little lower than the angels for the suffering of death, crowned with glory and honour; that he by the grace of God should taste death for every man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 10, E'For it became him, for whom are all things, and by whom are all things, in bringing many sons unto glory, to make the captain of their salvation perfect through sufferings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 11, E'For both he that sanctifieth and they who are sanctified are all of one: for which cause he is not ashamed to call them brethren,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 12, E'Saying, I will declare thy name unto my brethren, in the midst of the church will I sing praise unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 13, E'And again, I will put my trust in him. And again, Behold I and the children which God hath given me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 14, E'Forasmuch then as the children are partakers of flesh and blood, he also himself likewise took part of the same; that through death he might destroy him that had the power of death, that is, the devil;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 15, E'And deliver them who through fear of death were all their lifetime subject to bondage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 16, E'For verily he took not on him the nature of angels; but he took on him the seed of Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 17, E'Wherefore in all things it behoved him to be made like unto his brethren, that he might be a merciful and faithful high priest in things pertaining to God, to make reconciliation for the sins of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 2, 18, E'For in that he himself hath suffered being tempted, he is able to succour them that are tempted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 1, E'Wherefore, holy brethren, partakers of the heavenly calling, consider the Apostle and High Priest of our profession, Christ Jesus;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 2, E'Who was faithful to him that appointed him, as also Moses was faithful in all his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 3, E'For this man was counted worthy of more glory than Moses, inasmuch as he who hath builded the house hath more honour than the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 4, E'For every house is builded by some man; but he that built all things is God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 5, E'And Moses verily was faithful in all his house, as a servant, for a testimony of those things which were to be spoken after;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 6, E'But Christ as a son over his own house; whose house are we, if we hold fast the confidence and the rejoicing of the hope firm unto the end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 7, E'Wherefore (as the Holy Ghost saith, To day if ye will hear his voice,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 8, E'Harden not your hearts, as in the provocation, in the day of temptation in the wilderness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 9, E'When your fathers tempted me, proved me, and saw my works forty years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 10, E'Wherefore I was grieved with that generation, and said, They do alway err in their heart; and they have not known my ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 11, E'So I sware in my wrath, They shall not enter into my rest.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 12, E'Take heed, brethren, lest there be in any of you an evil heart of unbelief, in departing from the living God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 13, E'But exhort one another daily, while it is called To day; lest any of you be hardened through the deceitfulness of sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 14, E'For we are made partakers of Christ, if we hold the beginning of our confidence stedfast unto the end;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 15, E'While it is said, To day if ye will hear his voice, harden not your hearts, as in the provocation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 16, E'For some, when they had heard, did provoke: howbeit not all that came out of Egypt by Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 17, E'But with whom was he grieved forty years? was it not with them that had sinned, whose carcases fell in the wilderness?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 18, E'And to whom sware he that they should not enter into his rest, but to them that believed not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 3, 19, E'So we see that they could not enter in because of unbelief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 1, E'Let us therefore fear, lest, a promise being left us of entering into his rest, any of you should seem to come short of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 2, E'For unto us was the gospel preached, as well as unto them: but the word preached did not profit them, not being mixed with faith in them that heard it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 3, E'For we which have believed do enter into rest, as he said, As I have sworn in my wrath, if they shall enter into my rest: although the works were finished from the foundation of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 4, E'For he spake in a certain place of the seventh day on this wise, And God did rest the seventh day from all his works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 5, E'And in this place again, If they shall enter into my rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 6, E'Seeing therefore it remaineth that some must enter therein, and they to whom it was first preached entered not in because of unbelief:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 7, E'Again, he limiteth a certain day, saying in David, To day, after so long a time; as it is said, To day if ye will hear his voice, harden not your hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 8, E'For if Jesus had given them rest, then would he not afterward have spoken of another day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 9, E'There remaineth therefore a rest to the people of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 10, E'For he that is entered into his rest, he also hath ceased from his own works, as God did from his.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 11, E'Let us labour therefore to enter into that rest, lest any man fall after the same example of unbelief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 12, E'For the word of God is quick, and powerful, and sharper than any twoedged sword, piercing even to the dividing asunder of soul and spirit, and of the joints and marrow, and is a discerner of the thoughts and intents of the heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 13, E'Neither is there any creature that is not manifest in his sight: but all things are naked and opened unto the eyes of him with whom we have to do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 14, E'Seeing then that we have a great high priest, that is passed into the heavens, Jesus the Son of God, let us hold fast our profession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 15, E'For we have not an high priest which cannot be touched with the feeling of our infirmities; but was in all points tempted like as we are, yet without sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 4, 16, E'Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 1, E'For every high priest taken from among men is ordained for men in things pertaining to God, that he may offer both gifts and sacrifices for sins:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 2, E'Who can have compassion on the ignorant, and on them that are out of the way; for that he himself also is compassed with infirmity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 3, E'And by reason hereof he ought, as for the people, so also for himself, to offer for sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 4, E'And no man taketh this honour unto himself, but he that is called of God, as was Aaron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 5, E'So also Christ glorified not himself to be made an high priest; but he that said unto him, Thou art my Son, to day have I begotten thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 6, E'As he saith also in another place, Thou art a priest for ever after the order of Melchisedec.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 7, E'Who in the days of his flesh, when he had offered up prayers and supplications with strong crying and tears unto him that was able to save him from death, and was heard in that he feared;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 8, E'Though he were a Son, yet learned he obedience by the things which he suffered;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 9, E'And being made perfect, he became the author of eternal salvation unto all them that obey him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 10, E'Called of God an high priest after the order of Melchisedec.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 11, E'Of whom we have many things to say, and hard to be uttered, seeing ye are dull of hearing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 12, E'For when for the time ye ought to be teachers, ye have need that one teach you again which be the first principles of the oracles of God; and are become such as have need of milk, and not of strong meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 13, E'For every one that useth milk is unskilful in the word of righteousness: for he is a babe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 5, 14, E'But strong meat belongeth to them that are of full age, even those who by reason of use have their senses exercised to discern both good and evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 1, E'Therefore leaving the principles of the doctrine of Christ, let us go on unto perfection; not laying again the foundation of repentance from dead works, and of faith toward God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 2, E'Of the doctrine of baptisms, and of laying on of hands, and of resurrection of the dead, and of eternal judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 3, E'And this will we do, if God permit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 4, E'For it is impossible for those who were once enlightened, and have tasted of the heavenly gift, and were made partakers of the Holy Ghost,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 5, E'And have tasted the good word of God, and the powers of the world to come,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 6, E'If they shall fall away, to renew them again unto repentance; seeing they crucify to themselves the Son of God afresh, and put him to an open shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 7, E'For the earth which drinketh in the rain that cometh oft upon it, and bringeth forth herbs meet for them by whom it is dressed, receiveth blessing from God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 8, E'But that which beareth thorns and briers is rejected, and is nigh unto cursing; whose end is to be burned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 9, E'But, beloved, we are persuaded better things of you, and things that accompany salvation, though we thus speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 10, E'For God is not unrighteous to forget your work and labour of love, which ye have shewed toward his name, in that ye have ministered to the saints, and do minister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 11, E'And we desire that every one of you do shew the same diligence to the full assurance of hope unto the end:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 12, E'That ye be not slothful, but followers of them who through faith and patience inherit the promises.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 13, E'For when God made promise to Abraham, because he could swear by no greater, he sware by himself,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 14, E'Saying, Surely blessing I will bless thee, and multiplying I will multiply thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 15, E'And so, after he had patiently endured, he obtained the promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 16, E'For men verily swear by the greater: and an oath for confirmation is to them an end of all strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 17, E'Wherein God, willing more abundantly to shew unto the heirs of promise the immutability of his counsel, confirmed it by an oath:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 18, E'That by two immutable things, in which it was impossible for God to lie, we might have a strong consolation, who have fled for refuge to lay hold upon the hope set before us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 19, E'Which hope we have as an anchor of the soul, both sure and stedfast, and which entereth into that within the veil;')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Hebrews') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 6, 20, E'Whither the forerunner is for us entered, even Jesus, made an high priest for ever after the order of Melchisedec.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 1, E'For this Melchisedec, king of Salem, priest of the most high God, who met Abraham returning from the slaughter of the kings, and blessed him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 2, E'To whom also Abraham gave a tenth part of all; first being by interpretation King of righteousness, and after that also King of Salem, which is, King of peace;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 3, E'Without father, without mother, without descent, having neither beginning of days, nor end of life; but made like unto the Son of God; abideth a priest continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 4, E'Now consider how great this man was, unto whom even the patriarch Abraham gave the tenth of the spoils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 5, E'And verily they that are of the sons of Levi, who receive the office of the priesthood, have a commandment to take tithes of the people according to the law, that is, of their brethren, though they come out of the loins of Abraham:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 6, E'But he whose descent is not counted from them received tithes of Abraham, and blessed him that had the promises.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 7, E'And without all contradiction the less is blessed of the better.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 8, E'And here men that die receive tithes; but there he receiveth them, of whom it is witnessed that he liveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 9, E'And as I may so say, Levi also, who receiveth tithes, payed tithes in Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 10, E'For he was yet in the loins of his father, when Melchisedec met him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 11, E'If therefore perfection were by the Levitical priesthood, (for under it the people received the law,) what further need was there that another priest should rise after the order of Melchisedec, and not be called after the order of Aaron?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 12, E'For the priesthood being changed, there is made of necessity a change also of the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 13, E'For he of whom these things are spoken pertaineth to another tribe, of which no man gave attendance at the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 14, E'For it is evident that our Lord sprang out of Juda; of which tribe Moses spake nothing concerning priesthood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 15, E'And it is yet far more evident: for that after the similitude of Melchisedec there ariseth another priest,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 16, E'Who is made, not after the law of a carnal commandment, but after the power of an endless life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 17, E'For he testifieth, Thou art a priest for ever after the order of Melchisedec.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 18, E'For there is verily a disannulling of the commandment going before for the weakness and unprofitableness thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 19, E'For the law made nothing perfect, but the bringing in of a better hope did; by the which we draw nigh unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 20, E'And inasmuch as not without an oath he was made priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 21, E'(For those priests were made without an oath; but this with an oath by him that said unto him, The Lord sware and will not repent, Thou art a priest for ever after the order of Melchisedec:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 22, E'By so much was Jesus made a surety of a better testament.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 23, E'And they truly were many priests, because they were not suffered to continue by reason of death:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 24, E'But this man, because he continueth ever, hath an unchangeable priesthood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 25, E'Wherefore he is able also to save them to the uttermost that come unto God by him, seeing he ever liveth to make intercession for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 26, E'For such an high priest became us, who is holy, harmless, undefiled, separate from sinners, and made higher than the heavens;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 27, E'Who needeth not daily, as those high priests, to offer up sacrifice, first for his own sins, and then for the peopleâ€™s: for this he did once, when he offered up himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 7, 28, E'For the law maketh men high priests which have infirmity; but the word of the oath, which was since the law, maketh the Son, who is consecrated for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 1, E'Now of the things which we have spoken this is the sum: We have such an high priest, who is set on the right hand of the throne of the Majesty in the heavens;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 2, E'A minister of the sanctuary, and of the true tabernacle, which the Lord pitched, and not man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 3, E'For every high priest is ordained to offer gifts and sacrifices: wherefore it is of necessity that this man have somewhat also to offer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 4, E'For if he were on earth, he should not be a priest, seeing that there are priests that offer gifts according to the law:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 5, E'Who serve unto the example and shadow of heavenly things, as Moses was admonished of God when he was about to make the tabernacle: for, See, saith he, that thou make all things according to the pattern shewed to thee in the mount.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 6, E'But now hath he obtained a more excellent ministry, by how much also he is the mediator of a better covenant, which was established upon better promises.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 7, E'For if that first covenant had been faultless, then should no place have been sought for the second.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 8, E'For finding fault with them, he saith, Behold, the days come, saith the Lord, when I will make a new covenant with the house of Israel and with the house of Judah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 9, E'Not according to the covenant that I made with their fathers in the day when I took them by the hand to lead them out of the land of Egypt; because they continued not in my covenant, and I regarded them not, saith the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 10, E'For this is the covenant that I will make with the house of Israel after those days, saith the Lord; I will put my laws into their mind, and write them in their hearts: and I will be to them a God, and they shall be to me a people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 11, E'And they shall not teach every man his neighbour, and every man his brother, saying, Know the Lord: for all shall know me, from the least to the greatest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 12, E'For I will be merciful to their unrighteousness, and their sins and their iniquities will I remember no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 8, 13, E'In that he saith, A new covenant, he hath made the first old. Now that which decayeth and waxeth old is ready to vanish away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 1, E'Then verily the first covenant had also ordinances of divine service, and a worldly sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 2, E'For there was a tabernacle made; the first, wherein was the candlestick, and the table, and the shewbread; which is called the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 3, E'And after the second veil, the tabernacle which is called the Holiest of all;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 4, E'Which had the golden censer, and the ark of the covenant overlaid round about with gold, wherein was the golden pot that had manna, and Aaronâ€™s rod that budded, and the tables of the covenant;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 5, E'And over it the cherubims of glory shadowing the mercyseat; of which we cannot now speak particularly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 6, E'Now when these things were thus ordained, the priests went always into the first tabernacle, accomplishing the service of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 7, E'But into the second went the high priest alone once every year, not without blood, which he offered for himself, and for the errors of the people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 8, E'The Holy Ghost this signifying, that the way into the holiest of all was not yet made manifest, while as the first tabernacle was yet standing:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 9, E'Which was a figure for the time then present, in which were offered both gifts and sacrifices, that could not make him that did the service perfect, as pertaining to the conscience;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 10, E'Which stood only in meats and drinks, and divers washings, and carnal ordinances, imposed on them until the time of reformation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 11, E'But Christ being come an high priest of good things to come, by a greater and more perfect tabernacle, not made with hands, that is to say, not of this building;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 12, E'Neither by the blood of goats and calves, but by his own blood he entered in once into the holy place, having obtained eternal redemption for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 13, E'For if the blood of bulls and of goats, and the ashes of an heifer sprinkling the unclean, sanctifieth to the purifying of the flesh:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 14, E'How much more shall the blood of Christ, who through the eternal Spirit offered himself without spot to God, purge your conscience from dead works to serve the living God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 15, E'And for this cause he is the mediator of the new testament, that by means of death, for the redemption of the transgressions that were under the first testament, they which are called might receive the promise of eternal inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 16, E'For where a testament is, there must also of necessity be the death of the testator.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 17, E'For a testament is of force after men are dead: otherwise it is of no strength at all while the testator liveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 18, E'Whereupon neither the first testament was dedicated without blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 19, E'For when Moses had spoken every precept to all the people according to the law, he took the blood of calves and of goats, with water, and scarlet wool, and hyssop, and sprinkled both the book, and all the people,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 20, E'Saying, This is the blood of the testament which God hath enjoined unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 21, E'Moreover he sprinkled with blood both the tabernacle, and all the vessels of the ministry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 22, E'And almost all things are by the law purged with blood; and without shedding of blood is no remission.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 23, E'It was therefore necessary that the patterns of things in the heavens should be purified with these; but the heavenly things themselves with better sacrifices than these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 24, E'For Christ is not entered into the holy places made with hands, which are the figures of the true; but into heaven itself, now to appear in the presence of God for us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 25, E'Nor yet that he should offer himself often, as the high priest entereth into the holy place every year with blood of others;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 26, E'For then must he often have suffered since the foundation of the world: but now once in the end of the world hath he appeared to put away sin by the sacrifice of himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 27, E'And as it is appointed unto men once to die, but after this the judgment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 9, 28, E'So Christ was once offered to bear the sins of many; and unto them that look for him shall he appear the second time without sin unto salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 1, E'For the law having a shadow of good things to come, and not the very image of the things, can never with those sacrifices which they offered year by year continually make the comers thereunto perfect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 2, E'For then would they not have ceased to be offered? because that the worshippers once purged should have had no more conscience of sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 3, E'But in those sacrifices there is a remembrance again made of sins every year.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 4, E'For it is not possible that the blood of bulls and of goats should take away sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 5, E'Wherefore when he cometh into the world, he saith, Sacrifice and offering thou wouldest not, but a body hast thou prepared me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 6, E'In burnt offerings and sacrifices for sin thou hast had no pleasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 7, E'Then said I, Lo, I come (in the volume of the book it is written of me,) to do thy will, O God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 8, E'Above when he said, Sacrifice and offering and burnt offerings and offering for sin thou wouldest not, neither hadst pleasure therein; which are offered by the law;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 9, E'Then said he, Lo, I come to do thy will, O God. He taketh away the first, that he may establish the second.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 10, E'By the which will we are sanctified through the offering of the body of Jesus Christ once for all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 11, E'And every priest standeth daily ministering and offering oftentimes the same sacrifices, which can never take away sins:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 12, E'But this man, after he had offered one sacrifice for sins for ever, sat down on the right hand of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 13, E'From henceforth expecting till his enemies be made his footstool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 14, E'For by one offering he hath perfected for ever them that are sanctified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 15, E'Whereof the Holy Ghost also is a witness to us: for after that he had said before,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 16, E'This is the covenant that I will make with them after those days, saith the Lord, I will put my laws into their hearts, and in their minds will I write them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 17, E'And their sins and iniquities will I remember no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 18, E'Now where remission of these is, there is no more offering for sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 19, E'Having therefore, brethren, boldness to enter into the holiest by the blood of Jesus,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 20, E'By a new and living way, which he hath consecrated for us, through the veil, that is to say, his flesh;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 21, E'And having an high priest over the house of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 22, E'Let us draw near with a true heart in full assurance of faith, having our hearts sprinkled from an evil conscience, and our bodies washed with pure water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 23, E'Let us hold fast the profession of our faith without wavering; (for he is faithful that promised;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 24, E'And let us consider one another to provoke unto love and to good works:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 25, E'Not forsaking the assembling of ourselves together, as the manner of some is; but exhorting one another: and so much the more, as ye see the day approaching.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 26, E'For if we sin wilfully after that we have received the knowledge of the truth, there remaineth no more sacrifice for sins,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 27, E'But a certain fearful looking for of judgment and fiery indignation, which shall devour the adversaries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 28, E'He that despised Mosesâ€™ law died without mercy under two or three witnesses:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 29, E'Of how much sorer punishment, suppose ye, shall he be thought worthy, who hath trodden under foot the Son of God, and hath counted the blood of the covenant, wherewith he was sanctified, an unholy thing, and hath done despite unto the Spirit of grace?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 30, E'For we know him that hath said, Vengeance belongeth unto me, I will recompense, saith the Lord. And again, The Lord shall judge his people.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Hebrews') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 31, E'It is a fearful thing to fall into the hands of the living God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 32, E'But call to remembrance the former days, in which, after ye were illuminated, ye endured a great fight of afflictions;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 33, E'Partly, whilst ye were made a gazingstock both by reproaches and afflictions; and partly, whilst ye became companions of them that were so used.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 34, E'For ye had compassion of me in my bonds, and took joyfully the spoiling of your goods, knowing in yourselves that ye have in heaven a better and an enduring substance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 35, E'Cast not away therefore your confidence, which hath great recompence of reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 36, E'For ye have need of patience, that, after ye have done the will of God, ye might receive the promise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 37, E'For yet a little while, and he that shall come will come, and will not tarry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 38, E'Now the just shall live by faith: but if any man draw back, my soul shall have no pleasure in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 10, 39, E'But we are not of them who draw back unto perdition; but of them that believe to the saving of the soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 1, E'Now faith is the substance of things hoped for, the evidence of things not seen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 2, E'For by it the elders obtained a good report.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 3, E'Through faith we understand that the worlds were framed by the word of God, so that things which are seen were not made of things which do appear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 4, E'By faith Abel offered unto God a more excellent sacrifice than Cain, by which he obtained witness that he was righteous, God testifying of his gifts: and by it he being dead yet speaketh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 5, E'By faith Enoch was translated that he should not see death; and was not found, because God had translated him: for before his translation he had this testimony, that he pleased God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 6, E'But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 7, E'By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house; by the which he condemned the world, and became heir of the righteousness which is by faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 8, E'By faith Abraham, when he was called to go out into a place which he should after receive for an inheritance, obeyed; and he went out, not knowing whither he went.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 9, E'By faith he sojourned in the land of promise, as in a strange country, dwelling in tabernacles with Isaac and Jacob, the heirs with him of the same promise:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 10, E'For he looked for a city which hath foundations, whose builder and maker is God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 11, E'Through faith also Sara herself received strength to conceive seed, and was delivered of a child when she was past age, because she judged him faithful who had promised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 12, E'Therefore sprang there even of one, and him as good as dead, so many as the stars of the sky in multitude, and as the sand which is by the sea shore innumerable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 13, E'These all died in faith, not having received the promises, but having seen them afar off, and were persuaded of them, and embraced them, and confessed that they were strangers and pilgrims on the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 14, E'For they that say such things declare plainly that they seek a country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 15, E'And truly, if they had been mindful of that country from whence they came out, they might have had opportunity to have returned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 16, E'But now they desire a better country, that is, an heavenly: wherefore God is not ashamed to be called their God: for he hath prepared for them a city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 17, E'By faith Abraham, when he was tried, offered up Isaac: and he that had received the promises offered up his only begotten son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 18, E'Of whom it was said, That in Isaac shall thy seed be called:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 19, E'Accounting that God was able to raise him up, even from the dead; from whence also he received him in a figure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 20, E'By faith Isaac blessed Jacob and Esau concerning things to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 21, E'By faith Jacob, when he was a dying, blessed both the sons of Joseph; and worshipped, leaning upon the top of his staff.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 22, E'By faith Joseph, when he died, made mention of the departing of the children of Israel; and gave commandment concerning his bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 23, E'By faith Moses, when he was born, was hid three months of his parents, because they saw he was a proper child; and they were not afraid of the kingâ€™s commandment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 24, E'By faith Moses, when he was come to years, refused to be called the son of Pharaohâ€™s daughter;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 25, E'Choosing rather to suffer affliction with the people of God, than to enjoy the pleasures of sin for a season;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 26, E'Esteeming the reproach of Christ greater riches than the treasures in Egypt: for he had respect unto the recompence of the reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 27, E'By faith he forsook Egypt, not fearing the wrath of the king: for he endured, as seeing him who is invisible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 28, E'Through faith he kept the passover, and the sprinkling of blood, lest he that destroyed the firstborn should touch them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 29, E'By faith they passed through the Red sea as by dry land: which the Egyptians assaying to do were drowned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 30, E'By faith the walls of Jericho fell down, after they were compassed about seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 31, E'By faith the harlot Rahab perished not with them that believed not, when she had received the spies with peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 32, E'And what shall I more say? for the time would fail me to tell of Gedeon, and of Barak, and of Samson, and of Jephthae; of David also, and Samuel, and of the prophets:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 33, E'Who through faith subdued kingdoms, wrought righteousness, obtained promises, stopped the mouths of lions,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 34, E'Quenched the violence of fire, escaped the edge of the sword, out of weakness were made strong, waxed valiant in fight, turned to flight the armies of the aliens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 35, E'Women received their dead raised to life again: and others were tortured, not accepting deliverance; that they might obtain a better resurrection:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 36, E'And others had trial of cruel mockings and scourgings, yea, moreover of bonds and imprisonment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 37, E'They were stoned, they were sawn asunder, were tempted, were slain with the sword: they wandered about in sheepskins and goatskins; being destitute, afflicted, tormented;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 38, E'(Of whom the world was not worthy:) they wandered in deserts, and in mountains, and in dens and caves of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 39, E'And these all, having obtained a good report through faith, received not the promise:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 11, 40, E'God having provided some better thing for us, that they without us should not be made perfect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 1, E'Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 2, E'Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 3, E'For consider him that endured such contradiction of sinners against himself, lest ye be wearied and faint in your minds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 4, E'Ye have not yet resisted unto blood, striving against sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 5, E'And ye have forgotten the exhortation which speaketh unto you as unto children, My son, despise not thou the chastening of the Lord, nor faint when thou art rebuked of him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 6, E'For whom the Lord loveth he chasteneth, and scourgeth every son whom he receiveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 7, E'If ye endure chastening, God dealeth with you as with sons; for what son is he whom the father chasteneth not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 8, E'But if ye be without chastisement, whereof all are partakers, then are ye bastards, and not sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 9, E'Furthermore we have had fathers of our flesh which corrected us, and we gave them reverence: shall we not much rather be in subjection unto the Father of spirits, and live?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 10, E'For they verily for a few days chastened us after their own pleasure; but he for our profit, that we might be partakers of his holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 11, E'Now no chastening for the present seemeth to be joyous, but grievous: nevertheless afterward it yieldeth the peaceable fruit of righteousness unto them which are exercised thereby.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 12, E'Wherefore lift up the hands which hang down, and the feeble knees;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 13, E'And make straight paths for your feet, lest that which is lame be turned out of the way; but let it rather be healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 14, E'Follow peace with all men, and holiness, without which no man shall see the Lord:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 15, E'Looking diligently lest any man fail of the grace of God; lest any root of bitterness springing up trouble you, and thereby many be defiled;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 16, E'Lest there be any fornicator, or profane person, as Esau, who for one morsel of meat sold his birthright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 17, E'For ye know how that afterward, when he would have inherited the blessing, he was rejected: for he found no place of repentance, though he sought it carefully with tears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 18, E'For ye are not come unto the mount that might be touched, and that burned with fire, nor unto blackness, and darkness, and tempest,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 19, E'And the sound of a trumpet, and the voice of words; which voice they that heard intreated that the word should not be spoken to them any more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 20, E'(For they could not endure that which was commanded, And if so much as a beast touch the mountain, it shall be stoned, or thrust through with a dart:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 21, E'And so terrible was the sight, that Moses said, I exceedingly fear and quake:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 22, E'But ye are come unto mount Sion, and unto the city of the living God, the heavenly Jerusalem, and to an innumerable company of angels,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 23, E'To the general assembly and church of the firstborn, which are written in heaven, and to God the Judge of all, and to the spirits of just men made perfect,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 24, E'And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 25, E'See that ye refuse not him that speaketh. For if they escaped not who refused him that spake on earth, much more shall not we escape, if we turn away from him that speaketh from heaven:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 26, E'Whose voice then shook the earth: but now he hath promised, saying, Yet once more I shake not the earth only, but also heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 27, E'And this word, Yet once more, signifieth the removing of those things that are shaken, as of things that are made, that those things which cannot be shaken may remain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 28, E'Wherefore we receiving a kingdom which cannot be moved, let us have grace, whereby we may serve God acceptably with reverence and godly fear:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 12, 29, E'For our God is a consuming fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 1, E'Let brotherly love continue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 2, E'Be not forgetful to entertain strangers: for thereby some have entertained angels unawares.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 3, E'Remember them that are in bonds, as bound with them; and them which suffer adversity, as being yourselves also in the body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 4, E'Marriage is honourable in all, and the bed undefiled: but whoremongers and adulterers God will judge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 5, E'Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 6, E'So that we may boldly say, The Lord is my helper, and I will not fear what man shall do unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 7, E'Remember them which have the rule over you, who have spoken unto you the word of God: whose faith follow, considering the end of their conversation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 8, E'Jesus Christ the same yesterday, and to day, and for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 9, E'Be not carried about with divers and strange doctrines. For it is a good thing that the heart be established with grace; not with meats, which have not profited them that have been occupied therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 10, E'We have an altar, whereof they have no right to eat which serve the tabernacle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 11, E'For the bodies of those beasts, whose blood is brought into the sanctuary by the high priest for sin, are burned without the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 12, E'Wherefore Jesus also, that he might sanctify the people with his own blood, suffered without the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 13, E'Let us go forth therefore unto him without the camp, bearing his reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 14, E'For here have we no continuing city, but we seek one to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 15, E'By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 16, E'But to do good and to communicate forget not: for with such sacrifices God is well pleased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 17, E'Obey them that have the rule over you, and submit yourselves: for they watch for your souls, as they that must give account, that they may do it with joy, and not with grief: for that is unprofitable for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 18, E'Pray for us: for we trust we have a good conscience, in all things willing to live honestly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 19, E'But I beseech you the rather to do this, that I may be restored to you the sooner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 20, E'Now the God of peace, that brought again from the dead our Lord Jesus, that great shepherd of the sheep, through the blood of the everlasting covenant,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 21, E'Make you perfect in every good work to do his will, working in you that which is wellpleasing in his sight, through Jesus Christ; to whom be glory for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 22, E'And I beseech you, brethren, suffer the word of exhortation: for I have written a letter unto you in few words.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Hebrews') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 23, E'Know ye that our brother Timothy is set at liberty; with whom, if he come shortly, I will see you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 24, E'Salute all them that have the rule over you, and all the saints. They of Italy salute you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'b3634d0f-1c09-4ef6-babc-377965751904', 13, 25, E'Grace be with you all. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Hebrews') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 1, E'James, a servant of God and of the Lord Jesus Christ, to the twelve tribes which are scattered abroad, greeting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 2, E'My brethren, count it all joy when ye fall into divers temptations;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 3, E'Knowing this, that the trying of your faith worketh patience.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 4, E'But let patience have her perfect work, that ye may be perfect and entire, wanting nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 5, E'If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 6, E'But let him ask in faith, nothing wavering. For he that wavereth is like a wave of the sea driven with the wind and tossed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 7, E'For let not that man think that he shall receive any thing of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 8, E'A double minded man is unstable in all his ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 9, E'Let the brother of low degree rejoice in that he is exalted:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 10, E'But the rich, in that he is made low: because as the flower of the grass he shall pass away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 11, E'For the sun is no sooner risen with a burning heat, but it withereth the grass, and the flower thereof falleth, and the grace of the fashion of it perisheth: so also shall the rich man fade away in his ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 12, E'Blessed is the man that endureth temptation: for when he is tried, he shall receive the crown of life, which the Lord hath promised to them that love him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 13, E'Let no man say when he is tempted, I am tempted of God: for God cannot be tempted with evil, neither tempteth he any man:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 14, E'But every man is tempted, when he is drawn away of his own lust, and enticed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 15, E'Then when lust hath conceived, it bringeth forth sin: and sin, when it is finished, bringeth forth death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 16, E'Do not err, my beloved brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 17, E'Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 18, E'Of his own will begat he us with the word of truth, that we should be a kind of firstfruits of his creatures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 19, E'Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 20, E'For the wrath of man worketh not the righteousness of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 21, E'Wherefore lay apart all filthiness and superfluity of naughtiness, and receive with meekness the engrafted word, which is able to save your souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 22, E'But be ye doers of the word, and not hearers only, deceiving your own selves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 23, E'For if any be a hearer of the word, and not a doer, he is like unto a man beholding his natural face in a glass:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 24, E'For he beholdeth himself, and goeth his way, and straightway forgetteth what manner of man he was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 25, E'But whoso looketh into the perfect law of liberty, and continueth therein, he being not a forgetful hearer, but a doer of the work, this man shall be blessed in his deed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 26, E'If any man among you seem to be religious, and bridleth not his tongue, but deceiveth his own heart, this manâ€™s religion is vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 1, 27, E'Pure religion and undefiled before God and the Father is this, To visit the fatherless and widows in their affliction, and to keep himself unspotted from the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 1, E'My brethren, have not the faith of our Lord Jesus Christ, the Lord of glory, with respect of persons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 2, E'For if there come unto your assembly a man with a gold ring, in goodly apparel, and there come in also a poor man in vile raiment;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 3, E'And ye have respect to him that weareth the gay clothing, and say unto him, Sit thou here in a good place; and say to the poor, Stand thou there, or sit here under my footstool:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 4, E'Are ye not then partial in yourselves, and are become judges of evil thoughts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 5, E'Hearken, my beloved brethren, Hath not God chosen the poor of this world rich in faith, and heirs of the kingdom which he hath promised to them that love him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 6, E'But ye have despised the poor. Do not rich men oppress you, and draw you before the judgment seats?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 7, E'Do not they blaspheme that worthy name by the which ye are called?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 8, E'If ye fulfil the royal law according to the scripture, Thou shalt love thy neighbour as thyself, ye do well:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 9, E'But if ye have respect to persons, ye commit sin, and are convinced of the law as transgressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 10, E'For whosoever shall keep the whole law, and yet offend in one point, he is guilty of all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 11, E'For he that said, Do not commit adultery, said also, Do not kill. Now if thou commit no adultery, yet if thou kill, thou art become a transgressor of the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 12, E'So speak ye, and so do, as they that shall be judged by the law of liberty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 13, E'For he shall have judgment without mercy, that hath shewed no mercy; and mercy rejoiceth against judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 14, E'What doth it profit, my brethren, though a man say he hath faith, and have not works? can faith save him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 15, E'If a brother or sister be naked, and destitute of daily food,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 16, E'And one of you say unto them, Depart in peace, be ye warmed and filled; notwithstanding ye give them not those things which are needful to the body; what doth it profit?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 17, E'Even so faith, if it hath not works, is dead, being alone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 18, E'Yea, a man may say, Thou hast faith, and I have works: shew me thy faith without thy works, and I will shew thee my faith by my works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 19, E'Thou believest that there is one God; thou doest well: the devils also believe, and tremble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 20, E'But wilt thou know, O vain man, that faith without works is dead?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 21, E'Was not Abraham our father justified by works, when he had offered Isaac his son upon the altar?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 22, E'Seest thou how faith wrought with his works, and by works was faith made perfect?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 23, E'And the scripture was fulfilled which saith, Abraham believed God, and it was imputed unto him for righteousness: and he was called the Friend of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 24, E'Ye see then how that by works a man is justified, and not by faith only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 25, E'Likewise also was not Rahab the harlot justified by works, when she had received the messengers, and had sent them out another way?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 2, 26, E'For as the body without the spirit is dead, so faith without works is dead also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 1, E'My brethren, be not many masters, knowing that we shall receive the greater condemnation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 2, E'For in many things we offend all. If any man offend not in word, the same is a perfect man, and able also to bridle the whole body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 3, E'Behold, we put bits in the horsesâ€™ mouths, that they may obey us; and we turn about their whole body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 4, E'Behold also the ships, which though they be so great, and are driven of fierce winds, yet are they turned about with a very small helm, whithersoever the governor listeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 5, E'Even so the tongue is a little member, and boasteth great things. Behold, how great a matter a little fire kindleth!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 6, E'And the tongue is a fire, a world of iniquity: so is the tongue among our members, that it defileth the whole body, and setteth on fire the course of nature; and it is set on fire of hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 7, E'For every kind of beasts, and of birds, and of serpents, and of things in the sea, is tamed, and hath been tamed of mankind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 8, E'But the tongue can no man tame; it is an unruly evil, full of deadly poison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 9, E'Therewith bless we God, even the Father; and therewith curse we men, which are made after the similitude of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 10, E'Out of the same mouth proceedeth blessing and cursing. My brethren, these things ought not so to be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 11, E'Doth a fountain send forth at the same place sweet water and bitter?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 12, E'Can the fig tree, my brethren, bear olive berries? either a vine, figs? so can no fountain both yield salt water and fresh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 13, E'Who is a wise man and endued with knowledge among you? let him shew out of a good conversation his works with meekness of wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 14, E'But if ye have bitter envying and strife in your hearts, glory not, and lie not against the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 15, E'This wisdom descendeth not from above, but is earthly, sensual, devilish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 16, E'For where envying and strife is, there is confusion and every evil work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 17, E'But the wisdom that is from above is first pure, then peaceable, gentle, and easy to be intreated, full of mercy and good fruits, without partiality, and without hypocrisy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 3, 18, E'And the fruit of righteousness is sown in peace of them that make peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 1, E'From whence come wars and fightings among you? come they not hence, even of your lusts that war in your members?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 2, E'Ye lust, and have not: ye kill, and desire to have, and cannot obtain: ye fight and war, yet ye have not, because ye ask not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 3, E'Ye ask, and receive not, because ye ask amiss, that ye may consume it upon your lusts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 4, E'Ye adulterers and adulteresses, know ye not that the friendship of the world is enmity with God? whosoever therefore will be a friend of the world is the enemy of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 5, E'Do ye think that the scripture saith in vain, The spirit that dwelleth in us lusteth to envy?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 6, E'But he giveth more grace. Wherefore he saith, God resisteth the proud, but giveth grace unto the humble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 7, E'Submit yourselves therefore to God. Resist the devil, and he will flee from you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 8, E'Draw nigh to God, and he will draw nigh to you. Cleanse your hands, ye sinners; and purify your hearts, ye double minded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 9, E'Be afflicted, and mourn, and weep: let your laughter be turned to mourning, and your joy to heaviness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 10, E'Humble yourselves in the sight of the Lord, and he shall lift you up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 11, E'Speak not evil one of another, brethren. He that speaketh evil of his brother, and judgeth his brother, speaketh evil of the law, and judgeth the law: but if thou judge the law, thou art not a doer of the law, but a judge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 12, E'There is one lawgiver, who is able to save and to destroy: who art thou that judgest another?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 13, E'Go to now, ye that say, To day or to morrow we will go into such a city, and continue there a year, and buy and sell, and get gain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 14, E'Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 15, E'For that ye ought to say, If the Lord will, we shall live, and do this, or that.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 16, E'But now ye rejoice in your boastings: all such rejoicing is evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 4, 17, E'Therefore to him that knoweth to do good, and doeth it not, to him it is sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 1, E'Go to now, ye rich men, weep and howl for your miseries that shall come upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 2, E'Your riches are corrupted, and your garments are motheaten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 3, E'Your gold and silver is cankered; and the rust of them shall be a witness against you, and shall eat your flesh as it were fire. Ye have heaped treasure together for the last days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 4, E'Behold, the hire of the labourers who have reaped down your fields, which is of you kept back by fraud, crieth: and the cries of them which have reaped are entered into the ears of the Lord of sabaoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 5, E'Ye have lived in pleasure on the earth, and been wanton; ye have nourished your hearts, as in a day of slaughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 6, E'Ye have condemned and killed the just; and he doth not resist you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 7, E'Be patient therefore, brethren, unto the coming of the Lord. Behold, the husbandman waiteth for the precious fruit of the earth, and hath long patience for it, until he receive the early and latter rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 8, E'Be ye also patient; stablish your hearts: for the coming of the Lord draweth nigh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 9, E'Grudge not one against another, brethren, lest ye be condemned: behold, the judge standeth before the door.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 10, E'Take, my brethren, the prophets, who have spoken in the name of the Lord, for an example of suffering affliction, and of patience.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 11, E'Behold, we count them happy which endure. Ye have heard of the patience of Job, and have seen the end of the Lord; that the Lord is very pitiful, and of tender mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 12, E'But above all things, my brethren, swear not, neither by heaven, neither by the earth, neither by any other oath: but let your yea be yea; and your nay, nay; lest ye fall into condemnation.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'James') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 13, E'Is any among you afflicted? let him pray. Is any merry? let him sing psalms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 14, E'Is any sick among you? let him call for the elders of the church; and let them pray over him, anointing him with oil in the name of the Lord:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 15, E'And the prayer of faith shall save the sick, and the Lord shall raise him up; and if he have committed sins, they shall be forgiven him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 16, E'Confess your faults one to another, and pray one for another, that ye may be healed. The effectual fervent prayer of a righteous man availeth much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 17, E'Elias was a man subject to like passions as we are, and he prayed earnestly that it might not rain: and it rained not on the earth by the space of three years and six months.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 18, E'And he prayed again, and the heaven gave rain, and the earth brought forth her fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 19, E'Brethren, if any of you do err from the truth, and one convert him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0762364b-38a6-4a52-97d8-d9140a103e06', 5, 20, E'Let him know, that he which converteth the sinner from the error of his way shall save a soul from death, and shall hide a multitude of sins.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'James') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 1, E'Peter, an apostle of Jesus Christ, to the strangers scattered throughout Pontus, Galatia, Cappadocia, Asia, and Bithynia,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 2, E'Elect according to the foreknowledge of God the Father, through sanctification of the Spirit, unto obedience and sprinkling of the blood of Jesus Christ: Grace unto you, and peace, be multiplied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 3, E'Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 4, E'To an inheritance incorruptible, and undefiled, and that fadeth not away, reserved in heaven for you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 5, E'Who are kept by the power of God through faith unto salvation ready to be revealed in the last time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 6, E'Wherein ye greatly rejoice, though now for a season, if need be, ye are in heaviness through manifold temptations:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 7, E'That the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire, might be found unto praise and honour and glory at the appearing of Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 8, E'Whom having not seen, ye love; in whom, though now ye see him not, yet believing, ye rejoice with joy unspeakable and full of glory:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 9, E'Receiving the end of your faith, even the salvation of your souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 10, E'Of which salvation the prophets have enquired and searched diligently, who prophesied of the grace that should come unto you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 11, E'Searching what, or what manner of time the Spirit of Christ which was in them did signify, when it testified beforehand the sufferings of Christ, and the glory that should follow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 12, E'Unto whom it was revealed, that not unto themselves, but unto us they did minister the things, which are now reported unto you by them that have preached the gospel unto you with the Holy Ghost sent down from heaven; which things the angels desire to look into.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 13, E'Wherefore gird up the loins of your mind, be sober, and hope to the end for the grace that is to be brought unto you at the revelation of Jesus Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 14, E'As obedient children, not fashioning yourselves according to the former lusts in your ignorance:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 15, E'But as he which hath called you is holy, so be ye holy in all manner of conversation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 16, E'Because it is written, Be ye holy; for I am holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 17, E'And if ye call on the Father, who without respect of persons judgeth according to every manâ€™s work, pass the time of your sojourning here in fear:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 18, E'Forasmuch as ye know that ye were not redeemed with corruptible things, as silver and gold, from your vain conversation received by tradition from your fathers;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 19, E'But with the precious blood of Christ, as of a lamb without blemish and without spot:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 20, E'Who verily was foreordained before the foundation of the world, but was manifest in these last times for you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 21, E'Who by him do believe in God, that raised him up from the dead, and gave him glory; that your faith and hope might be in God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 22, E'Seeing ye have purified your souls in obeying the truth through the Spirit unto unfeigned love of the brethren, see that ye love one another with a pure heart fervently:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 23, E'Being born again, not of corruptible seed, but of incorruptible, by the word of God, which liveth and abideth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 24, E'For all flesh is as grass, and all the glory of man as the flower of grass. The grass withereth, and the flower thereof falleth away:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 1, 25, E'But the word of the Lord endureth for ever. And this is the word which by the gospel is preached unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 1, E'Wherefore laying aside all malice, and all guile, and hypocrisies, and envies, and all evil speakings,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 2, E'As newborn babes, desire the sincere milk of the word, that ye may grow thereby:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 3, E'If so be ye have tasted that the Lord is gracious.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 4, E'To whom coming, as unto a living stone, disallowed indeed of men, but chosen of God, and precious,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 5, E'Ye also, as lively stones, are built up a spiritual house, an holy priesthood, to offer up spiritual sacrifices, acceptable to God by Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 6, E'Wherefore also it is contained in the scripture, Behold, I lay in Sion a chief corner stone, elect, precious: and he that believeth on him shall not be confounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 7, E'Unto you therefore which believe he is precious: but unto them which be disobedient, the stone which the builders disallowed, the same is made the head of the corner,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 8, E'And a stone of stumbling, and a rock of offence, even to them which stumble at the word, being disobedient: whereunto also they were appointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 9, E'But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 10, E'Which in time past were not a people, but are now the people of God: which had not obtained mercy, but now have obtained mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 11, E'Dearly beloved, I beseech you as strangers and pilgrims, abstain from fleshly lusts, which war against the soul;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 12, E'Having your conversation honest among the Gentiles: that, whereas they speak against you as evildoers, they may by your good works, which they shall behold, glorify God in the day of visitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 13, E'Submit yourselves to every ordinance of man for the Lordâ€™s sake: whether it be to the king, as supreme;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 14, E'Or unto governors, as unto them that are sent by him for the punishment of evildoers, and for the praise of them that do well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 15, E'For so is the will of God, that with well doing ye may put to silence the ignorance of foolish men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 16, E'As free, and not using your liberty for a cloke of maliciousness, but as the servants of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 17, E'Honour all men. Love the brotherhood. Fear God. Honour the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 18, E'Servants, be subject to your masters with all fear; not only to the good and gentle, but also to the froward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 19, E'For this is thankworthy, if a man for conscience toward God endure grief, suffering wrongfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 20, E'For what glory is it, if, when ye be buffeted for your faults, ye shall take it patiently? but if, when ye do well, and suffer for it, ye take it patiently, this is acceptable with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 21, E'For even hereunto were ye called: because Christ also suffered for us, leaving us an example, that ye should follow his steps:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 22, E'Who did no sin, neither was guile found in his mouth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 23, E'Who, when he was reviled, reviled not again; when he suffered, he threatened not; but committed himself to him that judgeth righteously:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 24, E'Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 2, 25, E'For ye were as sheep going astray; but are now returned unto the Shepherd and Bishop of your souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 1, E'Likewise, ye wives, be in subjection to your own husbands; that, if any obey not the word, they also may without the word be won by the conversation of the wives;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 2, E'While they behold your chaste conversation coupled with fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 3, E'Whose adorning let it not be that outward adorning of plaiting the hair, and of wearing of gold, or of putting on of apparel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 4, E'But let it be the hidden man of the heart, in that which is not corruptible, even the ornament of a meek and quiet spirit, which is in the sight of God of great price.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 5, E'For after this manner in the old time the holy women also, who trusted in God, adorned themselves, being in subjection unto their own husbands:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 6, E'Even as Sara obeyed Abraham, calling him lord: whose daughters ye are, as long as ye do well, and are not afraid with any amazement.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 7, E'Likewise, ye husbands, dwell with them according to knowledge, giving honour unto the wife, as unto the weaker vessel, and as being heirs together of the grace of life; that your prayers be not hindered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 8, E'Finally, be ye all of one mind, having compassion one of another, love as brethren, be pitiful, be courteous:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 9, E'Not rendering evil for evil, or railing for railing: but contrariwise blessing; knowing that ye are thereunto called, that ye should inherit a blessing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 10, E'For he that will love life, and see good days, let him refrain his tongue from evil, and his lips that they speak no guile:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 11, E'Let him eschew evil, and do good; let him seek peace, and ensue it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 12, E'For the eyes of the Lord are over the righteous, and his ears are open unto their prayers: but the face of the Lord is against them that do evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 13, E'And who is he that will harm you, if ye be followers of that which is good?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 14, E'But and if ye suffer for righteousnessâ€™ sake, happy are ye: and be not afraid of their terror, neither be troubled;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 15, E'But sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 16, E'Having a good conscience; that, whereas they speak evil of you, as of evildoers, they may be ashamed that falsely accuse your good conversation in Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 17, E'For it is better, if the will of God be so, that ye suffer for well doing, than for evil doing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 18, E'For Christ also hath once suffered for sins, the just for the unjust, that he might bring us to God, being put to death in the flesh, but quickened by the Spirit:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 19, E'By which also he went and preached unto the spirits in prison;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 20, E'Which sometime were disobedient, when once the longsuffering of God waited in the days of Noah, while the ark was a preparing, wherein few, that is, eight souls were saved by water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 21, E'The like figure whereunto even baptism doth also now save us (not the putting away of the filth of the flesh, but the answer of a good conscience toward God,) by the resurrection of Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 3, 22, E'Who is gone into heaven, and is on the right hand of God; angels and authorities and powers being made subject unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 1, E'Forasmuch then as Christ hath suffered for us in the flesh, arm yourselves likewise with the same mind: for he that hath suffered in the flesh hath ceased from sin;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 2, E'That he no longer should live the rest of his time in the flesh to the lusts of men, but to the will of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 3, E'For the time past of our life may suffice us to have wrought the will of the Gentiles, when we walked in lasciviousness, lusts, excess of wine, revellings, banquetings, and abominable idolatries:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 4, E'Wherein they think it strange that ye run not with them to the same excess of riot, speaking evil of you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 5, E'Who shall give account to him that is ready to judge the quick and the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 6, E'For for this cause was the gospel preached also to them that are dead, that they might be judged according to men in the flesh, but live according to God in the spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 7, E'But the end of all things is at hand: be ye therefore sober, and watch unto prayer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 8, E'And above all things have fervent charity among yourselves: for charity shall cover the multitude of sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 9, E'Use hospitality one to another without grudging.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 10, E'As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 11, E'If any man speak, let him speak as the oracles of God; if any man minister, let him do it as of the ability which God giveth: that God in all things may be glorified through Jesus Christ, to whom be praise and dominion for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 12, E'Beloved, think it not strange concerning the fiery trial which is to try you, as though some strange thing happened unto you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 13, E'But rejoice, inasmuch as ye are partakers of Christâ€™s sufferings; that, when his glory shall be revealed, ye may be glad also with exceeding joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 14, E'If ye be reproached for the name of Christ, happy are ye; for the spirit of glory and of God resteth upon you: on their part he is evil spoken of, but on your part he is glorified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 15, E'But let none of you suffer as a murderer, or as a thief, or as an evildoer, or as a busybody in other menâ€™s matters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 16, E'Yet if any man suffer as a Christian, let him not be ashamed; but let him glorify God on this behalf.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 17, E'For the time is come that judgment must begin at the house of God: and if it first begin at us, what shall the end be of them that obey not the gospel of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 18, E'And if the righteous scarcely be saved, where shall the ungodly and the sinner appear?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 4, 19, E'Wherefore let them that suffer according to the will of God commit the keeping of their souls to him in well doing, as unto a faithful Creator.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 1, E'The elders which are among you I exhort, who am also an elder, and a witness of the sufferings of Christ, and also a partaker of the glory that shall be revealed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 2, E'Feed the flock of God which is among you, taking the oversight thereof, not by constraint, but willingly; not for filthy lucre, but of a ready mind;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 3, E'Neither as being lords over Godâ€™s heritage, but being ensamples to the flock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 4, E'And when the chief Shepherd shall appear, ye shall receive a crown of glory that fadeth not away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 5, E'Likewise, ye younger, submit yourselves unto the elder. Yea, all of you be subject one to another, and be clothed with humility: for God resisteth the proud, and giveth grace to the humble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 6, E'Humble yourselves therefore under the mighty hand of God, that he may exalt you in due time:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 7, E'Casting all your care upon him; for he careth for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 8, E'Be sober, be vigilant; because your adversary the devil, as a roaring lion, walketh about, seeking whom he may devour:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 9, E'Whom resist stedfast in the faith, knowing that the same afflictions are accomplished in your brethren that are in the world.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Peter') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 10, E'But the God of all grace, who hath called us unto his eternal glory by Christ Jesus, after that ye have suffered a while, make you perfect, stablish, strengthen, settle you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 11, E'To him be glory and dominion for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 12, E'By Silvanus, a faithful brother unto you, as I suppose, I have written briefly, exhorting, and testifying that this is the true grace of God wherein ye stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 13, E'The church that is at Babylon, elected together with you, saluteth you; and so doth Marcus my son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '514e1363-819d-4085-a61b-3b38509273cc', 5, 14, E'Greet ye one another with a kiss of charity. Peace be with you all that are in Christ Jesus. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Peter') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 1, E'Simon Peter, a servant and an apostle of Jesus Christ, to them that have obtained like precious faith with us through the righteousness of God and our Saviour Jesus Christ:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 2, E'Grace and peace be multiplied unto you through the knowledge of God, and of Jesus our Lord,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 3, E'According as his divine power hath given unto us all things that pertain unto life and godliness, through the knowledge of him that hath called us to glory and virtue:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 4, E'Whereby are given unto us exceeding great and precious promises: that by these ye might be partakers of the divine nature, having escaped the corruption that is in the world through lust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 5, E'And beside this, giving all diligence, add to your faith virtue; and to virtue knowledge;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 6, E'And to knowledge temperance; and to temperance patience; and to patience godliness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 7, E'And to godliness brotherly kindness; and to brotherly kindness charity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 8, E'For if these things be in you, and abound, they make you that ye shall neither be barren nor unfruitful in the knowledge of our Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 9, E'But he that lacketh these things is blind, and cannot see afar off, and hath forgotten that he was purged from his old sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 10, E'Wherefore the rather, brethren, give diligence to make your calling and election sure: for if ye do these things, ye shall never fall:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 11, E'For so an entrance shall be ministered unto you abundantly into the everlasting kingdom of our Lord and Saviour Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 12, E'Wherefore I will not be negligent to put you always in remembrance of these things, though ye know them, and be established in the present truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 13, E'Yea, I think it meet, as long as I am in this tabernacle, to stir you up by putting you in remembrance;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 14, E'Knowing that shortly I must put off this my tabernacle, even as our Lord Jesus Christ hath shewed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 15, E'Moreover I will endeavour that ye may be able after my decease to have these things always in remembrance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 16, E'For we have not followed cunningly devised fables, when we made known unto you the power and coming of our Lord Jesus Christ, but were eyewitnesses of his majesty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 17, E'For he received from God the Father honour and glory, when there came such a voice to him from the excellent glory, This is my beloved Son, in whom I am well pleased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 18, E'And this voice which came from heaven we heard, when we were with him in the holy mount.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 19, E'We have also a more sure word of prophecy; whereunto ye do well that ye take heed, as unto a light that shineth in a dark place, until the day dawn, and the day star arise in your hearts:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 20, E'Knowing this first, that no prophecy of the scripture is of any private interpretation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 1, 21, E'For the prophecy came not in old time by the will of man: but holy men of God spake as they were moved by the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 1, E'But there were false prophets also among the people, even as there shall be false teachers among you, who privily shall bring in damnable heresies, even denying the Lord that bought them, and bring upon themselves swift destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 2, E'And many shall follow their pernicious ways; by reason of whom the way of truth shall be evil spoken of.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 3, E'And through covetousness shall they with feigned words make merchandise of you: whose judgment now of a long time lingereth not, and their damnation slumbereth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 4, E'For if God spared not the angels that sinned, but cast them down to hell, and delivered them into chains of darkness, to be reserved unto judgment;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 5, E'And spared not the old world, but saved Noah the eighth person, a preacher of righteousness, bringing in the flood upon the world of the ungodly;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 6, E'And turning the cities of Sodom and Gomorrha into ashes condemned them with an overthrow, making them an ensample unto those that after should live ungodly;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 7, E'And delivered just Lot, vexed with the filthy conversation of the wicked:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 8, E'(For that righteous man dwelling among them, in seeing and hearing, vexed his righteous soul from day to day with their unlawful deeds;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 9, E'The Lord knoweth how to deliver the godly out of temptations, and to reserve the unjust unto the day of judgment to be punished:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 10, E'But chiefly them that walk after the flesh in the lust of uncleanness, and despise government. Presumptuous are they, selfwilled, they are not afraid to speak evil of dignities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 11, E'Whereas angels, which are greater in power and might, bring not railing accusation against them before the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 12, E'But these, as natural brute beasts, made to be taken and destroyed, speak evil of the things that they understand not; and shall utterly perish in their own corruption;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 13, E'And shall receive the reward of unrighteousness, as they that count it pleasure to riot in the day time. Spots they are and blemishes, sporting themselves with their own deceivings while they feast with you;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 14, E'Having eyes full of adultery, and that cannot cease from sin; beguiling unstable souls: an heart they have exercised with covetous practices; cursed children:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 15, E'Which have forsaken the right way, and are gone astray, following the way of Balaam the son of Bosor, who loved the wages of unrighteousness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 16, E'But was rebuked for his iniquity: the dumb ass speaking with manâ€™s voice forbad the madness of the prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 17, E'These are wells without water, clouds that are carried with a tempest; to whom the mist of darkness is reserved for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 18, E'For when they speak great swelling words of vanity, they allure through the lusts of the flesh, through much wantonness, those that were clean escaped from them who live in error.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 19, E'While they promise them liberty, they themselves are the servants of corruption: for of whom a man is overcome, of the same is he brought in bondage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 20, E'For if after they have escaped the pollutions of the world through the knowledge of the Lord and Saviour Jesus Christ, they are again entangled therein, and overcome, the latter end is worse with them than the beginning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 21, E'For it had been better for them not to have known the way of righteousness, than, after they have known it, to turn from the holy commandment delivered unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 2, 22, E'But it is happened unto them according to the true proverb, The dog is turned to his own vomit again; and the sow that was washed to her wallowing in the mire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 1, E'This second epistle, beloved, I now write unto you; in both which I stir up your pure minds by way of remembrance:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 2, E'That ye may be mindful of the words which were spoken before by the holy prophets, and of the commandment of us the apostles of the Lord and Saviour:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 3, E'Knowing this first, that there shall come in the last days scoffers, walking after their own lusts,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 4, E'And saying, Where is the promise of his coming? for since the fathers fell asleep, all things continue as they were from the beginning of the creation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 5, E'For this they willingly are ignorant of, that by the word of God the heavens were of old, and the earth standing out of the water and in the water:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 6, E'Whereby the world that then was, being overflowed with water, perished:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 7, E'But the heavens and the earth, which are now, by the same word are kept in store, reserved unto fire against the day of judgment and perdition of ungodly men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 8, E'But, beloved, be not ignorant of this one thing, that one day is with the Lord as a thousand years, and a thousand years as one day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 9, E'The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 10, E'But the day of the Lord will come as a thief in the night; in the which the heavens shall pass away with a great noise, and the elements shall melt with fervent heat, the earth also and the works that are therein shall be burned up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 11, E'Seeing then that all these things shall be dissolved, what manner of persons ought ye to be in all holy conversation and godliness,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 12, E'Looking for and hasting unto the coming of the day of God, wherein the heavens being on fire shall be dissolved, and the elements shall melt with fervent heat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 13, E'Nevertheless we, according to his promise, look for new heavens and a new earth, wherein dwelleth righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 14, E'Wherefore, beloved, seeing that ye look for such things, be diligent that ye may be found of him in peace, without spot, and blameless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 15, E'And account that the longsuffering of our Lord is salvation; even as our beloved brother Paul also according to the wisdom given unto him hath written unto you;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 16, E'As also in all his epistles, speaking in them of these things; in which are some things hard to be understood, which they that are unlearned and unstable wrest, as they do also the other scriptures, unto their own destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 17, E'Ye therefore, beloved, seeing ye know these things before, beware lest ye also, being led away with the error of the wicked, fall from your own stedfastness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '5ee10564-1959-4b31-aeb7-5b26e04b9cad', 3, 18, E'But grow in grace, and in the knowledge of our Lord and Saviour Jesus Christ. To him be glory both now and for ever. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Peter') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 1, E'That which was from the beginning, which we have heard, which we have seen with our eyes, which we have looked upon, and our hands have handled, of the Word of life;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 2, E'(For the life was manifested, and we have seen it, and bear witness, and shew unto you that eternal life, which was with the Father, and was manifested unto us;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 3, E'That which we have seen and heard declare we unto you, that ye also may have fellowship with us: and truly our fellowship is with the Father, and with his Son Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 4, E'And these things write we unto you, that your joy may be full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 5, E'This then is the message which we have heard of him, and declare unto you, that God is light, and in him is no darkness at all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 6, E'If we say that we have fellowship with him, and walk in darkness, we lie, and do not the truth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 7, E'But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 8, E'If we say that we have no sin, we deceive ourselves, and the truth is not in us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 9, E'If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 1, 10, E'If we say that we have not sinned, we make him a liar, and his word is not in us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 1, E'My little children, these things write I unto you, that ye sin not. And if any man sin, we have an advocate with the Father, Jesus Christ the righteous:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 2, E'And he is the propitiation for our sins: and not for ours only, but also for the sins of the whole world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 3, E'And hereby we do know that we know him, if we keep his commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 4, E'He that saith, I know him, and keepeth not his commandments, is a liar, and the truth is not in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 5, E'But whoso keepeth his word, in him verily is the love of God perfected: hereby know we that we are in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 6, E'He that saith he abideth in him ought himself also so to walk, even as he walked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 7, E'Brethren, I write no new commandment unto you, but an old commandment which ye had from the beginning. The old commandment is the word which ye have heard from the beginning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 8, E'Again, a new commandment I write unto you, which thing is true in him and in you: because the darkness is past, and the true light now shineth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 9, E'He that saith he is in the light, and hateth his brother, is in darkness even until now.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 10, E'He that loveth his brother abideth in the light, and there is none occasion of stumbling in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 11, E'But he that hateth his brother is in darkness, and walketh in darkness, and knoweth not whither he goeth, because that darkness hath blinded his eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 12, E'I write unto you, little children, because your sins are forgiven you for his nameâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 13, E'I write unto you, fathers, because ye have known him that is from the beginning. I write unto you, young men, because ye have overcome the wicked one. I write unto you, little children, because ye have known the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 14, E'I have written unto you, fathers, because ye have known him that is from the beginning. I have written unto you, young men, because ye are strong, and the word of God abideth in you, and ye have overcome the wicked one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 15, E'Love not the world, neither the things that are in the world. If any man love the world, the love of the Father is not in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 16, E'For all that is in the world, the lust of the flesh, and the lust of the eyes, and the pride of life, is not of the Father, but is of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 17, E'And the world passeth away, and the lust thereof: but he that doeth the will of God abideth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 18, E'Little children, it is the last time: and as ye have heard that antichrist shall come, even now are there many antichrists; whereby we know that it is the last time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 19, E'They went out from us, but they were not of us; for if they had been of us, they would no doubt have continued with us: but they went out, that they might be made manifest that they were not all of us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 20, E'But ye have an unction from the Holy One, and ye know all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 21, E'I have not written unto you because ye know not the truth, but because ye know it, and that no lie is of the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 22, E'Who is a liar but he that denieth that Jesus is the Christ? He is antichrist, that denieth the Father and the Son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 23, E'Whosoever denieth the Son, the same hath not the Father: he that acknowledgeth the Son hath the Father also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 24, E'Let that therefore abide in you, which ye have heard from the beginning. If that which ye have heard from the beginning shall remain in you, ye also shall continue in the Son, and in the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 25, E'And this is the promise that he hath promised us, even eternal life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 26, E'These things have I written unto you concerning them that seduce you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 27, E'But the anointing which ye have received of him abideth in you, and ye need not that any man teach you: but as the same anointing teacheth you of all things, and is truth, and is no lie, and even as it hath taught you, ye shall abide in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 28, E'And now, little children, abide in him; that, when he shall appear, we may have confidence, and not be ashamed before him at his coming.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 2, 29, E'If ye know that he is righteous, ye know that every one that doeth righteousness is born of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 1, E'Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 2, E'Beloved, now are we the sons of God, and it doth not yet appear what we shall be: but we know that, when he shall appear, we shall be like him; for we shall see him as he is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 3, E'And every man that hath this hope in him purifieth himself, even as he is pure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 4, E'Whosoever committeth sin transgresseth also the law: for sin is the transgression of the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 5, E'And ye know that he was manifested to take away our sins; and in him is no sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 6, E'Whosoever abideth in him sinneth not: whosoever sinneth hath not seen him, neither known him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 7, E'Little children, let no man deceive you: he that doeth righteousness is righteous, even as he is righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 8, E'He that committeth sin is of the devil; for the devil sinneth from the beginning. For this purpose the Son of God was manifested, that he might destroy the works of the devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 9, E'Whosoever is born of God doth not commit sin; for his seed remaineth in him: and he cannot sin, because he is born of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 10, E'In this the children of God are manifest, and the children of the devil: whosoever doeth not righteousness is not of God, neither he that loveth not his brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 11, E'For this is the message that ye heard from the beginning, that we should love one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 12, E'Not as Cain, who was of that wicked one, and slew his brother. And wherefore slew he him? Because his own works were evil, and his brotherâ€™s righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 13, E'Marvel not, my brethren, if the world hate you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 14, E'We know that we have passed from death unto life, because we love the brethren. He that loveth not his brother abideth in death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 15, E'Whosoever hateth his brother is a murderer: and ye know that no murderer hath eternal life abiding in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 16, E'Hereby perceive we the love of God, because he laid down his life for us: and we ought to lay down our lives for the brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 17, E'But whoso hath this worldâ€™s good, and seeth his brother have need, and shutteth up his bowels of compassion from him, how dwelleth the love of God in him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 18, E'My little children, let us not love in word, neither in tongue; but in deed and in truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 19, E'And hereby we know that we are of the truth, and shall assure our hearts before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 20, E'For if our heart condemn us, God is greater than our heart, and knoweth all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 21, E'Beloved, if our heart condemn us not, then have we confidence toward God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 22, E'And whatsoever we ask, we receive of him, because we keep his commandments, and do those things that are pleasing in his sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 23, E'And this is his commandment, That we should believe on the name of his Son Jesus Christ, and love one another, as he gave us commandment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 3, 24, E'And he that keepeth his commandments dwelleth in him, and he in him. And hereby we know that he abideth in us, by the Spirit which he hath given us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 1, E'Beloved, believe not every spirit, but try the spirits whether they are of God: because many false prophets are gone out into the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 2, E'Hereby know ye the Spirit of God: Every spirit that confesseth that Jesus Christ is come in the flesh is of God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 3, E'And every spirit that confesseth not that Jesus Christ is come in the flesh is not of God: and this is that spirit of antichrist, whereof ye have heard that it should come; and even now already is it in the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 4, E'Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 5, E'They are of the world: therefore speak they of the world, and the world heareth them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 6, E'We are of God: he that knoweth God heareth us; he that is not of God heareth not us. Hereby know we the spirit of truth, and the spirit of error.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 7, E'Beloved, let us love one another: for love is of God; and every one that loveth is born of God, and knoweth God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 8, E'He that loveth not knoweth not God; for God is love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 9, E'In this was manifested the love of God toward us, because that God sent his only begotten Son into the world, that we might live through him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 10, E'Herein is love, not that we loved God, but that he loved us, and sent his Son to be the propitiation for our sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 11, E'Beloved, if God so loved us, we ought also to love one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 12, E'No man hath seen God at any time. If we love one another, God dwelleth in us, and his love is perfected in us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 13, E'Hereby know we that we dwell in him, and he in us, because he hath given us of his Spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 14, E'And we have seen and do testify that the Father sent the Son to be the Saviour of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 15, E'Whosoever shall confess that Jesus is the Son of God, God dwelleth in him, and he in God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 16, E'And we have known and believed the love that God hath to us. God is love; and he that dwelleth in love dwelleth in God, and God in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 17, E'Herein is our love made perfect, that we may have boldness in the day of judgment: because as he is, so are we in this world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 18, E'There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 19, E'We love him, because he first loved us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 20, E'If a man say, I love God, and hateth his brother, he is a liar: for he that loveth not his brother whom he hath seen, how can he love God whom he hath not seen?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 4, 21, E'And this commandment have we from him, That he who loveth God love his brother also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 1, E'Whosoever believeth that Jesus is the Christ is born of God: and every one that loveth him that begat loveth him also that is begotten of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 2, E'By this we know that we love the children of God, when we love God, and keep his commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 3, E'For this is the love of God, that we keep his commandments: and his commandments are not grievous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 4, E'For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 5, E'Who is he that overcometh the world, but he that believeth that Jesus is the Son of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 6, E'This is he that came by water and blood, even Jesus Christ; not by water only, but by water and blood. And it is the Spirit that beareth witness, because the Spirit is truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 7, E'For there are three that bear record in heaven, the Father, the Word, and the Holy Ghost: and these three are one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 8, E'And there are three that bear witness in earth, the Spirit, and the water, and the blood: and these three agree in one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 9, E'If we receive the witness of men, the witness of God is greater: for this is the witness of God which he hath testified of his Son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 10, E'He that believeth on the Son of God hath the witness in himself: he that believeth not God hath made him a liar; because he believeth not the record that God gave of his Son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 11, E'And this is the record, that God hath given to us eternal life, and this life is in his Son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 12, E'He that hath the Son hath life; and he that hath not the Son of God hath not life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 13, E'These things have I written unto you that believe on the name of the Son of God; that ye may know that ye have eternal life, and that ye may believe on the name of the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 14, E'And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 15, E'And if we know that he hear us, whatsoever we ask, we know that we have the petitions that we desired of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 16, E'If any man see his brother sin a sin which is not unto death, he shall ask, and he shall give him life for them that sin not unto death. There is a sin unto death: I do not say that he shall pray for it.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 17, E'All unrighteousness is sin: and there is a sin not unto death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 18, E'We know that whosoever is born of God sinneth not; but he that is begotten of God keepeth himself, and that wicked one toucheth him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 19, E'And we know that we are of God, and the whole world lieth in wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 20, E'And we know that the Son of God is come, and hath given us an understanding, that we may know him that is true, and we are in him that is true, even in his Son Jesus Christ. This is the true God, and eternal life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c8355ae3-1a97-4ec8-95f4-66ac92f950d3', 5, 21, E'Little children, keep yourselves from idols. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 1, E'The elder unto the elect lady and her children, whom I love in the truth; and not I only, but also all they that have known the truth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 2, E'For the truthâ€™s sake, which dwelleth in us, and shall be with us for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 3, E'Grace be with you, mercy, and peace, from God the Father, and from the Lord Jesus Christ, the Son of the Father, in truth and love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 4, E'I rejoiced greatly that I found of thy children walking in truth, as we have received a commandment from the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 5, E'And now I beseech thee, lady, not as though I wrote a new commandment unto thee, but that which we had from the beginning, that we love one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 6, E'And this is love, that we walk after his commandments. This is the commandment, That, as ye have heard from the beginning, ye should walk in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 7, E'For many deceivers are entered into the world, who confess not that Jesus Christ is come in the flesh. This is a deceiver and an antichrist.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 8, E'Look to yourselves, that we lose not those things which we have wrought, but that we receive a full reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 9, E'Whosoever transgresseth, and abideth not in the doctrine of Christ, hath not God. He that abideth in the doctrine of Christ, he hath both the Father and the Son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 10, E'If there come any unto you, and bring not this doctrine, receive him not into your house, neither bid him God speed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 11, E'For he that biddeth him God speed is partaker of his evil deeds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 12, E'Having many things to write unto you, I would not write with paper and ink: but I trust to come unto you, and speak face to face, that our joy may be full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '9c196566-6050-4702-bc47-5067368b0470', 1, 13, E'The children of thy elect sister greet thee. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 1, E'The elder unto the wellbeloved Gaius, whom I love in the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 2, E'Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 3, E'For I rejoiced greatly, when the brethren came and testified of the truth that is in thee, even as thou walkest in the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 4, E'I have no greater joy than to hear that my children walk in truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 5, E'Beloved, thou doest faithfully whatsoever thou doest to the brethren, and to strangers;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 6, E'Which have borne witness of thy charity before the church: whom if thou bring forward on their journey after a godly sort, thou shalt do well:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 7, E'Because that for his nameâ€™s sake they went forth, taking nothing of the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 8, E'We therefore ought to receive such, that we might be fellowhelpers to the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 9, E'I wrote unto the church: but Diotrephes, who loveth to have the preeminence among them, receiveth us not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 10, E'Wherefore, if I come, I will remember his deeds which he doeth, prating against us with malicious words: and not content therewith, neither doth he himself receive the brethren, and forbiddeth them that would, and casteth them out of the church.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 11, E'Beloved, follow not that which is evil, but that which is good. He that doeth good is of God: but he that doeth evil hath not seen God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 12, E'Demetrius hath good report of all men, and of the truth itself: yea, and we also bear record; and ye know that our record is true.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 13, E'I had many things to write, but I will not with ink and pen write unto thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '84c2c5ca-4672-4adf-981a-ab36a8df9b78', 1, 14, E'But I trust I shall shortly see thee, and we shall speak face to face. Peace be to thee. Our friends salute thee. Greet the friends by name.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '3 John') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 1, E'Jude, the servant of Jesus Christ, and brother of James, to them that are sanctified by God the Father, and preserved in Jesus Christ, and called:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 2, E'Mercy unto you, and peace, and love, be multiplied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 3, E'Beloved, when I gave all diligence to write unto you of the common salvation, it was needful for me to write unto you, and exhort you that ye should earnestly contend for the faith which was once delivered unto the saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 4, E'For there are certain men crept in unawares, who were before of old ordained to this condemnation, ungodly men, turning the grace of our God into lasciviousness, and denying the only Lord God, and our Lord Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 5, E'I will therefore put you in remembrance, though ye once knew this, how that the Lord, having saved the people out of the land of Egypt, afterward destroyed them that believed not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 6, E'And the angels which kept not their first estate, but left their own habitation, he hath reserved in everlasting chains under darkness unto the judgment of the great day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 7, E'Even as Sodom and Gomorrha, and the cities about them in like manner, giving themselves over to fornication, and going after strange flesh, are set forth for an example, suffering the vengeance of eternal fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 8, E'Likewise also these filthy dreamers defile the flesh, despise dominion, and speak evil of dignities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 9, E'Yet Michael the archangel, when contending with the devil he disputed about the body of Moses, durst not bring against him a railing accusation, but said, The Lord rebuke thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 10, E'But these speak evil of those things which they know not: but what they know naturally, as brute beasts, in those things they corrupt themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 11, E'Woe unto them! for they have gone in the way of Cain, and ran greedily after the error of Balaam for reward, and perished in the gainsaying of Core.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 12, E'These are spots in your feasts of charity, when they feast with you, feeding themselves without fear: clouds they are without water, carried about of winds; trees whose fruit withereth, without fruit, twice dead, plucked up by the roots;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 13, E'Raging waves of the sea, foaming out their own shame; wandering stars, to whom is reserved the blackness of darkness for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 14, E'And Enoch also, the seventh from Adam, prophesied of these, saying, Behold, the Lord cometh with ten thousands of his saints,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 15, E'To execute judgment upon all, and to convince all that are ungodly among them of all their ungodly deeds which they have ungodly committed, and of all their hard speeches which ungodly sinners have spoken against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 16, E'These are murmurers, complainers, walking after their own lusts; and their mouth speaketh great swelling words, having menâ€™s persons in admiration because of advantage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 17, E'But, beloved, remember ye the words which were spoken before of the apostles of our Lord Jesus Christ;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 18, E'How that they told you there should be mockers in the last time, who should walk after their own ungodly lusts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 19, E'These be they who separate themselves, sensual, having not the Spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 20, E'But ye, beloved, building up yourselves on your most holy faith, praying in the Holy Ghost,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 21, E'Keep yourselves in the love of God, looking for the mercy of our Lord Jesus Christ unto eternal life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 22, E'And of some have compassion, making a difference:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 23, E'And others save with fear, pulling them out of the fire; hating even the garment spotted by the flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 24, E'Now unto him that is able to keep you from falling, and to present you faultless before the presence of his glory with exceeding joy,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'f3e2fdf7-37fa-4222-a057-47aa97e8c4f8', 1, 25, E'To the only wise God our Saviour, be glory and majesty, dominion and power, both now and ever. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jude') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 1, E'The Revelation of Jesus Christ, which God gave unto him, to shew unto his servants things which must shortly come to pass; and he sent and signified it by his angel unto his servant John:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 2, E'Who bare record of the word of God, and of the testimony of Jesus Christ, and of all things that he saw.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 3, E'Blessed is he that readeth, and they that hear the words of this prophecy, and keep those things which are written therein: for the time is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 4, E'John to the seven churches which are in Asia: Grace be unto you, and peace, from him which is, and which was, and which is to come; and from the seven Spirits which are before his throne;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 5, E'And from Jesus Christ, who is the faithful witness, and the first begotten of the dead, and the prince of the kings of the earth. Unto him that loved us, and washed us from our sins in his own blood,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 6, E'And hath made us kings and priests unto God and his Father; to him be glory and dominion for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 7, E'Behold, he cometh with clouds; and every eye shall see him, and they also which pierced him: and all kindreds of the earth shall wail because of him. Even so, Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 8, E'I am Alpha and Omega, the beginning and the ending, saith the Lord, which is, and which was, and which is to come, the Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 9, E'I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 10, E'I was in the Spirit on the Lordâ€™s day, and heard behind me a great voice, as of a trumpet,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 11, E'Saying, I am Alpha and Omega, the first and the last: and, What thou seest, write in a book, and send it unto the seven churches which are in Asia; unto Ephesus, and unto Smyrna, and unto Pergamos, and unto Thyatira, and unto Sardis, and unto Philadelphia, and unto Laodicea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 12, E'And I turned to see the voice that spake with me. And being turned, I saw seven golden candlesticks;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 13, E'And in the midst of the seven candlesticks one like unto the Son of man, clothed with a garment down to the foot, and girt about the paps with a golden girdle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 14, E'His head and his hairs were white like wool, as white as snow; and his eyes were as a flame of fire;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 15, E'And his feet like unto fine brass, as if they burned in a furnace; and his voice as the sound of many waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 16, E'And he had in his right hand seven stars: and out of his mouth went a sharp twoedged sword: and his countenance was as the sun shineth in his strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 17, E'And when I saw him, I fell at his feet as dead. And he laid his right hand upon me, saying unto me, Fear not; I am the first and the last:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 18, E'I am he that liveth, and was dead; and, behold, I am alive for evermore, Amen; and have the keys of hell and of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 19, E'Write the things which thou hast seen, and the things which are, and the things which shall be hereafter;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 1, 20, E'The mystery of the seven stars which thou sawest in my right hand, and the seven golden candlesticks. The seven stars are the angels of the seven churches: and the seven candlesticks which thou sawest are the seven churches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 1, E'Unto the angel of the church of Ephesus write; These things saith he that holdeth the seven stars in his right hand, who walketh in the midst of the seven golden candlesticks;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 2, E'I know thy works, and thy labour, and thy patience, and how thou canst not bear them which are evil: and thou hast tried them which say they are apostles, and are not, and hast found them liars:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 3, E'And hast borne, and hast patience, and for my nameâ€™s sake hast laboured, and hast not fainted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 4, E'Nevertheless I have somewhat against thee, because thou hast left thy first love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 5, E'Remember therefore from whence thou art fallen, and repent, and do the first works; or else I will come unto thee quickly, and will remove thy candlestick out of his place, except thou repent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 6, E'But this thou hast, that thou hatest the deeds of the Nicolaitanes, which I also hate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 7, E'He that hath an ear, let him hear what the Spirit saith unto the churches; To him that overcometh will I give to eat of the tree of life, which is in the midst of the paradise of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 8, E'And unto the angel of the church in Smyrna write; These things saith the first and the last, which was dead, and is alive;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 9, E'I know thy works, and tribulation, and poverty, (but thou art rich) and I know the blasphemy of them which say they are Jews, and are not, but are the synagogue of Satan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 10, E'Fear none of those things which thou shalt suffer: behold, the devil shall cast some of you into prison, that ye may be tried; and ye shall have tribulation ten days: be thou faithful unto death, and I will give thee a crown of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 11, E'He that hath an ear, let him hear what the Spirit saith unto the churches; He that overcometh shall not be hurt of the second death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 12, E'And to the angel of the church in Pergamos write; These things saith he which hath the sharp sword with two edges;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 13, E'I know thy works, and where thou dwellest, even where Satanâ€™s seat is: and thou holdest fast my name, and hast not denied my faith, even in those days wherein Antipas was my faithful martyr, who was slain among you, where Satan dwelleth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 14, E'But I have a few things against thee, because thou hast there them that hold the doctrine of Balaam, who taught Balac to cast a stumblingblock before the children of Israel, to eat things sacrificed unto idols, and to commit fornication.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 15, E'So hast thou also them that hold the doctrine of the Nicolaitanes, which thing I hate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 16, E'Repent; or else I will come unto thee quickly, and will fight against them with the sword of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 17, E'He that hath an ear, let him hear what the Spirit saith unto the churches; To him that overcometh will I give to eat of the hidden manna, and will give him a white stone, and in the stone a new name written, which no man knoweth saving he that receiveth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 18, E'And unto the angel of the church in Thyatira write; These things saith the Son of God, who hath his eyes like unto a flame of fire, and his feet are like fine brass;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 19, E'I know thy works, and charity, and service, and faith, and thy patience, and thy works; and the last to be more than the first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 20, E'Notwithstanding I have a few things against thee, because thou sufferest that woman Jezebel, which calleth herself a prophetess, to teach and to seduce my servants to commit fornication, and to eat things sacrificed unto idols.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 21, E'And I gave her space to repent of her fornication; and she repented not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 22, E'Behold, I will cast her into a bed, and them that commit adultery with her into great tribulation, except they repent of their deeds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 23, E'And I will kill her children with death; and all the churches shall know that I am he which searcheth the reins and hearts: and I will give unto every one of you according to your works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 24, E'But unto you I say, and unto the rest in Thyatira, as many as have not this doctrine, and which have not known the depths of Satan, as they speak; I will put upon you none other burden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 25, E'But that which ye have already hold fast till I come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 26, E'And he that overcometh, and keepeth my works unto the end, to him will I give power over the nations:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 27, E'And he shall rule them with a rod of iron; as the vessels of a potter shall they be broken to shivers: even as I received of my Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 28, E'And I will give him the morning star.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 2, 29, E'He that hath an ear, let him hear what the Spirit saith unto the churches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 1, E'And unto the angel of the church in Sardis write; These things saith he that hath the seven Spirits of God, and the seven stars; I know thy works, that thou hast a name that thou livest, and art dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 2, E'Be watchful, and strengthen the things which remain, that are ready to die: for I have not found thy works perfect before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 3, E'Remember therefore how thou hast received and heard, and hold fast, and repent. If therefore thou shalt not watch, I will come on thee as a thief, and thou shalt not know what hour I will come upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 4, E'Thou hast a few names even in Sardis which have not defiled their garments; and they shall walk with me in white: for they are worthy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 5, E'He that overcometh, the same shall be clothed in white raiment; and I will not blot out his name out of the book of life, but I will confess his name before my Father, and before his angels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 6, E'He that hath an ear, let him hear what the Spirit saith unto the churches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 7, E'And to the angel of the church in Philadelphia write; These things saith he that is holy, he that is true, he that hath the key of David, he that openeth, and no man shutteth; and shutteth, and no man openeth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 8, E'I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 9, E'Behold, I will make them of the synagogue of Satan, which say they are Jews, and are not, but do lie; behold, I will make them to come and worship before thy feet, and to know that I have loved thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 10, E'Because thou hast kept the word of my patience, I also will keep thee from the hour of temptation, which shall come upon all the world, to try them that dwell upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 11, E'Behold, I come quickly: hold that fast which thou hast, that no man take thy crown.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 12, E'Him that overcometh will I make a pillar in the temple of my God, and he shall go no more out: and I will write upon him the name of my God, and the name of the city of my God, which is new Jerusalem, which cometh down out of heaven from my God: and I will write upon him my new name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 13, E'He that hath an ear, let him hear what the Spirit saith unto the churches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 14, E'And unto the angel of the church of the Laodiceans write; These things saith the Amen, the faithful and true witness, the beginning of the creation of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 15, E'I know thy works, that thou art neither cold nor hot: I would thou wert cold or hot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 16, E'So then because thou art lukewarm, and neither cold nor hot, I will spue thee out of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 17, E'Because thou sayest, I am rich, and increased with goods, and have need of nothing; and knowest not that thou art wretched, and miserable, and poor, and blind, and naked:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 18, E'I counsel thee to buy of me gold tried in the fire, that thou mayest be rich; and white raiment, that thou mayest be clothed, and that the shame of thy nakedness do not appear; and anoint thine eyes with eyesalve, that thou mayest see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 19, E'As many as I love, I rebuke and chasten: be zealous therefore, and repent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 20, E'Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 21, E'To him that overcometh will I grant to sit with me in my throne, even as I also overcame, and am set down with my Father in his throne.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 3, 22, E'He that hath an ear, let him hear what the Spirit saith unto the churches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 1, E'After this I looked, and, behold, a door was opened in heaven: and the first voice which I heard was as it were of a trumpet talking with me; which said, Come up hither, and I will shew thee things which must be hereafter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 2, E'And immediately I was in the spirit: and, behold, a throne was set in heaven, and one sat on the throne.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 3, E'And he that sat was to look upon like a jasper and a sardine stone: and there was a rainbow round about the throne, in sight like unto an emerald.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 4, E'And round about the throne were four and twenty seats: and upon the seats I saw four and twenty elders sitting, clothed in white raiment; and they had on their heads crowns of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 5, E'And out of the throne proceeded lightnings and thunderings and voices: and there were seven lamps of fire burning before the throne, which are the seven Spirits of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 6, E'And before the throne there was a sea of glass like unto crystal: and in the midst of the throne, and round about the throne, were four beasts full of eyes before and behind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 7, E'And the first beast was like a lion, and the second beast like a calf, and the third beast had a face as a man, and the fourth beast was like a flying eagle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 8, E'And the four beasts had each of them six wings about him; and they were full of eyes within: and they rest not day and night, saying, Holy, holy, holy, LORD God Almighty, which was, and is, and is to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 9, E'And when those beasts give glory and honour and thanks to him that sat on the throne, who liveth for ever and ever,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 10, E'The four and twenty elders fall down before him that sat on the throne, and worship him that liveth for ever and ever, and cast their crowns before the throne, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 4, 11, E'Thou art worthy, O Lord, to receive glory and honour and power: for thou hast created all things, and for thy pleasure they are and were created.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 1, E'And I saw in the right hand of him that sat on the throne a book written within and on the backside, sealed with seven seals.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 2, E'And I saw a strong angel proclaiming with a loud voice, Who is worthy to open the book, and to loose the seals thereof?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 3, E'And no man in heaven, nor in earth, neither under the earth, was able to open the book, neither to look thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 4, E'And I wept much, because no man was found worthy to open and to read the book, neither to look thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 5, E'And one of the elders saith unto me, Weep not: behold, the Lion of the tribe of Juda, the Root of David, hath prevailed to open the book, and to loose the seven seals thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 6, E'And I beheld, and, lo, in the midst of the throne and of the four beasts, and in the midst of the elders, stood a Lamb as it had been slain, having seven horns and seven eyes, which are the seven Spirits of God sent forth into all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 7, E'And he came and took the book out of the right hand of him that sat upon the throne.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 8, E'And when he had taken the book, the four beasts and four and twenty elders fell down before the Lamb, having every one of them harps, and golden vials full of odours, which are the prayers of saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 9, E'And they sung a new song, saying, Thou art worthy to take the book, and to open the seals thereof: for thou wast slain, and hast redeemed us to God by thy blood out of every kindred, and tongue, and people, and nation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 10, E'And hast made us unto our God kings and priests: and we shall reign on the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 11, E'And I beheld, and I heard the voice of many angels round about the throne and the beasts and the elders: and the number of them was ten thousand times ten thousand, and thousands of thousands;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 12, E'Saying with a loud voice, Worthy is the Lamb that was slain to receive power, and riches, and wisdom, and strength, and honour, and glory, and blessing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 13, E'And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 5, 14, E'And the four beasts said, Amen. And the four and twenty elders fell down and worshipped him that liveth for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 1, E'And I saw when the Lamb opened one of the seals, and I heard, as it were the noise of thunder, one of the four beasts saying, Come and see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 2, E'And I saw, and behold a white horse: and he that sat on him had a bow; and a crown was given unto him: and he went forth conquering, and to conquer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 3, E'And when he had opened the second seal, I heard the second beast say, Come and see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 4, E'And there went out another horse that was red: and power was given to him that sat thereon to take peace from the earth, and that they should kill one another: and there was given unto him a great sword.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Revelation') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 5, E'And when he had opened the third seal, I heard the third beast say, Come and see. And I beheld, and lo a black horse; and he that sat on him had a pair of balances in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 6, E'And I heard a voice in the midst of the four beasts say, A measure of wheat for a penny, and three measures of barley for a penny; and see thou hurt not the oil and the wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 7, E'And when he had opened the fourth seal, I heard the voice of the fourth beast say, Come and see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 8, E'And I looked, and behold a pale horse: and his name that sat on him was Death, and Hell followed with him. And power was given unto them over the fourth part of the earth, to kill with sword, and with hunger, and with death, and with the beasts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 9, E'And when he had opened the fifth seal, I saw under the altar the souls of them that were slain for the word of God, and for the testimony which they held:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 10, E'And they cried with a loud voice, saying, How long, O Lord, holy and true, dost thou not judge and avenge our blood on them that dwell on the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 11, E'And white robes were given unto every one of them; and it was said unto them, that they should rest yet for a little season, until their fellowservants also and their brethren, that should be killed as they were, should be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 12, E'And I beheld when he had opened the sixth seal, and, lo, there was a great earthquake; and the sun became black as sackcloth of hair, and the moon became as blood;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 13, E'And the stars of heaven fell unto the earth, even as a fig tree casteth her untimely figs, when she is shaken of a mighty wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 14, E'And the heaven departed as a scroll when it is rolled together; and every mountain and island were moved out of their places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 15, E'And the kings of the earth, and the great men, and the rich men, and the chief captains, and the mighty men, and every bondman, and every free man, hid themselves in the dens and in the rocks of the mountains;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 16, E'And said to the mountains and rocks, Fall on us, and hide us from the face of him that sitteth on the throne, and from the wrath of the Lamb:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 6, 17, E'For the great day of his wrath is come; and who shall be able to stand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 1, E'And after these things I saw four angels standing on the four corners of the earth, holding the four winds of the earth, that the wind should not blow on the earth, nor on the sea, nor on any tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 2, E'And I saw another angel ascending from the east, having the seal of the living God: and he cried with a loud voice to the four angels, to whom it was given to hurt the earth and the sea,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 3, E'Saying, Hurt not the earth, neither the sea, nor the trees, till we have sealed the servants of our God in their foreheads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 4, E'And I heard the number of them which were sealed: and there were sealed an hundred and forty and four thousand of all the tribes of the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 5, E'Of the tribe of Juda were sealed twelve thousand. Of the tribe of Reuben were sealed twelve thousand. Of the tribe of Gad were sealed twelve thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 6, E'Of the tribe of Aser were sealed twelve thousand. Of the tribe of Nephthalim were sealed twelve thousand. Of the tribe of Manasses were sealed twelve thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 7, E'Of the tribe of Simeon were sealed twelve thousand. Of the tribe of Levi were sealed twelve thousand. Of the tribe of Issachar were sealed twelve thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 8, E'Of the tribe of Zabulon were sealed twelve thousand. Of the tribe of Joseph were sealed twelve thousand. Of the tribe of Benjamin were sealed twelve thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 9, E'After this I beheld, and, lo, a great multitude, which no man could number, of all nations, and kindreds, and people, and tongues, stood before the throne, and before the Lamb, clothed with white robes, and palms in their hands;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 10, E'And cried with a loud voice, saying, Salvation to our God which sitteth upon the throne, and unto the Lamb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 11, E'And all the angels stood round about the throne, and about the elders and the four beasts, and fell before the throne on their faces, and worshipped God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 12, E'Saying, Amen: Blessing, and glory, and wisdom, and thanksgiving, and honour, and power, and might, be unto our God for ever and ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 13, E'And one of the elders answered, saying unto me, What are these which are arrayed in white robes? and whence came they?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 14, E'And I said unto him, Sir, thou knowest. And he said to me, These are they which came out of great tribulation, and have washed their robes, and made them white in the blood of the Lamb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 15, E'Therefore are they before the throne of God, and serve him day and night in his temple: and he that sitteth on the throne shall dwell among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 16, E'They shall hunger no more, neither thirst any more; neither shall the sun light on them, nor any heat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 7, 17, E'For the Lamb which is in the midst of the throne shall feed them, and shall lead them unto living fountains of waters: and God shall wipe away all tears from their eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 1, E'And when he had opened the seventh seal, there was silence in heaven about the space of half an hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 2, E'And I saw the seven angels which stood before God; and to them were given seven trumpets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 3, E'And another angel came and stood at the altar, having a golden censer; and there was given unto him much incense, that he should offer it with the prayers of all saints upon the golden altar which was before the throne.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 4, E'And the smoke of the incense, which came with the prayers of the saints, ascended up before God out of the angelâ€™s hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 5, E'And the angel took the censer, and filled it with fire of the altar, and cast it into the earth: and there were voices, and thunderings, and lightnings, and an earthquake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 6, E'And the seven angels which had the seven trumpets prepared themselves to sound.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 7, E'The first angel sounded, and there followed hail and fire mingled with blood, and they were cast upon the earth: and the third part of trees was burnt up, and all green grass was burnt up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 8, E'And the second angel sounded, and as it were a great mountain burning with fire was cast into the sea: and the third part of the sea became blood;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 9, E'And the third part of the creatures which were in the sea, and had life, died; and the third part of the ships were destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 10, E'And the third angel sounded, and there fell a great star from heaven, burning as it were a lamp, and it fell upon the third part of the rivers, and upon the fountains of waters;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 11, E'And the name of the star is called Wormwood: and the third part of the waters became wormwood; and many men died of the waters, because they were made bitter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 12, E'And the fourth angel sounded, and the third part of the sun was smitten, and the third part of the moon, and the third part of the stars; so as the third part of them was darkened, and the day shone not for a third part of it, and the night likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 8, 13, E'And I beheld, and heard an angel flying through the midst of heaven, saying with a loud voice, Woe, woe, woe, to the inhabiters of the earth by reason of the other voices of the trumpet of the three angels, which are yet to sound!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 1, E'And the fifth angel sounded, and I saw a star fall from heaven unto the earth: and to him was given the key of the bottomless pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 2, E'And he opened the bottomless pit; and there arose a smoke out of the pit, as the smoke of a great furnace; and the sun and the air were darkened by reason of the smoke of the pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 3, E'And there came out of the smoke locusts upon the earth: and unto them was given power, as the scorpions of the earth have power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 4, E'And it was commanded them that they should not hurt the grass of the earth, neither any green thing, neither any tree; but only those men which have not the seal of God in their foreheads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 5, E'And to them it was given that they should not kill them, but that they should be tormented five months: and their torment was as the torment of a scorpion, when he striketh a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 6, E'And in those days shall men seek death, and shall not find it; and shall desire to die, and death shall flee from them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 7, E'And the shapes of the locusts were like unto horses prepared unto battle; and on their heads were as it were crowns like gold, and their faces were as the faces of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 8, E'And they had hair as the hair of women, and their teeth were as the teeth of lions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 9, E'And they had breastplates, as it were breastplates of iron; and the sound of their wings was as the sound of chariots of many horses running to battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 10, E'And they had tails like unto scorpions, and there were stings in their tails: and their power was to hurt men five months.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 11, E'And they had a king over them, which is the angel of the bottomless pit, whose name in the Hebrew tongue is Abaddon, but in the Greek tongue hath his name Apollyon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 12, E'One woe is past; and, behold, there come two woes more hereafter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 13, E'And the sixth angel sounded, and I heard a voice from the four horns of the golden altar which is before God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 14, E'Saying to the sixth angel which had the trumpet, Loose the four angels which are bound in the great river Euphrates.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 15, E'And the four angels were loosed, which were prepared for an hour, and a day, and a month, and a year, for to slay the third part of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 16, E'And the number of the army of the horsemen were two hundred thousand thousand: and I heard the number of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 17, E'And thus I saw the horses in the vision, and them that sat on them, having breastplates of fire, and of jacinth, and brimstone: and the heads of the horses were as the heads of lions; and out of their mouths issued fire and smoke and brimstone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 18, E'By these three was the third part of men killed, by the fire, and by the smoke, and by the brimstone, which issued out of their mouths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 19, E'For their power is in their mouth, and in their tails: for their tails were like unto serpents, and had heads, and with them they do hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 20, E'And the rest of the men which were not killed by these plagues yet repented not of the works of their hands, that they should not worship devils, and idols of gold, and silver, and brass, and stone, and of wood: which neither can see, nor hear, nor walk:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 9, 21, E'Neither repented they of their murders, nor of their sorceries, nor of their fornication, nor of their thefts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 1, E'And I saw another mighty angel come down from heaven, clothed with a cloud: and a rainbow was upon his head, and his face was as it were the sun, and his feet as pillars of fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 2, E'And he had in his hand a little book open: and he set his right foot upon the sea, and his left foot on the earth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 3, E'And cried with a loud voice, as when a lion roareth: and when he had cried, seven thunders uttered their voices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 4, E'And when the seven thunders had uttered their voices, I was about to write: and I heard a voice from heaven saying unto me, Seal up those things which the seven thunders uttered, and write them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 5, E'And the angel which I saw stand upon the sea and upon the earth lifted up his hand to heaven,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 6, E'And sware by him that liveth for ever and ever, who created heaven, and the things that therein are, and the earth, and the things that therein are, and the sea, and the things which are therein, that there should be time no longer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 7, E'But in the days of the voice of the seventh angel, when he shall begin to sound, the mystery of God should be finished, as he hath declared to his servants the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 8, E'And the voice which I heard from heaven spake unto me again, and said, Go and take the little book which is open in the hand of the angel which standeth upon the sea and upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 9, E'And I went unto the angel, and said unto him, Give me the little book. And he said unto me, Take it, and eat it up; and it shall make thy belly bitter, but it shall be in thy mouth sweet as honey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 10, E'And I took the little book out of the angelâ€™s hand, and ate it up; and it was in my mouth sweet as honey: and as soon as I had eaten it, my belly was bitter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 10, 11, E'And he said unto me, Thou must prophesy again before many peoples, and nations, and tongues, and kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 1, E'And there was given me a reed like unto a rod: and the angel stood, saying, Rise, and measure the temple of God, and the altar, and them that worship therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 2, E'But the court which is without the temple leave out, and measure it not; for it is given unto the Gentiles: and the holy city shall they tread under foot forty and two months.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 3, E'And I will give power unto my two witnesses, and they shall prophesy a thousand two hundred and threescore days, clothed in sackcloth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 4, E'These are the two olive trees, and the two candlesticks standing before the God of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 5, E'And if any man will hurt them, fire proceedeth out of their mouth, and devoureth their enemies: and if any man will hurt them, he must in this manner be killed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 6, E'These have power to shut heaven, that it rain not in the days of their prophecy: and have power over waters to turn them to blood, and to smite the earth with all plagues, as often as they will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 7, E'And when they shall have finished their testimony, the beast that ascendeth out of the bottomless pit shall make war against them, and shall overcome them, and kill them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 8, E'And their dead bodies shall lie in the street of the great city, which spiritually is called Sodom and Egypt, where also our Lord was crucified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 9, E'And they of the people and kindreds and tongues and nations shall see their dead bodies three days and an half, and shall not suffer their dead bodies to be put in graves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 10, E'And they that dwell upon the earth shall rejoice over them, and make merry, and shall send gifts one to another; because these two prophets tormented them that dwelt on the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 11, E'And after three days and an half the Spirit of life from God entered into them, and they stood upon their feet; and great fear fell upon them which saw them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 12, E'And they heard a great voice from heaven saying unto them, Come up hither. And they ascended up to heaven in a cloud; and their enemies beheld them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 13, E'And the same hour was there a great earthquake, and the tenth part of the city fell, and in the earthquake were slain of men seven thousand: and the remnant were affrighted, and gave glory to the God of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 14, E'The second woe is past; and, behold, the third woe cometh quickly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 15, E'And the seventh angel sounded; and there were great voices in heaven, saying, The kingdoms of this world are become the kingdoms of our Lord, and of his Christ; and he shall reign for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 16, E'And the four and twenty elders, which sat before God on their seats, fell upon their faces, and worshipped God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 17, E'Saying, We give thee thanks, O LORD God Almighty, which art, and wast, and art to come; because thou hast taken to thee thy great power, and hast reigned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 18, E'And the nations were angry, and thy wrath is come, and the time of the dead, that they should be judged, and that thou shouldest give reward unto thy servants the prophets, and to the saints, and them that fear thy name, small and great; and shouldest destroy them which destroy the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 11, 19, E'And the temple of God was opened in heaven, and there was seen in his temple the ark of his testament: and there were lightnings, and voices, and thunderings, and an earthquake, and great hail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 1, E'And there appeared a great wonder in heaven; a woman clothed with the sun, and the moon under her feet, and upon her head a crown of twelve stars:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 2, E'And she being with child cried, travailing in birth, and pained to be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 3, E'And there appeared another wonder in heaven; and behold a great red dragon, having seven heads and ten horns, and seven crowns upon his heads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 4, E'And his tail drew the third part of the stars of heaven, and did cast them to the earth: and the dragon stood before the woman which was ready to be delivered, for to devour her child as soon as it was born.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 5, E'And she brought forth a man child, who was to rule all nations with a rod of iron: and her child was caught up unto God, and to his throne.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 6, E'And the woman fled into the wilderness, where she hath a place prepared of God, that they should feed her there a thousand two hundred and threescore days.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Revelation') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 7, E'And there was war in heaven: Michael and his angels fought against the dragon; and the dragon fought and his angels,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 8, E'And prevailed not; neither was their place found any more in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 9, E'And the great dragon was cast out, that old serpent, called the Devil, and Satan, which deceiveth the whole world: he was cast out into the earth, and his angels were cast out with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 10, E'And I heard a loud voice saying in heaven, Now is come salvation, and strength, and the kingdom of our God, and the power of his Christ: for the accuser of our brethren is cast down, which accused them before our God day and night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 11, E'And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 12, E'Therefore rejoice, ye heavens, and ye that dwell in them. Woe to the inhabiters of the earth and of the sea! for the devil is come down unto you, having great wrath, because he knoweth that he hath but a short time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 13, E'And when the dragon saw that he was cast unto the earth, he persecuted the woman which brought forth the man child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 14, E'And to the woman were given two wings of a great eagle, that she might fly into the wilderness, into her place, where she is nourished for a time, and times, and half a time, from the face of the serpent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 15, E'And the serpent cast out of his mouth water as a flood after the woman, that he might cause her to be carried away of the flood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 16, E'And the earth helped the woman, and the earth opened her mouth, and swallowed up the flood which the dragon cast out of his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 12, 17, E'And the dragon was wroth with the woman, and went to make war with the remnant of her seed, which keep the commandments of God, and have the testimony of Jesus Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 1, E'And I stood upon the sand of the sea, and saw a beast rise up out of the sea, having seven heads and ten horns, and upon his horns ten crowns, and upon his heads the name of blasphemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 2, E'And the beast which I saw was like unto a leopard, and his feet were as the feet of a bear, and his mouth as the mouth of a lion: and the dragon gave him his power, and his seat, and great authority.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 3, E'And I saw one of his heads as it were wounded to death; and his deadly wound was healed: and all the world wondered after the beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 4, E'And they worshipped the dragon which gave power unto the beast: and they worshipped the beast, saying, Who is like unto the beast? who is able to make war with him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 5, E'And there was given unto him a mouth speaking great things and blasphemies; and power was given unto him to continue forty and two months.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 6, E'And he opened his mouth in blasphemy against God, to blaspheme his name, and his tabernacle, and them that dwell in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 7, E'And it was given unto him to make war with the saints, and to overcome them: and power was given him over all kindreds, and tongues, and nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 8, E'And all that dwell upon the earth shall worship him, whose names are not written in the book of life of the Lamb slain from the foundation of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 9, E'If any man have an ear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 10, E'He that leadeth into captivity shall go into captivity: he that killeth with the sword must be killed with the sword. Here is the patience and the faith of the saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 11, E'And I beheld another beast coming up out of the earth; and he had two horns like a lamb, and he spake as a dragon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 12, E'And he exerciseth all the power of the first beast before him, and causeth the earth and them which dwell therein to worship the first beast, whose deadly wound was healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 13, E'And he doeth great wonders, so that he maketh fire come down from heaven on the earth in the sight of men,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 14, E'And deceiveth them that dwell on the earth by the means of those miracles which he had power to do in the sight of the beast; saying to them that dwell on the earth, that they should make an image to the beast, which had the wound by a sword, and did live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 15, E'And he had power to give life unto the image of the beast, that the image of the beast should both speak, and cause that as many as would not worship the image of the beast should be killed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 16, E'And he causeth all, both small and great, rich and poor, free and bond, to receive a mark in their right hand, or in their foreheads:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 17, E'And that no man might buy or sell, save he that had the mark, or the name of the beast, or the number of his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 13, 18, E'Here is wisdom. Let him that hath understanding count the number of the beast: for it is the number of a man; and his number is Six hundred threescore and six.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 1, E'And I looked, and, lo, a Lamb stood on the mount Sion, and with him an hundred forty and four thousand, having his Fatherâ€™s name written in their foreheads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 2, E'And I heard a voice from heaven, as the voice of many waters, and as the voice of a great thunder: and I heard the voice of harpers harping with their harps:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 3, E'And they sung as it were a new song before the throne, and before the four beasts, and the elders: and no man could learn that song but the hundred and forty and four thousand, which were redeemed from the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 4, E'These are they which were not defiled with women; for they are virgins. These are they which follow the Lamb whithersoever he goeth. These were redeemed from among men, being the firstfruits unto God and to the Lamb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 5, E'And in their mouth was found no guile: for they are without fault before the throne of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 6, E'And I saw another angel fly in the midst of heaven, having the everlasting gospel to preach unto them that dwell on the earth, and to every nation, and kindred, and tongue, and people,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 7, E'Saying with a loud voice, Fear God, and give glory to him; for the hour of his judgment is come: and worship him that made heaven, and earth, and the sea, and the fountains of waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 8, E'And there followed another angel, saying, Babylon is fallen, is fallen, that great city, because she made all nations drink of the wine of the wrath of her fornication.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 9, E'And the third angel followed them, saying with a loud voice, If any man worship the beast and his image, and receive his mark in his forehead, or in his hand,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 10, E'The same shall drink of the wine of the wrath of God, which is poured out without mixture into the cup of his indignation; and he shall be tormented with fire and brimstone in the presence of the holy angels, and in the presence of the Lamb:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 11, E'And the smoke of their torment ascendeth up for ever and ever: and they have no rest day nor night, who worship the beast and his image, and whosoever receiveth the mark of his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 12, E'Here is the patience of the saints: here are they that keep the commandments of God, and the faith of Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 13, E'And I heard a voice from heaven saying unto me, Write, Blessed are the dead which die in the Lord from henceforth: Yea, saith the Spirit, that they may rest from their labours; and their works do follow them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 14, E'And I looked, and behold a white cloud, and upon the cloud one sat like unto the Son of man, having on his head a golden crown, and in his hand a sharp sickle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 15, E'And another angel came out of the temple, crying with a loud voice to him that sat on the cloud, Thrust in thy sickle, and reap: for the time is come for thee to reap; for the harvest of the earth is ripe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 16, E'And he that sat on the cloud thrust in his sickle on the earth; and the earth was reaped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 17, E'And another angel came out of the temple which is in heaven, he also having a sharp sickle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 18, E'And another angel came out from the altar, which had power over fire; and cried with a loud cry to him that had the sharp sickle, saying, Thrust in thy sharp sickle, and gather the clusters of the vine of the earth; for her grapes are fully ripe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 19, E'And the angel thrust in his sickle into the earth, and gathered the vine of the earth, and cast it into the great winepress of the wrath of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 14, 20, E'And the winepress was trodden without the city, and blood came out of the winepress, even unto the horse bridles, by the space of a thousand and six hundred furlongs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 15, 1, E'And I saw another sign in heaven, great and marvellous, seven angels having the seven last plagues; for in them is filled up the wrath of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 15, 2, E'And I saw as it were a sea of glass mingled with fire: and them that had gotten the victory over the beast, and over his image, and over his mark, and over the number of his name, stand on the sea of glass, having the harps of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 15, 3, E'And they sing the song of Moses the servant of God, and the song of the Lamb, saying, Great and marvellous are thy works, Lord God Almighty; just and true are thy ways, thou King of saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 15, 4, E'Who shall not fear thee, O Lord, and glorify thy name? for thou only art holy: for all nations shall come and worship before thee; for thy judgments are made manifest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 15, 5, E'And after that I looked, and, behold, the temple of the tabernacle of the testimony in heaven was opened:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 15, 6, E'And the seven angels came out of the temple, having the seven plagues, clothed in pure and white linen, and having their breasts girded with golden girdles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 15, 7, E'And one of the four beasts gave unto the seven angels seven golden vials full of the wrath of God, who liveth for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 15, 8, E'And the temple was filled with smoke from the glory of God, and from his power; and no man was able to enter into the temple, till the seven plagues of the seven angels were fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 1, E'And I heard a great voice out of the temple saying to the seven angels, Go your ways, and pour out the vials of the wrath of God upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 2, E'And the first went, and poured out his vial upon the earth; and there fell a noisome and grievous sore upon the men which had the mark of the beast, and upon them which worshipped his image.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 3, E'And the second angel poured out his vial upon the sea; and it became as the blood of a dead man: and every living soul died in the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 4, E'And the third angel poured out his vial upon the rivers and fountains of waters; and they became blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 5, E'And I heard the angel of the waters say, Thou art righteous, O Lord, which art, and wast, and shalt be, because thou hast judged thus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 6, E'For they have shed the blood of saints and prophets, and thou hast given them blood to drink; for they are worthy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 7, E'And I heard another out of the altar say, Even so, Lord God Almighty, true and righteous are thy judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 8, E'And the fourth angel poured out his vial upon the sun; and power was given unto him to scorch men with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 9, E'And men were scorched with great heat, and blasphemed the name of God, which hath power over these plagues: and they repented not to give him glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 10, E'And the fifth angel poured out his vial upon the seat of the beast; and his kingdom was full of darkness; and they gnawed their tongues for pain,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 11, E'And blasphemed the God of heaven because of their pains and their sores, and repented not of their deeds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 12, E'And the sixth angel poured out his vial upon the great river Euphrates; and the water thereof was dried up, that the way of the kings of the east might be prepared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 13, E'And I saw three unclean spirits like frogs come out of the mouth of the dragon, and out of the mouth of the beast, and out of the mouth of the false prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 14, E'For they are the spirits of devils, working miracles, which go forth unto the kings of the earth and of the whole world, to gather them to the battle of that great day of God Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 15, E'Behold, I come as a thief. Blessed is he that watcheth, and keepeth his garments, lest he walk naked, and they see his shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 16, E'And he gathered them together into a place called in the Hebrew tongue Armageddon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 17, E'And the seventh angel poured out his vial into the air; and there came a great voice out of the temple of heaven, from the throne, saying, It is done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 18, E'And there were voices, and thunders, and lightnings; and there was a great earthquake, such as was not since men were upon the earth, so mighty an earthquake, and so great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 19, E'And the great city was divided into three parts, and the cities of the nations fell: and great Babylon came in remembrance before God, to give unto her the cup of the wine of the fierceness of his wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 20, E'And every island fled away, and the mountains were not found.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 16, 21, E'And there fell upon men a great hail out of heaven, every stone about the weight of a talent: and men blasphemed God because of the plague of the hail; for the plague thereof was exceeding great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 1, E'And there came one of the seven angels which had the seven vials, and talked with me, saying unto me, Come hither; I will shew unto thee the judgment of the great whore that sitteth upon many waters:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 2, E'With whom the kings of the earth have committed fornication, and the inhabitants of the earth have been made drunk with the wine of her fornication.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 3, E'So he carried me away in the spirit into the wilderness: and I saw a woman sit upon a scarlet coloured beast, full of names of blasphemy, having seven heads and ten horns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 4, E'And the woman was arrayed in purple and scarlet colour, and decked with gold and precious stones and pearls, having a golden cup in her hand full of abominations and filthiness of her fornication:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 5, E'And upon her forehead was a name written, MYSTERY, BABYLON THE GREAT, THE MOTHER OF HARLOTS AND ABOMINATIONS OF THE EARTH.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 6, E'And I saw the woman drunken with the blood of the saints, and with the blood of the martyrs of Jesus: and when I saw her, I wondered with great admiration.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 7, E'And the angel said unto me, Wherefore didst thou marvel? I will tell thee the mystery of the woman, and of the beast that carrieth her, which hath the seven heads and ten horns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 8, E'The beast that thou sawest was, and is not; and shall ascend out of the bottomless pit, and go into perdition: and they that dwell on the earth shall wonder, whose names were not written in the book of life from the foundation of the world, when they behold the beast that was, and is not, and yet is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 9, E'And here is the mind which hath wisdom. The seven heads are seven mountains, on which the woman sitteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 10, E'And there are seven kings: five are fallen, and one is, and the other is not yet come; and when he cometh, he must continue a short space.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 11, E'And the beast that was, and is not, even he is the eighth, and is of the seven, and goeth into perdition.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 12, E'And the ten horns which thou sawest are ten kings, which have received no kingdom as yet; but receive power as kings one hour with the beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 13, E'These have one mind, and shall give their power and strength unto the beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 14, E'These shall make war with the Lamb, and the Lamb shall overcome them: for he is Lord of lords, and King of kings: and they that are with him are called, and chosen, and faithful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 15, E'And he saith unto me, The waters which thou sawest, where the whore sitteth, are peoples, and multitudes, and nations, and tongues.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 16, E'And the ten horns which thou sawest upon the beast, these shall hate the whore, and shall make her desolate and naked, and shall eat her flesh, and burn her with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 17, E'For God hath put in their hearts to fulfil his will, and to agree, and give their kingdom unto the beast, until the words of God shall be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 17, 18, E'And the woman which thou sawest is that great city, which reigneth over the kings of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 1, E'And after these things I saw another angel come down from heaven, having great power; and the earth was lightened with his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 2, E'And he cried mightily with a strong voice, saying, Babylon the great is fallen, is fallen, and is become the habitation of devils, and the hold of every foul spirit, and a cage of every unclean and hateful bird.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 3, E'For all nations have drunk of the wine of the wrath of her fornication, and the kings of the earth have committed fornication with her, and the merchants of the earth are waxed rich through the abundance of her delicacies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 4, E'And I heard another voice from heaven, saying, Come out of her, my people, that ye be not partakers of her sins, and that ye receive not of her plagues.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Revelation') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 5, E'For her sins have reached unto heaven, and God hath remembered her iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 6, E'Reward her even as she rewarded you, and double unto her double according to her works: in the cup which she hath filled fill to her double.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 7, E'How much she hath glorified herself, and lived deliciously, so much torment and sorrow give her: for she saith in her heart, I sit a queen, and am no widow, and shall see no sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 8, E'Therefore shall her plagues come in one day, death, and mourning, and famine; and she shall be utterly burned with fire: for strong is the Lord God who judgeth her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 9, E'And the kings of the earth, who have committed fornication and lived deliciously with her, shall bewail her, and lament for her, when they shall see the smoke of her burning,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 10, E'Standing afar off for the fear of her torment, saying, Alas, alas that great city Babylon, that mighty city! for in one hour is thy judgment come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 11, E'And the merchants of the earth shall weep and mourn over her; for no man buyeth their merchandise any more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 12, E'The merchandise of gold, and silver, and precious stones, and of pearls, and fine linen, and purple, and silk, and scarlet, and all thyine wood, and all manner vessels of ivory, and all manner vessels of most precious wood, and of brass, and iron, and marble,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 13, E'And cinnamon, and odours, and ointments, and frankincense, and wine, and oil, and fine flour, and wheat, and beasts, and sheep, and horses, and chariots, and slaves, and souls of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 14, E'And the fruits that thy soul lusted after are departed from thee, and all things which were dainty and goodly are departed from thee, and thou shalt find them no more at all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 15, E'The merchants of these things, which were made rich by her, shall stand afar off for the fear of her torment, weeping and wailing,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 16, E'And saying, Alas, alas, that great city, that was clothed in fine linen, and purple, and scarlet, and decked with gold, and precious stones, and pearls!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 17, E'For in one hour so great riches is come to nought. And every shipmaster, and all the company in ships, and sailors, and as many as trade by sea, stood afar off,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 18, E'And cried when they saw the smoke of her burning, saying, What city is like unto this great city!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 19, E'And they cast dust on their heads, and cried, weeping and wailing, saying, Alas, alas, that great city, wherein were made rich all that had ships in the sea by reason of her costliness! for in one hour is she made desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 20, E'Rejoice over her, thou heaven, and ye holy apostles and prophets; for God hath avenged you on her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 21, E'And a mighty angel took up a stone like a great millstone, and cast it into the sea, saying, Thus with violence shall that great city Babylon be thrown down, and shall be found no more at all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 22, E'And the voice of harpers, and musicians, and of pipers, and trumpeters, shall be heard no more at all in thee; and no craftsman, of whatsoever craft he be, shall be found any more in thee; and the sound of a millstone shall be heard no more at all in thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 23, E'And the light of a candle shall shine no more at all in thee; and the voice of the bridegroom and of the bride shall be heard no more at all in thee: for thy merchants were the great men of the earth; for by thy sorceries were all nations deceived.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 18, 24, E'And in her was found the blood of prophets, and of saints, and of all that were slain upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 1, E'And after these things I heard a great voice of much people in heaven, saying, Alleluia; Salvation, and glory, and honour, and power, unto the Lord our God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 2, E'For true and righteous are his judgments: for he hath judged the great whore, which did corrupt the earth with her fornication, and hath avenged the blood of his servants at her hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 3, E'And again they said, Alleluia.  And her smoke rose up for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 4, E'And the four and twenty elders and the four beasts fell down and worshipped God that sat on the throne, saying, Amen; Alleluia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 5, E'And a voice came out of the throne, saying, Praise our God, all ye his servants, and ye that fear him, both small and great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 6, E'And I heard as it were the voice of a great multitude, and as the voice of many waters, and as the voice of mighty thunderings, saying, Alleluia: for the Lord God omnipotent reigneth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 7, E'Let us be glad and rejoice, and give honour to him: for the marriage of the Lamb is come, and his wife hath made herself ready.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 8, E'And to her was granted that she should be arrayed in fine linen, clean and white: for the fine linen is the righteousness of saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 9, E'And he saith unto me, Write, Blessed are they which are called unto the marriage supper of the Lamb. And he saith unto me, These are the true sayings of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 10, E'And I fell at his feet to worship him. And he said unto me, See thou do it not: I am thy fellowservant, and of thy brethren that have the testimony of Jesus: worship God: for the testimony of Jesus is the spirit of prophecy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 11, E'And I saw heaven opened, and behold a white horse; and he that sat upon him was called Faithful and True, and in righteousness he doth judge and make war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 12, E'His eyes were as a flame of fire, and on his head were many crowns; and he had a name written, that no man knew, but he himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 13, E'And he was clothed with a vesture dipped in blood: and his name is called The Word of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 14, E'And the armies which were in heaven followed him upon white horses, clothed in fine linen, white and clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 15, E'And out of his mouth goeth a sharp sword, that with it he should smite the nations: and he shall rule them with a rod of iron: and he treadeth the winepress of the fierceness and wrath of Almighty God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 16, E'And he hath on his vesture and on his thigh a name written, KING OF KINGS, AND LORD OF LORDS.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 17, E'And I saw an angel standing in the sun; and he cried with a loud voice, saying to all the fowls that fly in the midst of heaven, Come and gather yourselves together unto the supper of the great God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 18, E'That ye may eat the flesh of kings, and the flesh of captains, and the flesh of mighty men, and the flesh of horses, and of them that sit on them, and the flesh of all men, both free and bond, both small and great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 19, E'And I saw the beast, and the kings of the earth, and their armies, gathered together to make war against him that sat on the horse, and against his army.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 20, E'And the beast was taken, and with him the false prophet that wrought miracles before him, with which he deceived them that had received the mark of the beast, and them that worshipped his image. These both were cast alive into a lake of fire burning with brimstone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 19, 21, E'And the remnant were slain with the sword of him that sat upon the horse, which sword proceeded out of his mouth: and all the fowls were filled with their flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 1, E'And I saw an angel come down from heaven, having the key of the bottomless pit and a great chain in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 2, E'And he laid hold on the dragon, that old serpent, which is the Devil, and Satan, and bound him a thousand years,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 3, E'And cast him into the bottomless pit, and shut him up, and set a seal upon him, that he should deceive the nations no more, till the thousand years should be fulfilled: and after that he must be loosed a little season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 4, E'And I saw thrones, and they sat upon them, and judgment was given unto them: and I saw the souls of them that were beheaded for the witness of Jesus, and for the word of God, and which had not worshipped the beast, neither his image, neither had received his mark upon their foreheads, or in their hands; and they lived and reigned with Christ a thousand years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 5, E'But the rest of the dead lived not again until the thousand years were finished. This is the first resurrection.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 6, E'Blessed and holy is he that hath part in the first resurrection: on such the second death hath no power, but they shall be priests of God and of Christ, and shall reign with him a thousand years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 7, E'And when the thousand years are expired, Satan shall be loosed out of his prison,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 8, E'And shall go out to deceive the nations which are in the four quarters of the earth, Gog and Magog, to gather them together to battle: the number of whom is as the sand of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 9, E'And they went up on the breadth of the earth, and compassed the camp of the saints about, and the beloved city: and fire came down from God out of heaven, and devoured them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 10, E'And the devil that deceived them was cast into the lake of fire and brimstone, where the beast and the false prophet are, and shall be tormented day and night for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 11, E'And I saw a great white throne, and him that sat on it, from whose face the earth and the heaven fled away; and there was found no place for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 12, E'And I saw the dead, small and great, stand before God; and the books were opened: and another book was opened, which is the book of life: and the dead were judged out of those things which were written in the books, according to their works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 13, E'And the sea gave up the dead which were in it; and death and hell delivered up the dead which were in them: and they were judged every man according to their works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 14, E'And death and hell were cast into the lake of fire. This is the second death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 20, 15, E'And whosoever was not found written in the book of life was cast into the lake of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 1, E'And I saw a new heaven and a new earth: for the first heaven and the first earth were passed away; and there was no more sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 2, E'And I John saw the holy city, new Jerusalem, coming down from God out of heaven, prepared as a bride adorned for her husband.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 3, E'And I heard a great voice out of heaven saying, Behold, the tabernacle of God is with men, and he will dwell with them, and they shall be his people, and God himself shall be with them, and be their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 4, E'And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 5, E'And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 6, E'And he said unto me, It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 7, E'He that overcometh shall inherit all things; and I will be his God, and he shall be my son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 8, E'But the fearful, and unbelieving, and the abominable, and murderers, and whoremongers, and sorcerers, and idolaters, and all liars, shall have their part in the lake which burneth with fire and brimstone: which is the second death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 9, E'And there came unto me one of the seven angels which had the seven vials full of the seven last plagues, and talked with me, saying, Come hither, I will shew thee the bride, the Lambâ€™s wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 10, E'And he carried me away in the spirit to a great and high mountain, and shewed me that great city, the holy Jerusalem, descending out of heaven from God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 11, E'Having the glory of God: and her light was like unto a stone most precious, even like a jasper stone, clear as crystal;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 12, E'And had a wall great and high, and had twelve gates, and at the gates twelve angels, and names written thereon, which are the names of the twelve tribes of the children of Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 13, E'On the east three gates; on the north three gates; on the south three gates; and on the west three gates.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 14, E'And the wall of the city had twelve foundations, and in them the names of the twelve apostles of the Lamb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 15, E'And he that talked with me had a golden reed to measure the city, and the gates thereof, and the wall thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 16, E'And the city lieth foursquare, and the length is as large as the breadth: and he measured the city with the reed, twelve thousand furlongs. The length and the breadth and the height of it are equal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 17, E'And he measured the wall thereof, an hundred and forty and four cubits, according to the measure of a man, that is, of the angel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 18, E'And the building of the wall of it was of jasper: and the city was pure gold, like unto clear glass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 19, E'And the foundations of the wall of the city were garnished with all manner of precious stones. The first foundation was jasper; the second, sapphire; the third, a chalcedony; the fourth, an emerald;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 20, E'The fifth, sardonyx; the sixth, sardius; the seventh, chrysolyte; the eighth, beryl; the ninth, a topaz; the tenth, a chrysoprasus; the eleventh, a jacinth; the twelfth, an amethyst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 21, E'And the twelve gates were twelve pearls: every several gate was of one pearl: and the street of the city was pure gold, as it were transparent glass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 22, E'And I saw no temple therein: for the Lord God Almighty and the Lamb are the temple of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 23, E'And the city had no need of the sun, neither of the moon, to shine in it: for the glory of God did lighten it, and the Lamb is the light thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 24, E'And the nations of them which are saved shall walk in the light of it: and the kings of the earth do bring their glory and honour into it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 25, E'And the gates of it shall not be shut at all by day: for there shall be no night there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 26, E'And they shall bring the glory and honour of the nations into it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 21, 27, E'And there shall in no wise enter into it any thing that defileth, neither whatsoever worketh abomination, or maketh a lie: but they which are written in the Lambâ€™s book of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 1, E'And he shewed me a pure river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 2, E'In the midst of the street of it, and on either side of the river, was there the tree of life, which bare twelve manner of fruits, and yielded her fruit every month: and the leaves of the tree were for the healing of the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 3, E'And there shall be no more curse: but the throne of God and of the Lamb shall be in it; and his servants shall serve him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 4, E'And they shall see his face; and his name shall be in their foreheads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 5, E'And there shall be no night there; and they need no candle, neither light of the sun; for the Lord God giveth them light: and they shall reign for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 6, E'And he said unto me, These sayings are faithful and true: and the Lord God of the holy prophets sent his angel to shew unto his servants the things which must shortly be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 7, E'Behold, I come quickly: blessed is he that keepeth the sayings of the prophecy of this book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 8, E'And I John saw these things, and heard them. And when I had heard and seen, I fell down to worship before the feet of the angel which shewed me these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 9, E'Then saith he unto me, See thou do it not: for I am thy fellowservant, and of thy brethren the prophets, and of them which keep the sayings of this book: worship God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 10, E'And he saith unto me, Seal not the sayings of the prophecy of this book: for the time is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 11, E'He that is unjust, let him be unjust still: and he which is filthy, let him be filthy still: and he that is righteous, let him be righteous still: and he that is holy, let him be holy still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 12, E'And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 13, E'I am Alpha and Omega, the beginning and the end, the first and the last.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 14, E'Blessed are they that do his commandments, that they may have right to the tree of life, and may enter in through the gates into the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 15, E'For without are dogs, and sorcerers, and whoremongers, and murderers, and idolaters, and whosoever loveth and maketh a lie.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 16, E'I Jesus have sent mine angel to testify unto you these things in the churches. I am the root and the offspring of David, and the bright and morning star.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 17, E'And the Spirit and the bride say, Come. And let him that heareth say, Come. And let him that is athirst come. And whosoever will, let him take the water of life freely.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Revelation') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 18, E'For I testify unto every man that heareth the words of the prophecy of this book, If any man shall add unto these things, God shall add unto him the plagues that are written in this book:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 19, E'And if any man shall take away from the words of the book of this prophecy, God shall take away his part out of the book of life, and out of the holy city, and from the things which are written in this book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 20, E'He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fec01bcf-1102-46f0-8e99-fb646d339dd8', 22, 21, E'The grace of our Lord Jesus Christ be with you all. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Revelation') b
ON CONFLICT DO NOTHING;

